-- Moneybags Modules 1-10: installation in your EXISTING Oracle schema.
-- Oracle Database 19c+. In SQL Developer, connect as ALPHA (or your own account)
-- and run this whole file with F5. New database users and passwords are not needed.
-- Tables retain module ownership in their names through M01_ through M10_.
-- All objects use one database owner; separate schema access boundaries are absent.
-- Fresh installation only. An error can leave objects already created by Oracle DDL.
-- M01: IAM
-- M02: CIF_KYC
-- M03: PRODUCT_MASTER
-- M04: ACCOUNT_MGMT
-- M05: MB_TXN
-- M06: MB_PAY
-- M07: MB_TREASURY
-- M08: MB_LOAN
-- M09: MB_PRIVACY
-- M10: MB_STATEMENT_REPORTING
-- COMPLETE EDITION: requires CREATE TABLE, CREATE VIEW, CREATE TRIGGER,
-- CREATE SEQUENCE, and available tablespace quota in your own schema.
-- Preserves the enhanced schema's triggers, views, and sequences.

SET DEFINE OFF
SET ECHO OFF
SET VERIFY OFF
SET FEEDBACK ON
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

-- Checks use views available to the current user; no DBA views or user creation.
DECLARE
  n NUMBER;
  storage_tablespace VARCHAR2(128);
BEGIN
  IF SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA') <> SYS_CONTEXT('USERENV', 'SESSION_USER') THEN
    RAISE_APPLICATION_ERROR(-20100, 'Use your own schema: CURRENT_SCHEMA must match SESSION_USER.');
  END IF;
  FOR p IN (
      SELECT 'CREATE TABLE' AS required_privilege FROM dual
      UNION ALL SELECT 'CREATE VIEW' AS required_privilege FROM dual
      UNION ALL SELECT 'CREATE TRIGGER' AS required_privilege FROM dual
      UNION ALL SELECT 'CREATE SEQUENCE' AS required_privilege FROM dual
  ) LOOP
    SELECT COUNT(*) INTO n FROM session_privs
    WHERE privilege = p.required_privilege
       OR privilege = REPLACE(p.required_privilege, 'CREATE ', 'CREATE ANY ');
    IF n = 0 THEN
      RAISE_APPLICATION_ERROR(-20101, 'Your account needs ' || p.required_privilege || ' for this installer.');
    END IF;
  END LOOP;
  SELECT default_tablespace INTO storage_tablespace FROM user_users;
  SELECT COUNT(*) INTO n FROM session_privs WHERE privilege = 'UNLIMITED TABLESPACE';
  IF n = 0 THEN
    SELECT COUNT(*) INTO n FROM user_ts_quotas
    WHERE tablespace_name = storage_tablespace AND (max_bytes = -1 OR max_bytes > bytes);
    IF n = 0 THEN
      RAISE_APPLICATION_ERROR(-20102, 'Your account needs available quota on ' || storage_tablespace || '.');
    END IF;
  END IF;
  SELECT COUNT(*) INTO n FROM user_objects WHERE (object_name IN ('M01_IAM_ACCESS_REQUEST',
      'M01_IAM_ACCESS_REQUEST_SCOPE',
      'M01_IAM_ASSIGN_IX_USER',
      'M01_IAM_AUDIT_EVENT',
