CREATE TABLE M01_IAM_USER (
  USER_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USERNAME VARCHAR2(120 CHAR) NOT NULL,
  USER_TYPE VARCHAR2(12 CHAR) NOT NULL,
  STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING_ACTIVATION' NOT NULL,
  EMPLOYEE_REF VARCHAR2(80 CHAR),
  ENTITLEMENT_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_IAM_USER_CK_TYPE CHECK (USER_TYPE IN ('CUSTOMER','EMPLOYEE','SERVICE')),
  CONSTRAINT MB_IAM_USER_CK_STATUS CHECK (STATUS IN ('PENDING_ACTIVATION','ACTIVE','AUTH_LOCKED','SUSPENDED','DISABLED','CLOSED')),
  CONSTRAINT MB_IAM_USER_CK_EMPLOYEE CHECK ((USER_TYPE = 'EMPLOYEE' AND EMPLOYEE_REF IS NOT NULL) OR (USER_TYPE <> 'EMPLOYEE' AND EMPLOYEE_REF IS NULL))
);
CREATE UNIQUE INDEX M01_IAM_USER_UQ_USERNAME_KEY ON M01_IAM_USER(UPPER(USERNAME));

CREATE TABLE M01_IAM_CREDENTIAL (
  CREDENTIAL_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  PASSWORD_HASH VARCHAR2(512 CHAR) NOT NULL,
  HASH_SCHEME VARCHAR2(40 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  FAILED_ATTEMPTS NUMBER(5) DEFAULT 0 NOT NULL,
  LOCKED_UNTIL TIMESTAMP(6) WITH TIME ZONE,
  CHANGED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_IAM_CRED_UQ_USER UNIQUE (USER_ID),
  CONSTRAINT MB_IAM_CRED_CK_STATUS CHECK (STATUS IN ('ACTIVE','RESET_REQUIRED','REVOKED')),
  CONSTRAINT MB_IAM_CRED_CK_FAILURES CHECK (FAILED_ATTEMPTS >= 0)
);

CREATE TABLE M01_IAM_AUTH_FACTOR (
  FACTOR_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  FACTOR_TYPE VARCHAR2(12 CHAR) NOT NULL,
  FACTOR_REF VARCHAR2(240 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  ENROLLED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  VERIFIED_AT TIMESTAMP(6) WITH TIME ZONE,
  REVOKED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_IAM_FACTOR_UQ_REF UNIQUE (FACTOR_TYPE, FACTOR_REF),
  CONSTRAINT MB_IAM_FACTOR_CK_TYPE CHECK (FACTOR_TYPE IN ('TOTP','WEBAUTHN','RECOVERY')),
  CONSTRAINT MB_IAM_FACTOR_CK_STATUS CHECK (STATUS IN ('PENDING','ACTIVE','REVOKED'))
);

CREATE TABLE M01_IAM_CUSTOMER_LINK (
  LINK_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  RELATIONSHIP_TYPE VARCHAR2(24 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  VALID_FROM_UTC TIMESTAMP(6) GENERATED ALWAYS AS (SYS_EXTRACT_UTC(VALID_FROM)) VIRTUAL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_IAM_LINK_UQ UNIQUE (USER_ID, CIF_ID, RELATIONSHIP_TYPE, VALID_FROM_UTC),
  CONSTRAINT MB_IAM_LINK_CK_STATUS CHECK (STATUS IN ('ACTIVE','REVOKED')),
  CONSTRAINT MB_IAM_LINK_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M01_IAM_LINK_IX_CIF ON M01_IAM_CUSTOMER_LINK(CIF_ID, STATUS);

CREATE TABLE M01_IAM_ROLE (
  ROLE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  ROLE_CODE VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  DISPLAY_NAME VARCHAR2(120 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  SENSITIVE_FLAG CHAR(1) DEFAULT 'N' NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_IAM_ROLE_CK_STATUS CHECK (STATUS IN ('ACTIVE','RETIRED')),
  CONSTRAINT MB_IAM_ROLE_CK_SENSITIVE CHECK (SENSITIVE_FLAG IN ('Y','N'))
);

CREATE TABLE M01_IAM_PERMISSION (
  PERMISSION_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PERMISSION_CODE VARCHAR2(100 CHAR) NOT NULL UNIQUE,
  RESOURCE_CODE VARCHAR2(60 CHAR) NOT NULL,
  ACTION_CODE VARCHAR2(60 CHAR) NOT NULL,
  STEP_UP_REQUIRED CHAR(1) DEFAULT 'N' NOT NULL,
  CONSTRAINT MB_IAM_PERM_CK_STEPUP CHECK (STEP_UP_REQUIRED IN ('Y','N'))
);

CREATE TABLE M01_IAM_ROLE_PERMISSION (
  ROLE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_ROLE(ROLE_ID),
  PERMISSION_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_PERMISSION(PERMISSION_ID),
  PRIMARY KEY (ROLE_ID, PERMISSION_ID)
);

-- Limits attached to IAM roles; Product Master queries IAM for the caller's
-- permission, assignment scope, and approval authority at decision time.
CREATE TABLE M01_IAM_ROLE_AUTHORITY (
  AUTHORITY_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  ROLE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_ROLE(ROLE_ID),
  AUTHORITY_CODE VARCHAR2(80 CHAR) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) DEFAULT '*' NOT NULL,
  MAX_AMOUNT NUMBER(20,4),
  MAX_RATE_PCT NUMBER(12,8),
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_FROM_UTC TIMESTAMP(6) GENERATED ALWAYS AS (SYS_EXTRACT_UTC(VALID_FROM)) VIRTUAL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_IAM_AUTH_CK_VALUE CHECK (MAX_AMOUNT IS NOT NULL OR MAX_RATE_PCT IS NOT NULL),
  CONSTRAINT MB_IAM_AUTH_CK_AMOUNT CHECK (MAX_AMOUNT IS NULL OR MAX_AMOUNT >= 0),
  CONSTRAINT MB_IAM_AUTH_CK_RATE CHECK (MAX_RATE_PCT IS NULL OR MAX_RATE_PCT >= 0),
  CONSTRAINT MB_IAM_AUTH_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM),
  CONSTRAINT MB_IAM_AUTH_UQ UNIQUE (ROLE_ID, AUTHORITY_CODE, CURRENCY_CODE, VALID_FROM_UTC)
);

CREATE TABLE M01_IAM_ACCESS_REQUEST (
  REQUEST_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  TARGET_USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  ROLE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_ROLE(ROLE_ID),
  CHANGE_TYPE VARCHAR2(8 CHAR) NOT NULL,
  TARGET_ASSIGNMENT_ID VARCHAR2(36 CHAR),
  SCOPE_TYPE VARCHAR2(12 CHAR) NOT NULL,
  SCOPE_REF VARCHAR2(80 CHAR),
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  REASON VARCHAR2(500 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'SUBMITTED' NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  MAKER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_USER_ID VARCHAR2(36 CHAR) REFERENCES M01_IAM_USER(USER_ID),
  CHECKER_SESSION_ID VARCHAR2(36 CHAR),
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_IAM_REQ_CK_CHANGE CHECK (CHANGE_TYPE IN ('GRANT','REVOKE')),
  CONSTRAINT MB_IAM_REQ_CK_TARGET CHECK ((CHANGE_TYPE = 'GRANT' AND TARGET_ASSIGNMENT_ID IS NULL) OR (CHANGE_TYPE = 'REVOKE' AND TARGET_ASSIGNMENT_ID IS NOT NULL)),
  CONSTRAINT MB_IAM_REQ_CK_SCOPE CHECK (SCOPE_TYPE IN ('SELF','BRANCH','REGION','GLOBAL')),
  CONSTRAINT MB_IAM_REQ_CK_SCOPE_REF CHECK ((SCOPE_TYPE IN ('SELF','GLOBAL') AND SCOPE_REF IS NULL) OR (SCOPE_TYPE IN ('BRANCH','REGION') AND SCOPE_REF IS NOT NULL)),
  CONSTRAINT MB_IAM_REQ_CK_STATUS CHECK (STATUS IN ('SUBMITTED','APPROVED','REJECTED','EXPIRED')),
  CONSTRAINT MB_IAM_REQ_CK_CHECKER CHECK (CHECKER_USER_ID IS NULL OR CHECKER_USER_ID <> MAKER_USER_ID),
  CONSTRAINT MB_IAM_REQ_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM),
  CONSTRAINT MB_IAM_REQ_CK_DECISION CHECK (
    (STATUS = 'SUBMITTED' AND CHECKER_USER_ID IS NULL AND CHECKER_SESSION_ID IS NULL AND DECIDED_AT IS NULL) OR
    (STATUS IN ('APPROVED','REJECTED') AND CHECKER_USER_ID IS NOT NULL AND CHECKER_SESSION_ID IS NOT NULL AND DECIDED_AT IS NOT NULL) OR
    (STATUS = 'EXPIRED' AND DECIDED_AT IS NOT NULL)
  )
);

CREATE TABLE M01_IAM_USER_ROLE (
  ASSIGNMENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  ROLE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_ROLE(ROLE_ID),
  SCOPE_TYPE VARCHAR2(12 CHAR) NOT NULL,
  SCOPE_REF VARCHAR2(80 CHAR),
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_REQUEST_ID VARCHAR2(36 CHAR) REFERENCES M01_IAM_ACCESS_REQUEST(REQUEST_ID),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_IAM_ASSIGN_CK_SCOPE CHECK (SCOPE_TYPE IN ('SELF','BRANCH','REGION','GLOBAL')),
  CONSTRAINT MB_IAM_ASSIGN_CK_SCOPE_REF CHECK ((SCOPE_TYPE IN ('SELF','GLOBAL') AND SCOPE_REF IS NULL) OR (SCOPE_TYPE IN ('BRANCH','REGION') AND SCOPE_REF IS NOT NULL)),
  CONSTRAINT MB_IAM_ASSIGN_CK_STATUS CHECK (STATUS IN ('ACTIVE','REVOKED','EXPIRED')),
  CONSTRAINT MB_IAM_ASSIGN_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M01_IAM_ASSIGN_IX_USER ON M01_IAM_USER_ROLE(USER_ID, STATUS, VALID_TO);
ALTER TABLE M01_IAM_ACCESS_REQUEST ADD CONSTRAINT MB_IAM_REQ_FK_ASSIGNMENT
  FOREIGN KEY (TARGET_ASSIGNMENT_ID) REFERENCES M01_IAM_USER_ROLE(ASSIGNMENT_ID);

-- Additional dimensions narrow a product-administration assignment. Values
-- for the same dimension are alternatives; different dimensions intersect.
CREATE TABLE M01_IAM_USER_ROLE_SCOPE (
  ASSIGNMENT_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER_ROLE(ASSIGNMENT_ID),
  DIMENSION_CODE VARCHAR2(20 CHAR) NOT NULL,
  SCOPE_VALUE VARCHAR2(80 CHAR) NOT NULL,
  PRIMARY KEY (ASSIGNMENT_ID, DIMENSION_CODE, SCOPE_VALUE),
  CONSTRAINT MB_IAM_SCOPE_CK_DIMENSION CHECK (DIMENSION_CODE IN ('PRODUCT_TYPE','CURRENCY'))
);

-- The request keeps the exact scoped authority reviewed by the checker.
CREATE TABLE M01_IAM_ACCESS_REQUEST_SCOPE (
  REQUEST_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_ACCESS_REQUEST(REQUEST_ID),
  DIMENSION_CODE VARCHAR2(20 CHAR) NOT NULL,
  SCOPE_VALUE VARCHAR2(80 CHAR) NOT NULL,
  PRIMARY KEY (REQUEST_ID, DIMENSION_CODE, SCOPE_VALUE),
  CONSTRAINT MB_IAM_REQ_SCOPE_CK_DIMENSION CHECK (DIMENSION_CODE IN ('PRODUCT_TYPE','CURRENCY'))
);

CREATE TABLE M01_IAM_SESSION (
  SESSION_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  USER_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_USER(USER_ID),
  CLIENT_ID VARCHAR2(80 CHAR) NOT NULL,
  DEVICE_REF VARCHAR2(160 CHAR),
  AUTH_LEVEL VARCHAR2(20 CHAR) NOT NULL,
  STATUS VARCHAR2(20 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  LAST_ACTIVITY_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  IDLE_EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  ABSOLUTE_EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  ENDED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_IAM_SESSION_CK_STATUS CHECK (STATUS IN ('ACTIVE','EXPIRED','REVOKED','COMPROMISED','POLICY_TERMINATED')),
  CONSTRAINT MB_IAM_SESSION_CK_EXPIRY CHECK (ABSOLUTE_EXPIRES_AT > CREATED_AT AND IDLE_EXPIRES_AT > CREATED_AT)
);
CREATE INDEX M01_IAM_SESSION_IX_USER ON M01_IAM_SESSION(USER_ID, STATUS);
ALTER TABLE M01_IAM_ACCESS_REQUEST ADD CONSTRAINT MB_IAM_REQ_FK_MAKER_SESSION
  FOREIGN KEY (MAKER_SESSION_ID) REFERENCES M01_IAM_SESSION(SESSION_ID);
ALTER TABLE M01_IAM_ACCESS_REQUEST ADD CONSTRAINT MB_IAM_REQ_FK_CHECKER_SESSION
  FOREIGN KEY (CHECKER_SESSION_ID) REFERENCES M01_IAM_SESSION(SESSION_ID);

CREATE TABLE M01_IAM_REFRESH_TOKEN (
  TOKEN_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  SESSION_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M01_IAM_SESSION(SESSION_ID),
  FAMILY_ID VARCHAR2(36 CHAR) NOT NULL,
  TOKEN_HASH VARCHAR2(128 CHAR) NOT NULL UNIQUE,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  ISSUED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  USED_AT TIMESTAMP(6) WITH TIME ZONE,
  REPLACED_BY_TOKEN_ID VARCHAR2(36 CHAR),
  CONSTRAINT MB_IAM_REFRESH_CK_STATUS CHECK (STATUS IN ('ACTIVE','USED','REVOKED','REUSED')),
  CONSTRAINT MB_IAM_REFRESH_CK_EXPIRY CHECK (EXPIRES_AT > ISSUED_AT)
);
ALTER TABLE M01_IAM_REFRESH_TOKEN ADD CONSTRAINT MB_IAM_REFRESH_FK_REPLACED
  FOREIGN KEY (REPLACED_BY_TOKEN_ID) REFERENCES M01_IAM_REFRESH_TOKEN(TOKEN_ID);
CREATE INDEX M01_IAM_REFRESH_IX_FAMILY ON M01_IAM_REFRESH_TOKEN(FAMILY_ID, STATUS);

CREATE TABLE M01_IAM_MENU_ITEM (
  MENU_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CLIENT_ID VARCHAR2(80 CHAR) NOT NULL,
  PARENT_MENU_ID VARCHAR2(36 CHAR) REFERENCES M01_IAM_MENU_ITEM(MENU_ID),
  ROUTE_PATH VARCHAR2(240 CHAR) NOT NULL,
  LABEL_KEY VARCHAR2(120 CHAR) NOT NULL,
  SORT_ORDER NUMBER(5) NOT NULL,
  REQUIRED_PERMISSION_ID VARCHAR2(36 CHAR) REFERENCES M01_IAM_PERMISSION(PERMISSION_ID),
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  CONSTRAINT MB_IAM_MENU_UQ_ROUTE UNIQUE (CLIENT_ID, ROUTE_PATH),
  CONSTRAINT MB_IAM_MENU_CK_STATUS CHECK (STATUS IN ('ACTIVE','HIDDEN'))
);

CREATE TABLE M01_IAM_AUDIT_EVENT (
  AUDIT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  ACTOR_USER_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  RESOURCE_TYPE VARCHAR2(60 CHAR),
  RESOURCE_ID VARCHAR2(80 CHAR),
  RESULT VARCHAR2(12 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR),
  MAKER_USER_ID VARCHAR2(36 CHAR),
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  BEFORE_STATE_HASH CHAR(64),
  AFTER_STATE_HASH CHAR(64),
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_IAM_AUDIT_CK_RESULT CHECK (RESULT IN ('SUCCESS','DENIED','FAILED'))
);
CREATE INDEX M01_IAM_AUDIT_IX_TIME ON M01_IAM_AUDIT_EVENT(OCCURRED_AT);

CREATE TABLE M01_IAM_OUTBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(40 CHAR) DEFAULT 'IAM' NOT NULL,
  SCHEMA_VERSION NUMBER(5) NOT NULL,
  AGGREGATE_TYPE VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(36 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  PAYLOAD CLOB NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  ATTEMPT_COUNT NUMBER(6) DEFAULT 0 NOT NULL,
  CONSTRAINT MB_IAM_OUTBOX_CK_JSON CHECK (PAYLOAD IS JSON),
  CONSTRAINT MB_IAM_OUTBOX_CK_ATTEMPTS CHECK (ATTEMPT_COUNT >= 0)
);
CREATE INDEX M01_IAM_OUTBOX_IX_PENDING ON M01_IAM_OUTBOX_EVENT(PUBLISHED_AT, OCCURRED_AT);

CREATE TABLE M01_IAM_INBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(36 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE
);

-- CIF/KYC service tables
CREATE TABLE M02_CIF_PARTY (
  PARTY_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PARTY_TYPE VARCHAR2(16 CHAR) NOT NULL,
  DATE_OF_BIRTH DATE,
  INCORPORATED_ON DATE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_CIF_PARTY_CK_TYPE CHECK (PARTY_TYPE IN ('INDIVIDUAL','ORGANIZATION')),
  CONSTRAINT MB_CIF_PARTY_CK_DATES CHECK ((PARTY_TYPE = 'INDIVIDUAL' AND INCORPORATED_ON IS NULL) OR (PARTY_TYPE = 'ORGANIZATION' AND DATE_OF_BIRTH IS NULL))
);

CREATE TABLE M02_CIF_CUSTOMER (
  CIF_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CIF_NUMBER VARCHAR2(40 CHAR) NOT NULL UNIQUE,
  PARTY_ID VARCHAR2(36 CHAR) NOT NULL UNIQUE REFERENCES M02_CIF_PARTY(PARTY_ID),
  STATUS VARCHAR2(24 CHAR) DEFAULT 'PROSPECT' NOT NULL,
  HOME_BRANCH_REF VARCHAR2(80 CHAR) NOT NULL,
  SEGMENT_CODE VARCHAR2(40 CHAR),
  KYC_STATUS VARCHAR2(16 CHAR) DEFAULT 'NOT_STARTED' NOT NULL,
  RISK_LEVEL VARCHAR2(8 CHAR),
  NEXT_REVIEW_DUE_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_CIF_CUSTOMER_CK_STATUS CHECK (STATUS IN ('PROSPECT','PENDING_VERIFICATION','ACTIVE','RESTRICTED','DORMANT','CLOSED')),
  CONSTRAINT MB_CIF_CUSTOMER_CK_KYC CHECK (KYC_STATUS IN ('NOT_STARTED','PENDING','VERIFIED','REJECTED','EXPIRED')),
  CONSTRAINT MB_CIF_CUSTOMER_CK_RISK CHECK (RISK_LEVEL IS NULL OR RISK_LEVEL IN ('LOW','MEDIUM','HIGH'))
);
CREATE INDEX M02_CIF_CUSTOMER_IX_BRANCH ON M02_CIF_CUSTOMER(HOME_BRANCH_REF, STATUS);

CREATE TABLE M02_CIF_NAME (
  NAME_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  NAME_TYPE VARCHAR2(16 CHAR) NOT NULL,
  FULL_NAME VARCHAR2(300 CHAR) NOT NULL,
  VERIFICATION_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CIF_NAME_CK_TYPE CHECK (NAME_TYPE IN ('LEGAL','PREFERRED','FORMER')),
  CONSTRAINT MB_CIF_NAME_CK_VERIFY CHECK (VERIFICATION_STATUS IN ('PENDING','VERIFIED','REJECTED')),
  CONSTRAINT MB_CIF_NAME_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M02_CIF_NAME_IX_PARTY ON M02_CIF_NAME(PARTY_ID, NAME_TYPE, VALID_TO);

CREATE TABLE M02_CIF_CONTACT (
  CONTACT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  CONTACT_TYPE VARCHAR2(8 CHAR) NOT NULL,
  VALUE_CIPHERTEXT BLOB NOT NULL,
  DISPLAY_HINT VARCHAR2(100 CHAR) NOT NULL,
  VERIFICATION_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  VERIFIED_AT TIMESTAMP(6) WITH TIME ZONE,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CIF_CONTACT_CK_TYPE CHECK (CONTACT_TYPE IN ('MOBILE','EMAIL')),
  CONSTRAINT MB_CIF_CONTACT_CK_VERIFY CHECK (VERIFICATION_STATUS IN ('PENDING','VERIFIED','REJECTED')),
  CONSTRAINT MB_CIF_CONTACT_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M02_CIF_CONTACT_IX_PARTY ON M02_CIF_CONTACT(PARTY_ID, CONTACT_TYPE, VALID_TO);

CREATE TABLE M02_CIF_ADDRESS (
  ADDRESS_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  ADDRESS_TYPE VARCHAR2(16 CHAR) NOT NULL,
  LINE1 VARCHAR2(240 CHAR) NOT NULL,
  LINE2 VARCHAR2(240 CHAR),
  CITY VARCHAR2(120 CHAR) NOT NULL,
  REGION VARCHAR2(120 CHAR),
  POSTAL_CODE VARCHAR2(24 CHAR),
  COUNTRY_CODE CHAR(2) NOT NULL,
  VERIFICATION_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  EVIDENCE_DOCUMENT_ID VARCHAR2(36 CHAR),
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CIF_ADDRESS_CK_TYPE CHECK (ADDRESS_TYPE IN ('RESIDENTIAL','MAILING','REGISTERED')),
  CONSTRAINT MB_CIF_ADDRESS_CK_VERIFY CHECK (VERIFICATION_STATUS IN ('PENDING','VERIFIED','REJECTED')),
  CONSTRAINT MB_CIF_ADDRESS_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M02_CIF_ADDRESS_IX_PARTY ON M02_CIF_ADDRESS(PARTY_ID, ADDRESS_TYPE, VALID_TO);

CREATE TABLE M02_CIF_IDENTIFIER (
  IDENTIFIER_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  IDENTIFIER_TYPE VARCHAR2(40 CHAR) NOT NULL,
  VALUE_CIPHERTEXT BLOB NOT NULL,
  DISPLAY_HINT VARCHAR2(100 CHAR) NOT NULL,
  LOOKUP_HMAC VARCHAR2(128 CHAR) NOT NULL,
  ISSUER_CODE VARCHAR2(80 CHAR),
  EXPIRES_ON DATE,
  VERIFICATION_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CIF_IDENT_UQ_LOOKUP UNIQUE (IDENTIFIER_TYPE, LOOKUP_HMAC),
  CONSTRAINT MB_CIF_IDENT_CK_VERIFY CHECK (VERIFICATION_STATUS IN ('PENDING','VERIFIED','REJECTED')),
  CONSTRAINT MB_CIF_IDENT_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M02_CIF_IDENT_IX_PARTY ON M02_CIF_IDENTIFIER(PARTY_ID, IDENTIFIER_TYPE);

CREATE TABLE M02_CIF_RELATIONSHIP (
  RELATIONSHIP_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  SOURCE_PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  TARGET_PARTY_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_PARTY(PARTY_ID),
  RELATIONSHIP_TYPE VARCHAR2(32 CHAR) NOT NULL,
  OPERATING_AUTHORITY VARCHAR2(32 CHAR) DEFAULT 'NONE' NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CIF_REL_CK_SELF CHECK (SOURCE_PARTY_ID <> TARGET_PARTY_ID),
  CONSTRAINT MB_CIF_REL_CK_AUTH CHECK (OPERATING_AUTHORITY IN ('NONE','VIEW','TRANSACT','REPRESENT')),
  CONSTRAINT MB_CIF_REL_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
CREATE INDEX M02_CIF_REL_IX_TARGET ON M02_CIF_RELATIONSHIP(TARGET_PARTY_ID, RELATIONSHIP_TYPE, VALID_TO);

CREATE TABLE M02_KYC_CASE (
  CASE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CIF_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_CUSTOMER(CIF_ID),
  CASE_TYPE VARCHAR2(16 CHAR) NOT NULL,
  STATUS VARCHAR2(28 CHAR) DEFAULT 'DRAFT' NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  ASSIGNED_OFFICER_USER_ID VARCHAR2(36 CHAR),
  RISK_LEVEL VARCHAR2(8 CHAR),
  SUBMITTED_AT TIMESTAMP(6) WITH TIME ZONE,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  REVIEW_DUE_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_KYC_CASE_CK_TYPE CHECK (CASE_TYPE IN ('ONBOARDING','PERIODIC','REMEDIATION')),
  CONSTRAINT MB_KYC_CASE_CK_STATUS CHECK (STATUS IN ('DRAFT','DOCUMENTS_PENDING','SUBMITTED','UNDER_REVIEW','MORE_INFO_REQUIRED','APPROVED','REJECTED','EXPIRED')),
  CONSTRAINT MB_KYC_CASE_CK_RISK CHECK (RISK_LEVEL IS NULL OR RISK_LEVEL IN ('LOW','MEDIUM','HIGH'))
);
CREATE INDEX M02_KYC_CASE_IX_CIF ON M02_KYC_CASE(CIF_ID, CREATED_AT);
CREATE INDEX M02_KYC_CASE_IX_QUEUE ON M02_KYC_CASE(STATUS, ASSIGNED_OFFICER_USER_ID, REVIEW_DUE_AT);

CREATE TABLE M02_KYC_DOCUMENT (
  DOCUMENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CASE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_KYC_CASE(CASE_ID),
  DOCUMENT_TYPE VARCHAR2(40 CHAR) NOT NULL,
  VERSION_NO NUMBER(5) NOT NULL,
  STORAGE_REF VARCHAR2(500 CHAR) NOT NULL,
  SHA256_HEX CHAR(64) NOT NULL,
  MIME_TYPE VARCHAR2(100 CHAR) NOT NULL,
  BYTE_SIZE NUMBER(16) NOT NULL,
  SCAN_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  VERIFICATION_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  UPLOADED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  UPLOADED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_KYC_DOC_UQ_VERSION UNIQUE (CASE_ID, DOCUMENT_TYPE, VERSION_NO),
  CONSTRAINT MB_KYC_DOC_UQ_STORAGE UNIQUE (STORAGE_REF),
  CONSTRAINT MB_KYC_DOC_CK_VERSION CHECK (VERSION_NO > 0),
  CONSTRAINT MB_KYC_DOC_CK_SIZE CHECK (BYTE_SIZE > 0),
  CONSTRAINT MB_KYC_DOC_CK_SCAN CHECK (SCAN_STATUS IN ('PENDING','CLEAN','QUARANTINED','FAILED')),
  CONSTRAINT MB_KYC_DOC_CK_VERIFY CHECK (VERIFICATION_STATUS IN ('PENDING','VERIFIED','REJECTED'))
);

ALTER TABLE M02_CIF_ADDRESS ADD CONSTRAINT MB_CIF_ADDRESS_FK_EVIDENCE
  FOREIGN KEY (EVIDENCE_DOCUMENT_ID) REFERENCES M02_KYC_DOCUMENT(DOCUMENT_ID);

CREATE TABLE M02_KYC_REVIEW (
  REVIEW_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CASE_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_KYC_CASE(CASE_ID),
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REVIEWER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REVIEWER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  OUTCOME VARCHAR2(24 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR),
  COMMENTS VARCHAR2(2000 CHAR),
  REVIEWED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  CONSTRAINT MB_KYC_REVIEW_CK_OUTCOME CHECK (OUTCOME IN ('APPROVE','REJECT','REQUEST_INFO')),
  CONSTRAINT MB_KYC_REVIEW_CK_SEPARATION CHECK (MAKER_USER_ID <> REVIEWER_USER_ID)
);
CREATE INDEX M02_KYC_REVIEW_IX_CASE ON M02_KYC_REVIEW(CASE_ID, REVIEWED_AT);

CREATE TABLE M02_CIF_CONSENT (
  CONSENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CIF_ID VARCHAR2(36 CHAR) NOT NULL REFERENCES M02_CIF_CUSTOMER(CIF_ID),
  PURPOSE_CODE VARCHAR2(80 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) NOT NULL,
  CAPTURE_CHANNEL VARCHAR2(40 CHAR) NOT NULL,
  CAPTURED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  WITHDRAWN_AT TIMESTAMP(6) WITH TIME ZONE,
  EVIDENCE_REF VARCHAR2(240 CHAR),
  CONSTRAINT MB_CIF_CONSENT_CK_STATUS CHECK (STATUS IN ('GRANTED','WITHDRAWN')),
  CONSTRAINT MB_CIF_CONSENT_CK_WITHDRAW CHECK ((STATUS = 'GRANTED' AND WITHDRAWN_AT IS NULL) OR (STATUS = 'WITHDRAWN' AND WITHDRAWN_AT IS NOT NULL))
);
CREATE INDEX M02_CIF_CONSENT_IX_CIF ON M02_CIF_CONSENT(CIF_ID, PURPOSE_CODE, CAPTURED_AT);

CREATE TABLE M02_CIF_AUDIT_EVENT (
  AUDIT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  ACTOR_USER_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  CIF_ID VARCHAR2(36 CHAR),
  CASE_ID VARCHAR2(36 CHAR),
  RESULT VARCHAR2(12 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR),
  MAKER_USER_ID VARCHAR2(36 CHAR),
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  BEFORE_STATE_HASH CHAR(64),
  AFTER_STATE_HASH CHAR(64),
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_CIF_AUDIT_CK_RESULT CHECK (RESULT IN ('SUCCESS','DENIED','FAILED'))
);
CREATE INDEX M02_CIF_AUDIT_IX_TIME ON M02_CIF_AUDIT_EVENT(OCCURRED_AT);

CREATE TABLE M02_CIF_OUTBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(40 CHAR) DEFAULT 'CIF_KYC' NOT NULL,
  SCHEMA_VERSION NUMBER(5) NOT NULL,
  AGGREGATE_TYPE VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(36 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  PAYLOAD CLOB NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  ATTEMPT_COUNT NUMBER(6) DEFAULT 0 NOT NULL,
  CONSTRAINT MB_CIF_OUTBOX_CK_JSON CHECK (PAYLOAD IS JSON),
  CONSTRAINT MB_CIF_OUTBOX_CK_ATTEMPTS CHECK (ATTEMPT_COUNT >= 0)
);
CREATE INDEX M02_CIF_OUTBOX_IX_PENDING ON M02_CIF_OUTBOX_EVENT(PUBLISHED_AT, OCCURRED_AT);

-- CIF/KYC consumes IAM and other domain events by ID, with idempotent handling.
CREATE TABLE M02_CIF_INBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(36 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE
);
CREATE INDEX M02_CIF_INBOX_IX_PENDING ON M02_CIF_INBOX_EVENT(PROCESSED_AT, RECEIVED_AT);
CREATE INDEX M01_IAM_INBOX_IX_PENDING ON M01_IAM_INBOX_EVENT(PROCESSED_AT, RECEIVED_AT);

-- Product Master service tables
-- IAM user/session and CIF/segment references are validated through APIs or
-- consumed events. They intentionally have no cross-schema foreign keys.
CREATE TABLE M03_PM_PRODUCT (
  PRODUCT_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_CODE VARCHAR2(40 CHAR) NOT NULL UNIQUE,
  PRODUCT_NAME VARCHAR2(200 CHAR) NOT NULL,
  PRODUCT_TYPE VARCHAR2(20 CHAR) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  BUSINESS_OWNER_REF VARCHAR2(80 CHAR) NOT NULL,
  PRODUCT_MANAGER_REF VARCHAR2(80 CHAR),
  SUPPORT_REF VARCHAR2(80 CHAR),
  DESCRIPTION VARCHAR2(2000 CHAR),
  SALES_START_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  SALES_END_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PM_PRODUCT_CK_TYPE CHECK (PRODUCT_TYPE IN ('SAVINGS','CURRENT','DEPOSIT','LOAN')),
  CONSTRAINT MB_PM_PRODUCT_CK_STATUS CHECK (STATUS IN ('ACTIVE','SUSPENDED','RETIRED')),
  CONSTRAINT MB_PM_PRODUCT_CK_SALES CHECK (SALES_END_AT IS NULL OR SALES_END_AT > SALES_START_AT)
);

CREATE TABLE M03_PM_PRODUCT_VERSION (
  PRODUCT_VERSION_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT(PRODUCT_ID),
  VERSION_NO NUMBER(8) NOT NULL,
  SOURCE_VERSION_ID NUMBER,
  VERSION_STATE VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL,
  EFFECTIVE_FROM_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  DEFAULT_TXN_ACTION VARCHAR2(10 CHAR) DEFAULT 'BLOCK' NOT NULL,
  CHANGE_REASON VARCHAR2(1000 CHAR) NOT NULL,
  RULE_SET_HASH CHAR(64),
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PM_VERSION_UQ_NO UNIQUE (PRODUCT_ID, VERSION_NO),
  CONSTRAINT MB_PM_VERSION_UQ_ID_PRODUCT UNIQUE (PRODUCT_VERSION_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_VERSION_FK_SOURCE FOREIGN KEY (SOURCE_VERSION_ID, PRODUCT_ID)
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_VERSION_CK_STATE CHECK (VERSION_STATE IN ('DRAFT','APPROVED','ACTIVE','SUSPENDED','RETIRED')),
  CONSTRAINT MB_PM_VERSION_CK_DATES CHECK (EFFECTIVE_TO_AT IS NULL OR EFFECTIVE_TO_AT > EFFECTIVE_FROM_AT),
  CONSTRAINT MB_PM_VERSION_CK_ACTION CHECK (DEFAULT_TXN_ACTION IN ('ALLOW','BLOCK'))
);
CREATE INDEX M03_PM_VERSION_LOOKUP_IX
  ON M03_PM_PRODUCT_VERSION(PRODUCT_ID, VERSION_STATE, EFFECTIVE_FROM_AT);

CREATE TABLE M03_PM_INTEREST_RULE (
  INTEREST_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  INTEREST_TYPE VARCHAR2(10 CHAR) NOT NULL,
  INTEREST_METHOD VARCHAR2(24 CHAR) NOT NULL,
  FIXED_RATE_PCT NUMBER(12,8),
  RATE_INDEX_CODE VARCHAR2(40 CHAR),
  SPREAD_PCT NUMBER(12,8),
  DAY_COUNT_BASIS VARCHAR2(20 CHAR) NOT NULL,
  COMPOUND_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  PAYOUT_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  ROUNDING_MODE VARCHAR2(20 CHAR) NOT NULL,
  CONSTRAINT MB_PM_INTEREST_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_INTEREST_RULE_CK_TYPE CHECK (INTEREST_TYPE IN ('FIXED','FLOATING')),
  CONSTRAINT MB_PM_INTEREST_RULE_CK_RATE CHECK
    ((INTEREST_TYPE = 'FIXED' AND FIXED_RATE_PCT IS NOT NULL
      AND FIXED_RATE_PCT >= 0 AND RATE_INDEX_CODE IS NULL AND SPREAD_PCT IS NULL) OR
     (INTEREST_TYPE = 'FLOATING' AND FIXED_RATE_PCT IS NULL
      AND RATE_INDEX_CODE IS NOT NULL AND SPREAD_PCT IS NOT NULL))
);

CREATE TABLE M03_PM_INTEREST_TIER (
  INTEREST_TIER_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  INTEREST_RULE_ID NUMBER NOT NULL REFERENCES M03_PM_INTEREST_RULE(INTEREST_RULE_ID),
  TIER_NO NUMBER(5) NOT NULL,
  AMOUNT_FROM NUMBER(20,4) NOT NULL,
  AMOUNT_TO NUMBER(20,4),
  RATE_PCT NUMBER(12,8) NOT NULL,
  CONSTRAINT MB_PM_INTEREST_TIER_UQ_NO UNIQUE (INTEREST_RULE_ID, TIER_NO),
  CONSTRAINT MB_PM_INTEREST_TIER_UQ_FROM UNIQUE (INTEREST_RULE_ID, AMOUNT_FROM),
  CONSTRAINT MB_PM_INTEREST_TIER_CK_RANGE CHECK (AMOUNT_TO IS NULL OR AMOUNT_TO > AMOUNT_FROM)
);

CREATE TABLE M03_PM_FEE_RULE (
  FEE_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  TRIGGER_CODE VARCHAR2(40 CHAR) NOT NULL,
  CHARGE_BASIS VARCHAR2(10 CHAR) NOT NULL,
  FIXED_AMOUNT NUMBER(20,4),
  RATE_PCT NUMBER(12,8),
  CHARGE_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  WAIVER_RULE_CODE VARCHAR2(40 CHAR),
  TAX_CODE VARCHAR2(40 CHAR),
  EFFECTIVE_FROM_AT TIMESTAMP(6) WITH TIME ZONE,
  EFFECTIVE_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_PM_FEE_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_FEE_RULE_CK_DATES CHECK (EFFECTIVE_TO_AT IS NULL OR EFFECTIVE_FROM_AT IS NOT NULL AND EFFECTIVE_TO_AT > EFFECTIVE_FROM_AT)
);

CREATE TABLE M03_PM_PENALTY_RULE (
  PENALTY_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  TRIGGER_CODE VARCHAR2(40 CHAR) NOT NULL,
  GRACE_DAYS NUMBER(6) DEFAULT 0 NOT NULL,
  FORMULA_CODE VARCHAR2(12 CHAR) NOT NULL,
  FIXED_AMOUNT NUMBER(20,4),
  RATE_PCT NUMBER(12,8),
  CAP_AMOUNT NUMBER(20,4),
  PRIORITY_NO NUMBER(5),
  EFFECTIVE_FROM_AT TIMESTAMP(6) WITH TIME ZONE,
  EFFECTIVE_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_PM_PENALTY_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_PENALTY_RULE_CK_DATES CHECK (EFFECTIVE_TO_AT IS NULL OR EFFECTIVE_FROM_AT IS NOT NULL AND EFFECTIVE_TO_AT > EFFECTIVE_FROM_AT)
);

CREATE TABLE M03_PM_LIMIT_RULE (
  LIMIT_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  OPERATION_CODE VARCHAR2(40 CHAR) NOT NULL,
  PERIOD_CODE VARCHAR2(20 CHAR) NOT NULL,
  MIN_AMOUNT NUMBER(20,4),
  MAX_AMOUNT NUMBER(20,4),
  MAX_COUNT NUMBER(12),
  CURRENCY_CODE VARCHAR2(3 CHAR),
  RESET_RULE_CODE VARCHAR2(40 CHAR),
  CONSTRAINT MB_PM_LIMIT_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_LIMIT_RULE_CK_RANGE CHECK (MIN_AMOUNT IS NULL OR MAX_AMOUNT IS NULL OR MIN_AMOUNT <= MAX_AMOUNT)
);

CREATE TABLE M03_PM_ELIGIBILITY_RULE (
  ELIGIBILITY_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  ATTRIBUTE_CODE VARCHAR2(40 CHAR) NOT NULL,
  OPERATOR_CODE VARCHAR2(12 CHAR) NOT NULL,
  VALUE_TYPE VARCHAR2(10 CHAR) NOT NULL,
  VALUE_TEXT VARCHAR2(250 CHAR),
  VALUE_NUMBER NUMBER(20,4),
  VALUE_DATE DATE,
  VALUE_BOOLEAN VARCHAR2(1 CHAR),
  FAILURE_REASON_CODE VARCHAR2(80 CHAR) NOT NULL,
  SEQUENCE_NO NUMBER(5) NOT NULL,
  CONSTRAINT MB_PM_ELIGIBILITY_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_ELIGIBILITY_RULE_UQ_SEQ UNIQUE (PRODUCT_VERSION_ID, SEQUENCE_NO),
  CONSTRAINT MB_PM_ELIGIBILITY_RULE_CK_BOOL CHECK (VALUE_BOOLEAN IS NULL OR VALUE_BOOLEAN IN ('Y','N')),
  CONSTRAINT MB_PM_ELIGIBILITY_RULE_CK_VALUE CHECK (
    (VALUE_TYPE = 'TEXT' AND VALUE_TEXT IS NOT NULL AND VALUE_NUMBER IS NULL AND VALUE_DATE IS NULL AND VALUE_BOOLEAN IS NULL) OR
    (VALUE_TYPE = 'NUMBER' AND VALUE_TEXT IS NULL AND VALUE_NUMBER IS NOT NULL AND VALUE_DATE IS NULL AND VALUE_BOOLEAN IS NULL) OR
    (VALUE_TYPE = 'DATE' AND VALUE_TEXT IS NULL AND VALUE_NUMBER IS NULL AND VALUE_DATE IS NOT NULL AND VALUE_BOOLEAN IS NULL) OR
    (VALUE_TYPE = 'BOOLEAN' AND VALUE_TEXT IS NULL AND VALUE_NUMBER IS NULL AND VALUE_DATE IS NULL AND VALUE_BOOLEAN IS NOT NULL)
  )
);

CREATE TABLE M03_PM_BALANCE_RULE (
  PRODUCT_VERSION_ID NUMBER PRIMARY KEY REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  MIN_BALANCE NUMBER(20,4) NOT NULL,
  MEASUREMENT_BASIS VARCHAR2(20 CHAR) NOT NULL,
  MEASUREMENT_PERIOD VARCHAR2(20 CHAR) NOT NULL,
  GRACE_DAYS NUMBER(6) DEFAULT 0 NOT NULL,
  CONSEQUENCE_CODE VARCHAR2(20 CHAR) NOT NULL,
  CONSTRAINT MB_PM_BALANCE_RULE_CK_MIN CHECK (MIN_BALANCE >= 0)
);


-- Deposit-account terms are Product Master policy, not Account Service
-- configuration. Savings/current activation requires this row on the exact
-- approved version. PM_BALANCE_RULE remains the ongoing minimum-balance rule;
-- MIN_OPENING_BALANCE is a distinct opening requirement.
CREATE TABLE M03_PM_ACCOUNT_RULE (
  PRODUCT_VERSION_ID NUMBER PRIMARY KEY
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  MIN_OPENING_BALANCE NUMBER(18,2) DEFAULT 0 NOT NULL,
  MINOR_ALLOWED CHAR(1) DEFAULT 'N' NOT NULL,
  MINOR_DAILY_DEBIT_LIMIT NUMBER(18,2),
  JOINT_ALLOWED CHAR(1) DEFAULT 'N' NOT NULL,
  MAX_HOLDERS NUMBER(3) DEFAULT 1 NOT NULL,
  NOMINEE_REQUIRED CHAR(1) DEFAULT 'N' NOT NULL,
  DORMANCY_AFTER_DAYS NUMBER(6),
  CONSTRAINT MB_PM_ACCT_RULE_CK_OPENING CHECK (MIN_OPENING_BALANCE >= 0),
  CONSTRAINT MB_PM_ACCT_RULE_CK_MINOR CHECK (MINOR_ALLOWED IN ('Y','N')),
  CONSTRAINT MB_PM_ACCT_RULE_CK_MINOR_LIMIT CHECK
    ((MINOR_ALLOWED = 'N' AND MINOR_DAILY_DEBIT_LIMIT IS NULL) OR
     (MINOR_ALLOWED = 'Y' AND MINOR_DAILY_DEBIT_LIMIT IS NOT NULL
      AND MINOR_DAILY_DEBIT_LIMIT >= 0)),
  CONSTRAINT MB_PM_ACCT_RULE_CK_JOINT CHECK (JOINT_ALLOWED IN ('Y','N')),
  CONSTRAINT MB_PM_ACCT_RULE_CK_HOLDERS CHECK
    (MAX_HOLDERS >= 1 AND (JOINT_ALLOWED = 'Y' OR MAX_HOLDERS = 1)),
  CONSTRAINT MB_PM_ACCT_RULE_CK_NOMINEE CHECK (NOMINEE_REQUIRED IN ('Y','N')),
  CONSTRAINT MB_PM_ACCT_RULE_CK_DORMANCY CHECK
    (DORMANCY_AFTER_DAYS IS NULL OR DORMANCY_AFTER_DAYS > 0)
);
-- Product Service validates that this table applies only to SAVINGS/CURRENT
-- versions. Include this row in the version's RULE_SET_HASH and approval
-- CONTENT_HASH; approved versions are immutable. Product Service exposes a
-- versioned eligibility decision to Account Service.

CREATE TABLE M03_PM_LOAN_RULE (
  PRODUCT_VERSION_ID NUMBER PRIMARY KEY
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  LOAN_CATEGORY VARCHAR2(20 CHAR) NOT NULL,
  MIN_LOAN_AMOUNT NUMBER(18,2) NOT NULL,
  MAX_LOAN_AMOUNT NUMBER(18,2) NOT NULL,
  MIN_TENURE_MONTHS NUMBER(4) NOT NULL,
  MAX_TENURE_MONTHS NUMBER(4) NOT NULL,
  ALLOWED_INTEREST_TYPE VARCHAR2(10 CHAR) NOT NULL,
  REPAYMENT_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  AMORTIZATION_METHOD VARCHAR2(24 CHAR) NOT NULL,
  DISBURSEMENT_MODE VARCHAR2(12 CHAR) DEFAULT 'SINGLE' NOT NULL,
  MAX_MORATORIUM_MONTHS NUMBER(3) DEFAULT 0 NOT NULL,
  GRACE_DAYS NUMBER(4) DEFAULT 0 NOT NULL,
  COLLATERAL_REQUIRED CHAR(1) DEFAULT 'N' NOT NULL,
  GUARANTOR_REQUIRED CHAR(1) DEFAULT 'N' NOT NULL,
  MAX_CO_BORROWERS NUMBER(2) DEFAULT 0 NOT NULL,
  PREPAYMENT_ALLOWED CHAR(1) DEFAULT 'Y' NOT NULL,
  PARTIAL_PREPAYMENT_ALLOWED CHAR(1) DEFAULT 'Y' NOT NULL,
  FORECLOSURE_ALLOWED CHAR(1) DEFAULT 'Y' NOT NULL,
  CONSTRAINT MB_PM_LOAN_RULE_CK_CATEGORY CHECK
    (LOAN_CATEGORY IN ('PERSONAL','HOME','VEHICLE','EDUCATION','BUSINESS','OTHER')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_AMOUNT CHECK
    (MIN_LOAN_AMOUNT > 0 AND MAX_LOAN_AMOUNT >= MIN_LOAN_AMOUNT),
  CONSTRAINT MB_PM_LOAN_RULE_CK_TENURE CHECK
    (MIN_TENURE_MONTHS > 0 AND MAX_TENURE_MONTHS >= MIN_TENURE_MONTHS),
  CONSTRAINT MB_PM_LOAN_RULE_CK_INTEREST CHECK
    (ALLOWED_INTEREST_TYPE IN ('FIXED','FLOATING','BOTH')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_FREQUENCY CHECK
    (REPAYMENT_FREQUENCY IN ('WEEKLY','FORTNIGHTLY','MONTHLY','QUARTERLY','BULLET')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_AMORTIZATION CHECK
    (AMORTIZATION_METHOD IN ('REDUCING_BALANCE','FLAT','BULLET','CUSTOM')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_DISBURSEMENT CHECK
    (DISBURSEMENT_MODE IN ('SINGLE','TRANCHE','BOTH')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_COUNTS CHECK
    (MAX_MORATORIUM_MONTHS >= 0 AND GRACE_DAYS >= 0 AND MAX_CO_BORROWERS >= 0),
  CONSTRAINT MB_PM_LOAN_RULE_CK_FLAGS CHECK
    (COLLATERAL_REQUIRED IN ('Y','N') AND GUARANTOR_REQUIRED IN ('Y','N')
     AND PREPAYMENT_ALLOWED IN ('Y','N')
     AND PARTIAL_PREPAYMENT_ALLOWED IN ('Y','N')
     AND FORECLOSURE_ALLOWED IN ('Y','N')),
  CONSTRAINT MB_PM_LOAN_RULE_CK_PARTIAL CHECK
    (PARTIAL_PREPAYMENT_ALLOWED = 'N' OR PREPAYMENT_ALLOWED = 'Y')
);
-- Product Service permits this extension only for LOAN versions. Its row is
-- included in RULE_SET_HASH and is immutable after version approval.

CREATE TABLE M03_PM_TRANSACTION_RULE (
  TRANSACTION_RULE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  OPERATION_CODE VARCHAR2(40 CHAR) NOT NULL,
  CHANNEL_CODE VARCHAR2(40 CHAR),
  DIRECTION_CODE VARCHAR2(10 CHAR) NOT NULL,
  COUNTERPARTY_CODE VARCHAR2(40 CHAR),
  GEOGRAPHY_CODE VARCHAR2(40 CHAR),
  TIME_WINDOW_CODE VARCHAR2(40 CHAR),
  ACTION_CODE VARCHAR2(10 CHAR) NOT NULL,
  PRIORITY_NO NUMBER(5) NOT NULL,
  CONSTRAINT MB_PM_TRANSACTION_RULE_UQ_CODE UNIQUE (PRODUCT_VERSION_ID, RULE_CODE),
  CONSTRAINT MB_PM_TRANSACTION_RULE_UQ_PRIORITY UNIQUE (PRODUCT_VERSION_ID, PRIORITY_NO)
);

CREATE TABLE M03_PM_AVAILABILITY (
  AVAILABILITY_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  SEGMENT_CODE VARCHAR2(40 CHAR), -- NULL means any segment.
  BRANCH_CODE VARCHAR2(80 CHAR), -- NULL means any branch; matches CIF/account branch references.
  CHANNEL_CODE VARCHAR2(40 CHAR), -- NULL means any channel.
  CURRENCY_CODE VARCHAR2(3 CHAR) NOT NULL,
  OFFER_FROM_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  OFFER_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  PRIORITY_NO NUMBER(5) DEFAULT 100 NOT NULL,
  CONSTRAINT MB_PM_AVAIL_CK_DATES CHECK (OFFER_TO_AT IS NULL OR OFFER_TO_AT > OFFER_FROM_AT)
);
CREATE INDEX M03_PM_AVAIL_VER_IX
  ON M03_PM_AVAILABILITY(PRODUCT_VERSION_ID);

CREATE TABLE M03_PM_APPROVAL (
  APPROVAL_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT(PRODUCT_ID),
  PRODUCT_VERSION_ID NUMBER,
  ACTION_CODE VARCHAR2(24 CHAR) NOT NULL,
  REQUEST_STATUS VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  MAKER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  CHECKER_SESSION_ID VARCHAR2(36 CHAR),
  CONTENT_HASH CHAR(64) NOT NULL,
  REASON VARCHAR2(1000 CHAR) NOT NULL,
  IMPACT_SUMMARY VARCHAR2(2000 CHAR),
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  SUBMITTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_EFFECTIVE_FROM_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_EFFECTIVE_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  CHECKER_COMMENT VARCHAR2(1000 CHAR),
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PM_APPROVAL_UQ_ID_PRODUCT UNIQUE (APPROVAL_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_APPROVAL_FK_VERSION FOREIGN KEY (PRODUCT_VERSION_ID, PRODUCT_ID)
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_APPROVAL_CK_CHECKER CHECK (CHECKER_USER_ID IS NULL OR CHECKER_USER_ID <> MAKER_USER_ID),
  CONSTRAINT MB_PM_APPROVAL_CK_ACTION CHECK (ACTION_CODE IN ('VERSION','SUSPEND','RETIRE','REACTIVATE','TREATMENT')),
  CONSTRAINT MB_PM_APPROVAL_CK_STATUS CHECK (REQUEST_STATUS IN ('PENDING','APPROVED','REJECTED','WITHDRAWN')),
  CONSTRAINT MB_PM_APPROVAL_CK_DATES CHECK (APPROVED_EFFECTIVE_TO_AT IS NULL OR APPROVED_EFFECTIVE_FROM_AT IS NOT NULL AND APPROVED_EFFECTIVE_TO_AT > APPROVED_EFFECTIVE_FROM_AT),
  CONSTRAINT MB_PM_APPROVAL_CK_DECISION CHECK (
    (REQUEST_STATUS = 'PENDING' AND CHECKER_USER_ID IS NULL AND CHECKER_SESSION_ID IS NULL AND DECIDED_AT IS NULL) OR
    (REQUEST_STATUS IN ('APPROVED','REJECTED') AND CHECKER_USER_ID IS NOT NULL AND CHECKER_SESSION_ID IS NOT NULL AND DECIDED_AT IS NOT NULL) OR
    (REQUEST_STATUS = 'WITHDRAWN' AND DECIDED_AT IS NOT NULL)
  )
);
CREATE INDEX M03_PM_APPROVAL_VER_IX
  ON M03_PM_APPROVAL(PRODUCT_VERSION_ID, REQUEST_STATUS);
-- Application logic binds CONTENT_HASH to the submitted rule set.

CREATE TABLE M03_PM_OVERRIDE_POLICY (
  OVERRIDE_POLICY_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER NOT NULL REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  RULE_FAMILY VARCHAR2(20 CHAR) NOT NULL,
  RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  FIELD_CODE VARCHAR2(40 CHAR) NOT NULL,
  MIN_VALUE NUMBER(20,8),
  MAX_VALUE NUMBER(20,8),
  AUTHORITY_CODE VARCHAR2(40 CHAR) NOT NULL,
  VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  VALID_TO TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_PM_OVERRIDE_POLICY_UQ_FIELD UNIQUE (PRODUCT_VERSION_ID, RULE_FAMILY, RULE_CODE, FIELD_CODE),
  CONSTRAINT MB_PM_OVERRIDE_POLICY_CK_RANGE CHECK (MIN_VALUE IS NULL OR MAX_VALUE IS NULL OR MIN_VALUE <= MAX_VALUE),
  CONSTRAINT MB_PM_OVERRIDE_POLICY_CK_DATES CHECK (VALID_TO IS NULL OR VALID_TO > VALID_FROM)
);
-- This table defines allowed overrides; Account/Pricing stores actual overrides.

CREATE TABLE M03_PM_VERSION_TREATMENT (
  VERSION_TREATMENT_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_ID NUMBER NOT NULL,
  SOURCE_VERSION_ID NUMBER NOT NULL,
  TARGET_VERSION_ID NUMBER NOT NULL,
  TREATMENT_CODE VARCHAR2(20 CHAR) NOT NULL,
  MIGRATION_FROM_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSENT_REQUIRED VARCHAR2(1 CHAR) DEFAULT 'N' NOT NULL,
  APPROVAL_ID NUMBER NOT NULL,
  CONSTRAINT MB_PM_TREATMENT_UQ_VERSIONS UNIQUE (SOURCE_VERSION_ID, TARGET_VERSION_ID),
  CONSTRAINT MB_PM_TREATMENT_CK_DIFFERENT CHECK (SOURCE_VERSION_ID <> TARGET_VERSION_ID),
  CONSTRAINT MB_PM_TREATMENT_CK_CODE CHECK (TREATMENT_CODE IN ('GRANDFATHER','SCHEDULED','RENEWAL','MANDATORY','OPT_IN')),
  CONSTRAINT MB_PM_TREATMENT_CK_CONSENT CHECK (CONSENT_REQUIRED IN ('Y','N')),
  CONSTRAINT MB_PM_TREATMENT_FK_SOURCE FOREIGN KEY (SOURCE_VERSION_ID, PRODUCT_ID)
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_TREATMENT_FK_TARGET FOREIGN KEY (TARGET_VERSION_ID, PRODUCT_ID)
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID, PRODUCT_ID),
  CONSTRAINT MB_PM_TREATMENT_FK_APPROVAL FOREIGN KEY (APPROVAL_ID, PRODUCT_ID)
    REFERENCES M03_PM_APPROVAL(APPROVAL_ID, PRODUCT_ID)
);
CREATE INDEX M03_PM_TREAT_TARGET_IX
  ON M03_PM_VERSION_TREATMENT(TARGET_VERSION_ID);

-- Administrative and sensitive-read evidence; foreign service IDs are kept
-- as historical references even if the source service later changes state.
CREATE TABLE M03_PM_AUDIT_EVENT (
  AUDIT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  ACTOR_USER_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  MAKER_USER_ID VARCHAR2(36 CHAR),
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  PRODUCT_ID NUMBER,
  PRODUCT_VERSION_ID NUMBER,
  RESOURCE_TYPE VARCHAR2(60 CHAR),
  RESOURCE_ID VARCHAR2(80 CHAR),
  RESULT VARCHAR2(12 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR),
  BEFORE_STATE_HASH CHAR(64),
  AFTER_STATE_HASH CHAR(64),
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_PM_AUDIT_CK_RESULT CHECK (RESULT IN ('SUCCESS','DENIED','FAILED'))
);
CREATE INDEX M03_PM_AUDIT_IX_TIME
  ON M03_PM_AUDIT_EVENT(OCCURRED_AT);
CREATE INDEX M03_PM_AUDIT_IX_PRODUCT
  ON M03_PM_AUDIT_EVENT(PRODUCT_ID, PRODUCT_VERSION_ID, OCCURRED_AT);

-- Product lifecycle/treatment changes and this outbox row commit together.
CREATE TABLE M03_PM_OUTBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(40 CHAR) DEFAULT 'PRODUCT_MASTER' NOT NULL,
  SCHEMA_VERSION NUMBER(5) NOT NULL,
  AGGREGATE_TYPE VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(40 CHAR) NOT NULL,
  PRODUCT_ID NUMBER,
  PRODUCT_VERSION_ID NUMBER,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  PAYLOAD CLOB NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  ATTEMPT_COUNT NUMBER(6) DEFAULT 0 NOT NULL,
  CONSTRAINT MB_PM_OUTBOX_CK_JSON CHECK (PAYLOAD IS JSON),
  CONSTRAINT MB_PM_OUTBOX_CK_ATTEMPTS CHECK (ATTEMPT_COUNT >= 0)
);
CREATE INDEX M03_PM_OUTBOX_IX_PENDING
  ON M03_PM_OUTBOX_EVENT(PUBLISHED_AT, OCCURRED_AT);

-- A unique event ID makes redelivery safe for Product Master consumers.
CREATE TABLE M03_PM_INBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(80 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE
);
CREATE INDEX M03_PM_INBOX_IX_PENDING
  ON M03_PM_INBOX_EVENT(PROCESSED_AT, RECEIVED_AT);

-- Account Management (module 4).
-- ACCOUNT_MGMT owns these tables. References to CIF_KYC.CIF_CUSTOMER.CIF_ID,
-- PRODUCT_MASTER.PM_PRODUCT/PM_PRODUCT_VERSION, and IAM.IAM_USER are values
-- validated through service APIs/events; they are deliberately not FKs.
-- Account internal IDs are Oracle identities. External CIF/IAM IDs are UUID
-- strings. Product and version IDs retain Product Master's numeric types.
-- The module 4 DBML's CUSTOMER and BANK_PRODUCT boxes resolve to the
-- existing CIF_KYC.CIF_CUSTOMER and PRODUCT_MASTER.PM_PRODUCT services; do
-- not create duplicate local masters. KYC/minor status stays with CIF, while
-- default rates and product rules stay with Product Master.
-- Initially open only SAVINGS/CURRENT products. An account pins the approved
-- product version it adopted; later product changes do not silently rewrite it.
-- All financial amounts use NUMBER(18,2), and all event times are zoned.
-- Module 5 serializes holds and balance mutation and is the only financial
-- posting writer. Account Management updates its balance projection only from
-- idempotently consumed Module 5 events and never authorizes from that projection.

CREATE SEQUENCE M04_ACCOUNT_NUMBER_SEQ START WITH 1 INCREMENT BY 1 NOCYCLE CACHE 100;
-- The service uses controlled short branch/product prefixes, this sequence,
-- and a check digit. Full branch/product codes may exceed 20 characters, so
-- they must not be concatenated verbatim. The unique constraint is final.

CREATE TABLE M04_BANK_ACCOUNT (
  ACCOUNT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_NUMBER VARCHAR2(20 CHAR) NOT NULL UNIQUE,
  PRIMARY_CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  PRODUCT_ID NUMBER(19) NOT NULL,
  PRODUCT_VERSION_ID NUMBER(19) NOT NULL,
  BRANCH_CODE VARCHAR2(80 CHAR) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) DEFAULT 'INR' NOT NULL,
  LIFECYCLE_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING_OPEN' NOT NULL,
  ACCOUNT_STATUS VARCHAR2(30 CHAR) DEFAULT 'PENDING_OPEN' NOT NULL,
  ACCOUNT_OPERATION_MODE VARCHAR2(30 CHAR) DEFAULT 'SELF_OPERATED' NOT NULL,
  MAJORITY_REVIEW_STATUS VARCHAR2(30 CHAR) DEFAULT 'NOT_APPLICABLE' NOT NULL,
  LEDGER_BALANCE NUMBER(18,2) DEFAULT 0 NOT NULL,
  BLOCKED_BALANCE NUMBER(18,2) DEFAULT 0 NOT NULL,
  LIEN_BALANCE NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDRAFT_LIMIT NUMBER(18,2) DEFAULT 0 NOT NULL,
  AVAILABLE_BALANCE NUMBER(18,2) GENERATED ALWAYS AS
    (LEDGER_BALANCE - BLOCKED_BALANCE - LIEN_BALANCE + OVERDRAFT_LIMIT) VIRTUAL,
  BALANCE_AS_OF TIMESTAMP(6) WITH TIME ZONE,
  BALANCE_SOURCE_JOURNAL_ID NUMBER(19),
  BALANCE_SOURCE_EVENT_ID RAW(16),
  BALANCE_SOURCE_VERSION NUMBER(19) DEFAULT 0 NOT NULL,
  FINANCIAL_CONTROL_VERSION NUMBER(19) DEFAULT 0 NOT NULL,
  INTEREST_ACCRUED NUMBER(18,2) DEFAULT 0 NOT NULL,
  LAST_INTEREST_CALCULATION_AT TIMESTAMP(6) WITH TIME ZONE,
  LAST_INTEREST_POSTING_AT TIMESTAMP(6) WITH TIME ZONE,
  OPENED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ACTIVATED_AT TIMESTAMP(6) WITH TIME ZONE,
  CANCELLED_AT TIMESTAMP(6) WITH TIME ZONE,
  CLOSED_AT TIMESTAMP(6) WITH TIME ZONE,
  LAST_TRANSACTION_AT TIMESTAMP(6) WITH TIME ZONE,
  OPEN_REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY_USER_ID VARCHAR2(36 CHAR),
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ROW_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_ACCT_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_ACCT_CK_STATUS CHECK (ACCOUNT_STATUS IN
    ('PENDING_OPEN','ACTIVE','FROZEN','DEBIT_BLOCKED','CREDIT_BLOCKED','DORMANT','CLOSING','CANCELLED','CLOSED')),
  CONSTRAINT MB_ACCT_CK_LIFECYCLE CHECK (LIFECYCLE_STATUS IN
    ('PENDING_OPEN','ACTIVE','DORMANT','CLOSING','CANCELLED','CLOSED')),
  CONSTRAINT MB_ACCT_CK_STATUS_PAIR CHECK
    ((LIFECYCLE_STATUS = 'ACTIVE' AND ACCOUNT_STATUS IN
       ('ACTIVE','FROZEN','DEBIT_BLOCKED','CREDIT_BLOCKED')) OR
     (LIFECYCLE_STATUS <> 'ACTIVE' AND ACCOUNT_STATUS = LIFECYCLE_STATUS)),
  CONSTRAINT MB_ACCT_CK_MODE CHECK (ACCOUNT_OPERATION_MODE IN
    ('SELF_OPERATED','ANYONE','JOINTLY','GUARDIAN_OPERATED')),
  CONSTRAINT MB_ACCT_CK_MAJORITY CHECK (MAJORITY_REVIEW_STATUS IN
    ('NOT_APPLICABLE','PENDING','COMPLETED','ESCALATED')),
  CONSTRAINT MB_ACCT_CK_PROJECTION CHECK
    (BLOCKED_BALANCE >= 0 AND LIEN_BALANCE >= 0 AND OVERDRAFT_LIMIT >= 0
     AND BALANCE_SOURCE_VERSION >= 0 AND FINANCIAL_CONTROL_VERSION >= 0),
  CONSTRAINT MB_ACCT_CK_CLOSED CHECK
    ((LIFECYCLE_STATUS = 'CLOSED' AND CLOSED_AT IS NOT NULL) OR
     (LIFECYCLE_STATUS <> 'CLOSED' AND CLOSED_AT IS NULL)),
  CONSTRAINT MB_ACCT_CK_CANCELLED CHECK
    ((LIFECYCLE_STATUS = 'CANCELLED' AND CANCELLED_AT IS NOT NULL) OR
     (LIFECYCLE_STATUS <> 'CANCELLED' AND CANCELLED_AT IS NULL)),
  CONSTRAINT MB_ACCT_CK_ACTIVE_TIME CHECK
    ((LIFECYCLE_STATUS IN ('PENDING_OPEN','CANCELLED') AND ACTIVATED_AT IS NULL) OR
     (LIFECYCLE_STATUS NOT IN ('PENDING_OPEN','CANCELLED') AND ACTIVATED_AT IS NOT NULL)),
  CONSTRAINT MB_ACCT_CK_ACTIVATION CHECK (ACTIVATED_AT IS NULL OR ACTIVATED_AT >= OPENED_AT),
  CONSTRAINT MB_ACCT_CK_CANCEL_TIME CHECK (CANCELLED_AT IS NULL OR CANCELLED_AT >= OPENED_AT),
  CONSTRAINT MB_ACCT_CK_CLOSE_TIME CHECK (CLOSED_AT IS NULL OR CLOSED_AT >= OPENED_AT)
);
CREATE INDEX M04_ACCT_IX_CIF
  ON M04_BANK_ACCOUNT(PRIMARY_CIF_ID, ACCOUNT_STATUS);
CREATE INDEX M04_ACCT_IX_PRODUCT
  ON M04_BANK_ACCOUNT(PRODUCT_ID, PRODUCT_VERSION_ID, ACCOUNT_STATUS);
CREATE INDEX M04_ACCT_IX_BRANCH
  ON M04_BANK_ACCOUNT(BRANCH_CODE, ACCOUNT_STATUS);
CREATE INDEX M04_ACCT_IX_BALANCE_EVENT
  ON M04_BANK_ACCOUNT(BALANCE_SOURCE_EVENT_ID);
-- LIFECYCLE_STATUS and live restrictions are Account Management facts. The four
-- financial amount columns are non-authoritative projections updated only from
-- idempotently consumed Module 5 events. Module 5 ACCOUNT_POSITION is used for
-- spend authorization; a stale screen projection must never approve a debit.

CREATE TABLE M04_ACCOUNT_OPENING_EVIDENCE (
  EVIDENCE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  ATTEMPT_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  CIF_DECISION_REF VARCHAR2(80 CHAR) NOT NULL,
  PRODUCT_DECISION_REF VARCHAR2(80 CHAR) NOT NULL,
  IAM_DECISION_REF VARCHAR2(80 CHAR) NOT NULL,
  PRODUCT_VERSION_ID NUMBER NOT NULL,
  PRODUCT_RULE_SET_HASH CHAR(64) NOT NULL,
  DECISION_RESULT VARCHAR2(8 CHAR) NOT NULL,
  FAILURE_REASON_CODE VARCHAR2(80 CHAR),
  EVALUATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_OPEN_CK_RESULT CHECK (DECISION_RESULT IN ('PASS','FAIL')),
  CONSTRAINT MB_ACCT_OPEN_CK_FAILURE CHECK
    ((DECISION_RESULT = 'PASS' AND FAILURE_REASON_CODE IS NULL) OR
     (DECISION_RESULT = 'FAIL' AND FAILURE_REASON_CODE IS NOT NULL))
);
CREATE INDEX M04_ACCT_OPEN_IX_ACCOUNT
  ON M04_ACCOUNT_OPENING_EVIDENCE(ACCOUNT_ID, EVALUATED_AT);
-- Recheck CIF/KYC, product version/availability, and IAM immediately before
-- activation; old evidence cannot be reused after a status or rule change.
-- PENDING_OPEN disallows ordinary transactions. If minimum opening funding
-- is positive, only a dedicated idempotent OPENING_FUNDING posting is allowed.
-- If opening fails after funding, reverse/return it through Transaction
-- Service before CANCELLED. A cancelled account number is never reused.

CREATE TABLE M04_ACCOUNT_PARTY (
  ACCOUNT_PARTY_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  PARTY_ROLE VARCHAR2(30 CHAR) NOT NULL,
  OPERATING_INSTRUCTION VARCHAR2(30 CHAR) DEFAULT 'SELF' NOT NULL,
  IS_ACTIVE CHAR(1) DEFAULT 'Y' NOT NULL,
  EFFECTIVE_FROM DATE NOT NULL,
  EFFECTIVE_TO DATE,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_PARTY_UQ_START UNIQUE (ACCOUNT_ID, CIF_ID, PARTY_ROLE, EFFECTIVE_FROM),
  CONSTRAINT MB_ACCT_PARTY_CK_ROLE CHECK (PARTY_ROLE IN
    ('PRIMARY_HOLDER','JOINT_HOLDER','AUTHORIZED_SIGNATORY','GUARDIAN')),
  CONSTRAINT MB_ACCT_PARTY_CK_INSTRUCTION CHECK (OPERATING_INSTRUCTION IN
    ('SELF','ANYONE','JOINTLY','GUARDIAN')),
  CONSTRAINT MB_ACCT_PARTY_CK_ACTIVE CHECK (IS_ACTIVE IN ('Y','N')),
  CONSTRAINT MB_ACCT_PARTY_CK_DATES CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM)
);
CREATE UNIQUE INDEX M04_ACCT_PARTY_UQ_PRIMARY
  ON M04_ACCOUNT_PARTY
    (CASE WHEN PARTY_ROLE = 'PRIMARY_HOLDER' AND IS_ACTIVE = 'Y' THEN ACCOUNT_ID END);
CREATE INDEX M04_ACCT_PARTY_IX_CIF
  ON M04_ACCOUNT_PARTY(CIF_ID, IS_ACTIVE);
-- Open/activate in one service transaction with exactly one active primary
-- holder whose CIF_ID equals BANK_ACCOUNT.PRIMARY_CIF_ID. The unique index
-- enforces at most one; the service enforces existence and matching identity.
-- For customer self-service, IAM_CUSTOMER_LINK alone is insufficient: the
-- caller also needs an active ACCOUNT_PARTY role with matching authority.

CREATE TABLE M04_ACCOUNT_NOMINEE (
  NOMINEE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  NOMINEE_CIF_ID VARCHAR2(36 CHAR),
  NOMINEE_NAME VARCHAR2(200 CHAR) NOT NULL,
  RELATIONSHIP VARCHAR2(50 CHAR) NOT NULL,
  DATE_OF_BIRTH DATE,
  MOBILE_NUMBER VARCHAR2(20 CHAR),
  ADDRESS_LINE1 VARCHAR2(200 CHAR),
  ADDRESS_LINE2 VARCHAR2(200 CHAR),
  CITY VARCHAR2(100 CHAR),
  STATE VARCHAR2(100 CHAR),
  POSTAL_CODE VARCHAR2(20 CHAR),
  SHARE_PERCENTAGE NUMBER(5,2) DEFAULT 100 NOT NULL,
  GUARDIAN_NAME VARCHAR2(200 CHAR),
  GUARDIAN_RELATIONSHIP VARCHAR2(50 CHAR),
  IS_ACTIVE CHAR(1) DEFAULT 'Y' NOT NULL,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_NOMINEE_CK_SHARE CHECK (SHARE_PERCENTAGE > 0 AND SHARE_PERCENTAGE <= 100),
  CONSTRAINT MB_ACCT_NOMINEE_CK_ACTIVE CHECK (IS_ACTIVE IN ('Y','N'))
);
CREATE INDEX M04_ACCT_NOMINEE_IX_ACCOUNT
  ON M04_ACCOUNT_NOMINEE(ACCOUNT_ID, IS_ACTIVE);
-- Nominees need not have a CIF. The service validates active shares sum to
-- 100 and protects nominee PII according to bank retention/access policy.

CREATE TABLE M04_ACCOUNT_MAJORITY_REVIEW (
  REVIEW_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  REVIEW_REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  REVIEW_STATUS VARCHAR2(16 CHAR) DEFAULT 'PENDING' NOT NULL,
  DUE_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  STARTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  DECIDED_BY_USER_ID VARCHAR2(36 CHAR),
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  DECISION_REASON VARCHAR2(500 CHAR),
  CONSTRAINT MB_ACCT_MAJOR_CK_STATUS CHECK
    (REVIEW_STATUS IN ('PENDING','COMPLETED','ESCALATED')),
  CONSTRAINT MB_ACCT_MAJOR_CK_DECISION CHECK
    ((REVIEW_STATUS = 'PENDING' AND DECIDED_AT IS NULL
      AND DECIDED_BY_USER_ID IS NULL) OR
     (REVIEW_STATUS <> 'PENDING' AND DECIDED_AT IS NOT NULL
      AND DECIDED_BY_USER_ID IS NOT NULL)),
  CONSTRAINT MB_ACCT_MAJOR_CK_TIME CHECK
    (DECIDED_AT IS NULL OR DECIDED_AT >= STARTED_AT)
);
CREATE UNIQUE INDEX M04_ACCT_MAJOR_UQ_PENDING
  ON M04_ACCOUNT_MAJORITY_REVIEW
    (CASE WHEN REVIEW_STATUS = 'PENDING' THEN ACCOUNT_ID END);
-- CIF date of birth and guardian relationship remain authoritative. Majority
-- does not silently remove guardian authority or switch operation mode;
-- review, customer consent, IAM authorization, and audit precede the change.

CREATE TABLE M04_ACCOUNT_STATUS_HISTORY (
  STATUS_HISTORY_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  CHANGE_KIND VARCHAR2(20 CHAR) NOT NULL,
  OLD_STATUS VARCHAR2(30 CHAR),
  NEW_STATUS VARCHAR2(30 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(50 CHAR) NOT NULL,
  REASON_REMARKS VARCHAR2(500 CHAR),
  CHANGED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CHANGED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  CONSTRAINT MB_ACCT_HIST_CK_KIND CHECK
    (CHANGE_KIND IN ('LIFECYCLE','RESTRICTION','SYSTEM')),
  CONSTRAINT MB_ACCT_HIST_CK_CHANGE CHECK
    (OLD_STATUS IS NULL OR OLD_STATUS <> NEW_STATUS OR CHANGE_KIND = 'RESTRICTION'),
  CONSTRAINT MB_ACCT_HIST_CK_NEW CHECK (NEW_STATUS IN
    ('PENDING_OPEN','ACTIVE','FROZEN','DEBIT_BLOCKED','CREDIT_BLOCKED','DORMANT','CLOSING','CANCELLED','CLOSED')),
  CONSTRAINT MB_ACCT_HIST_CK_OLD CHECK (OLD_STATUS IS NULL OR OLD_STATUS IN
    ('PENDING_OPEN','ACTIVE','FROZEN','DEBIT_BLOCKED','CREDIT_BLOCKED','DORMANT','CLOSING','CANCELLED','CLOSED'))
);
CREATE INDEX M04_ACCT_HIST_IX_ACCOUNT
  ON M04_ACCOUNT_STATUS_HISTORY(ACCOUNT_ID, CHANGED_AT);
-- Append a history row in the same local transaction as each status/control
-- change, including freezes whose display summary is already FROZEN.
-- CANCELLED and CLOSED are terminal; application logic forbids transitions.

CREATE TABLE M04_ACCOUNT_RESTRICTION (
  RESTRICTION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER(19) NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  RESTRICTION_TYPE VARCHAR2(30 CHAR) NOT NULL,
  RESTRICTION_AMOUNT NUMBER(18,2),
  SOURCE_SYSTEM VARCHAR2(40 CHAR),
  SOURCE_REFERENCE VARCHAR2(80 CHAR),
  REASON_CODE VARCHAR2(50 CHAR) NOT NULL,
  REASON_REMARKS VARCHAR2(500 CHAR),
  RESTRICTION_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING_APPLY' NOT NULL,
  STARTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  EFFECTIVE_AT TIMESTAMP(6) WITH TIME ZONE,
  ENDS_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REMOVED_BY_USER_ID VARCHAR2(36 CHAR),
  REMOVED_AT TIMESTAMP(6) WITH TIME ZONE,
  FAILURE_CODE VARCHAR2(50 CHAR),
  CONSTRAINT MB_ACCT_RESTRICT_CK_TYPE CHECK (RESTRICTION_TYPE IN
    ('FREEZE','DEBIT_BLOCK','CREDIT_BLOCK','LIEN','PARTIAL_BLOCK')),
  CONSTRAINT MB_ACCT_RESTRICT_CK_STATUS CHECK (RESTRICTION_STATUS IN
    ('PENDING_APPLY','ACTIVE','PENDING_REMOVE','REMOVED','EXPIRED','FAILED')),
  CONSTRAINT MB_ACCT_RESTRICT_CK_AMOUNT CHECK
    ((RESTRICTION_TYPE IN ('LIEN','PARTIAL_BLOCK') AND RESTRICTION_AMOUNT IS NOT NULL AND RESTRICTION_AMOUNT > 0) OR
     (RESTRICTION_TYPE IN ('FREEZE','DEBIT_BLOCK','CREDIT_BLOCK') AND RESTRICTION_AMOUNT IS NULL)),
  CONSTRAINT MB_ACCT_RESTRICT_CK_DATES CHECK (ENDS_AT IS NULL OR ENDS_AT > STARTED_AT),
  CONSTRAINT MB_ACCT_RESTRICT_CK_SOURCE CHECK
    ((SOURCE_SYSTEM IS NULL AND SOURCE_REFERENCE IS NULL) OR
     (SOURCE_SYSTEM IS NOT NULL AND SOURCE_REFERENCE IS NOT NULL)),
  CONSTRAINT MB_ACCT_RESTRICT_CK_EFFECTIVE CHECK
    ((RESTRICTION_STATUS IN ('PENDING_APPLY','FAILED') AND EFFECTIVE_AT IS NULL) OR
     (RESTRICTION_STATUS IN ('ACTIVE','PENDING_REMOVE','REMOVED','EXPIRED') AND EFFECTIVE_AT IS NOT NULL)),
  CONSTRAINT MB_ACCT_RESTRICT_CK_REMOVED CHECK
    ((RESTRICTION_STATUS IN ('REMOVED','EXPIRED') AND REMOVED_AT IS NOT NULL) OR
     (RESTRICTION_STATUS NOT IN ('REMOVED','EXPIRED') AND REMOVED_AT IS NULL)),
  CONSTRAINT MB_ACCT_RESTRICT_CK_FAILURE CHECK
    ((RESTRICTION_STATUS = 'FAILED' AND FAILURE_CODE IS NOT NULL) OR
     (RESTRICTION_STATUS <> 'FAILED' AND FAILURE_CODE IS NULL)),
  CONSTRAINT MB_ACCT_RESTRICT_CK_REMOVED_AT CHECK
    (REMOVED_AT IS NULL OR REMOVED_AT >= STARTED_AT)
);
CREATE INDEX M04_ACCT_RESTRICT_IX_ACTIVE
  ON M04_ACCOUNT_RESTRICTION(ACCOUNT_ID, RESTRICTION_STATUS, RESTRICTION_TYPE);
-- A control is PENDING_APPLY until Module 5 closes the corresponding posting
-- fence or applies its lien/partial-block amount and acknowledges the version.
-- During PENDING_REMOVE the old restriction remains effective; REMOVED/EXPIRED
-- is recorded only after Module 5 acknowledges release. This closes freeze races.

CREATE TABLE M04_ACCOUNT_CONTROL_SYNC (
  CONTROL_SYNC_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER(19) NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  RESTRICTION_ID NUMBER(19) REFERENCES M04_ACCOUNT_RESTRICTION(RESTRICTION_ID),
  REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  CONTROL_VERSION NUMBER(19) NOT NULL,
  TARGET_ACTION VARCHAR2(12 CHAR) NOT NULL,
  CONTROL_TYPE VARCHAR2(30 CHAR) NOT NULL,
  CONTROL_AMOUNT NUMBER(18,2),
  SYNC_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
  SOURCE_EVENT_ID RAW(16) NOT NULL,
  MODULE5_ACK_EVENT_ID RAW(16),
  MODULE5_FENCE_VERSION NUMBER(19),
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ACKNOWLEDGED_AT TIMESTAMP(6) WITH TIME ZONE,
  FAILURE_CODE VARCHAR2(50 CHAR),
  CONSTRAINT MB_ACCT_CTRL_UQ_VERSION UNIQUE (ACCOUNT_ID, CONTROL_VERSION),
  CONSTRAINT MB_ACCT_CTRL_UQ_EVENT UNIQUE (SOURCE_EVENT_ID),
  CONSTRAINT MB_ACCT_CTRL_UQ_ACK UNIQUE (MODULE5_ACK_EVENT_ID),
  CONSTRAINT MB_ACCT_CTRL_CK_VERSION CHECK (CONTROL_VERSION > 0),
  CONSTRAINT MB_ACCT_CTRL_CK_ACTION CHECK (TARGET_ACTION IN ('APPLY','REMOVE')),
  CONSTRAINT MB_ACCT_CTRL_CK_TYPE CHECK (CONTROL_TYPE IN
    ('LIFECYCLE','FREEZE','DEBIT_BLOCK','CREDIT_BLOCK','LIEN','PARTIAL_BLOCK','OVERDRAFT')),
  CONSTRAINT MB_ACCT_CTRL_CK_STATUS CHECK (SYNC_STATUS IN
    ('PENDING','ACKNOWLEDGED','FAILED')),
  CONSTRAINT MB_ACCT_CTRL_CK_AMOUNT CHECK
    ((CONTROL_TYPE IN ('LIEN','PARTIAL_BLOCK','OVERDRAFT') AND CONTROL_AMOUNT IS NOT NULL AND CONTROL_AMOUNT >= 0) OR
     (CONTROL_TYPE IN ('LIFECYCLE','FREEZE','DEBIT_BLOCK','CREDIT_BLOCK') AND CONTROL_AMOUNT IS NULL)),
  CONSTRAINT MB_ACCT_CTRL_CK_ACK CHECK
    ((SYNC_STATUS = 'PENDING' AND ACKNOWLEDGED_AT IS NULL AND MODULE5_ACK_EVENT_ID IS NULL AND FAILURE_CODE IS NULL) OR
     (SYNC_STATUS = 'ACKNOWLEDGED' AND ACKNOWLEDGED_AT IS NOT NULL AND MODULE5_ACK_EVENT_ID IS NOT NULL AND FAILURE_CODE IS NULL) OR
     (SYNC_STATUS = 'FAILED' AND ACKNOWLEDGED_AT IS NOT NULL AND FAILURE_CODE IS NOT NULL))
);
CREATE INDEX M04_ACCT_CTRL_IX_PENDING
  ON M04_ACCOUNT_CONTROL_SYNC(SYNC_STATUS, REQUESTED_AT);

CREATE TABLE M04_ACCOUNT_FINANCIAL_PROJECTION_EVENT (
  PROJECTION_EVENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER(19) NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  SOURCE_EVENT_ID RAW(16) NOT NULL,
  EVENT_TYPE VARCHAR2(40 CHAR) NOT NULL,
  SOURCE_JOURNAL_ID NUMBER(19),
  SOURCE_POSTING_ID NUMBER(19),
  SOURCE_TRANSACTION_ID NUMBER(19),
  SOURCE_HOLD_ID NUMBER(19),
  PROJECTION_VERSION NUMBER(19) NOT NULL,
  LEDGER_DELTA NUMBER(18,2) DEFAULT 0 NOT NULL,
  BLOCKED_DELTA NUMBER(18,2) DEFAULT 0 NOT NULL,
  LIEN_DELTA NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDRAFT_DELTA NUMBER(18,2) DEFAULT 0 NOT NULL,
  LEDGER_BALANCE_AFTER NUMBER(18,2) NOT NULL,
  BLOCKED_BALANCE_AFTER NUMBER(18,2) NOT NULL,
  LIEN_BALANCE_AFTER NUMBER(18,2) NOT NULL,
  OVERDRAFT_LIMIT_AFTER NUMBER(18,2) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  APPLIED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  CONSTRAINT MB_ACCT_PROJ_UQ_VERSION UNIQUE (ACCOUNT_ID, PROJECTION_VERSION),
  CONSTRAINT MB_ACCT_PROJ_UQ_EVENT UNIQUE (SOURCE_EVENT_ID, ACCOUNT_ID),
  CONSTRAINT MB_ACCT_PROJ_UQ_POSTING UNIQUE (SOURCE_POSTING_ID),
  CONSTRAINT MB_ACCT_PROJ_CK_VERSION CHECK (PROJECTION_VERSION > 0),
  CONSTRAINT MB_ACCT_PROJ_CK_EVENT CHECK (EVENT_TYPE IN
    ('LEDGER_POSTED','HOLD_PLACED','HOLD_CONSUMED','HOLD_RELEASED','LIEN_APPLIED',
     'LIEN_RELEASED','PARTIAL_BLOCK_APPLIED','PARTIAL_BLOCK_RELEASED',
     'OVERDRAFT_CHANGED','RECONCILIATION_CORRECTION')),
  CONSTRAINT MB_ACCT_PROJ_CK_BALANCES CHECK
    (BLOCKED_BALANCE_AFTER >= 0 AND LIEN_BALANCE_AFTER >= 0 AND OVERDRAFT_LIMIT_AFTER >= 0)
);
CREATE INDEX M04_ACCT_PROJ_IX_ACCOUNT
  ON M04_ACCOUNT_FINANCIAL_PROJECTION_EVENT(ACCOUNT_ID, APPLIED_AT);
CREATE INDEX M04_ACCT_PROJ_IX_JOURNAL
  ON M04_ACCOUNT_FINANCIAL_PROJECTION_EVENT(SOURCE_JOURNAL_ID);
-- These two tables replace Account Management's former authoritative debit
-- reservation/capture model. Module 5 owns FUNDS_HOLD and ACCOUNT_POSITION;
-- Account Management consumes ledger/hold events solely to update its screen
-- projection and uses ACCOUNT_CONTROL_SYNC for the restriction/fence handshake.

CREATE TABLE M04_ACCOUNT_LIMIT (
  LIMIT_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  CHANGE_REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  LIMIT_TYPE VARCHAR2(40 CHAR) NOT NULL,
  OPERATION_CODE VARCHAR2(40 CHAR) NOT NULL,
  CHANNEL_CODE VARCHAR2(40 CHAR),
  PERIOD_CODE VARCHAR2(20 CHAR) NOT NULL,
  RESET_RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  TIME_ZONE_ID VARCHAR2(64 CHAR) NOT NULL,
  LIMIT_AMOUNT NUMBER(18,2) NOT NULL,
  PRODUCT_LIMIT_RULE_ID NUMBER,
  OVERRIDE_POLICY_ID NUMBER,
  EFFECTIVE_FROM DATE NOT NULL,
  EFFECTIVE_TO DATE,
  IS_ACTIVE CHAR(1) DEFAULT 'Y' NOT NULL,
  APPROVED_BY_USER_ID VARCHAR2(36 CHAR),
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_LIMIT_CK_AMOUNT CHECK (LIMIT_AMOUNT >= 0),
  CONSTRAINT MB_ACCT_LIMIT_CK_ACTIVE CHECK (IS_ACTIVE IN ('Y','N')),
  CONSTRAINT MB_ACCT_LIMIT_CK_DATES CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM),
  CONSTRAINT MB_ACCT_LIMIT_CK_APPROVAL CHECK
    (OVERRIDE_POLICY_ID IS NULL OR APPROVED_BY_USER_ID IS NOT NULL),
  CONSTRAINT MB_ACCT_LIMIT_CK_SEPARATION CHECK
    (APPROVED_BY_USER_ID IS NULL OR APPROVED_BY_USER_ID <> CREATED_BY_USER_ID)
);
CREATE INDEX M04_ACCT_LIMIT_IX_ACTIVE
  ON M04_ACCOUNT_LIMIT(ACCOUNT_ID, IS_ACTIVE, EFFECTIVE_FROM);
-- Product rule and override policy IDs are Product Master references. A
-- relaxation of the product limit requires an approved PM policy and IAM
-- authority check. More restrictive local limits need no PM override. Reset
-- rule/time zone make daily windows unambiguous; unsettled Module 5 holds count
-- toward usage. Version adoption revalidates or expires account overrides.

CREATE TABLE M04_ACCOUNT_INTEREST_OVERRIDE (
  INTEREST_OVERRIDE_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  CHANGE_REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  PRODUCT_VERSION_ID NUMBER NOT NULL,
  OVERRIDE_POLICY_ID NUMBER NOT NULL,
  RATE_PCT NUMBER(12,8) NOT NULL,
  REASON VARCHAR2(500 CHAR) NOT NULL,
  EFFECTIVE_FROM_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_FROM_UTC TIMESTAMP(6) GENERATED ALWAYS AS (SYS_EXTRACT_UTC(EFFECTIVE_FROM_AT)) VIRTUAL,
  EFFECTIVE_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_RATE_UQ_FROM UNIQUE (ACCOUNT_ID, EFFECTIVE_FROM_UTC),
  CONSTRAINT MB_ACCT_RATE_CK_VALUE CHECK (RATE_PCT >= 0),
  CONSTRAINT MB_ACCT_RATE_CK_SEPARATION CHECK
    (APPROVED_BY_USER_ID <> CREATED_BY_USER_ID),
  CONSTRAINT MB_ACCT_RATE_CK_DATES CHECK
    (EFFECTIVE_TO_AT IS NULL OR EFFECTIVE_TO_AT > EFFECTIVE_FROM_AT)
);
-- This versioned record replaces the lone INTEREST_RATE_OVERRIDE field in
-- module 4 DBML; it preserves approval, policy, and effective dates. Product
-- version adoption requires reapproval or expiry of incompatible overrides.

CREATE TABLE M04_ACCOUNT_PRODUCT_VERSION_HISTORY (
  ADOPTION_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  FROM_PRODUCT_VERSION_ID NUMBER NOT NULL,
  TO_PRODUCT_VERSION_ID NUMBER NOT NULL,
  VERSION_TREATMENT_ID NUMBER NOT NULL,
  TREATMENT_EVENT_ID VARCHAR2(36 CHAR) NOT NULL,
  CONSENT_REFERENCE VARCHAR2(80 CHAR),
  REASON_CODE VARCHAR2(50 CHAR) NOT NULL,
  ADOPTED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  ADOPTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  CONSTRAINT MB_ACCT_ADOPT_UQ_EVENT UNIQUE (ACCOUNT_ID, TREATMENT_EVENT_ID),
  CONSTRAINT MB_ACCT_ADOPT_CK_DIFFERENT CHECK
    (FROM_PRODUCT_VERSION_ID <> TO_PRODUCT_VERSION_ID)
);
CREATE INDEX M04_ACCT_ADOPT_IX_ACCOUNT
  ON M04_ACCOUNT_PRODUCT_VERSION_HISTORY(ACCOUNT_ID, ADOPTED_AT);
-- PM treatment and consent rules are validated at adoption. The service
-- updates BANK_ACCOUNT.PRODUCT_VERSION_ID and adds this history atomically.

CREATE TABLE M04_ACCOUNT_CLOSURE_REQUEST (
  CLOSURE_REQUEST_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  REQUEST_ID VARCHAR2(80 CHAR) NOT NULL UNIQUE,
  CLOSURE_REASON_CODE VARCHAR2(50 CHAR) NOT NULL,
  CLOSURE_REMARKS VARCHAR2(500 CHAR),
  PRE_CLOSURE_LIFECYCLE_STATUS VARCHAR2(20 CHAR) NOT NULL,
  REQUEST_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
  REQUESTED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  DECIDED_BY_USER_ID VARCHAR2(36 CHAR),
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  SETTLEMENT_CLEARANCE_REF VARCHAR2(80 CHAR),
  SETTLEMENT_CHECKED_AT TIMESTAMP(6) WITH TIME ZONE,
  CLEARED_ACCOUNT_ROW_VERSION NUMBER(10),
  REJECTION_REASON VARCHAR2(500 CHAR),
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  CONSTRAINT MB_ACCT_CLOSE_CK_STATUS CHECK
    (REQUEST_STATUS IN ('PENDING','APPROVED','REJECTED','CANCELLED')),
  CONSTRAINT MB_ACCT_CLOSE_CK_PREVIOUS CHECK
    (PRE_CLOSURE_LIFECYCLE_STATUS IN ('ACTIVE','DORMANT')),
  CONSTRAINT MB_ACCT_CLOSE_CK_DECISION CHECK
    ((REQUEST_STATUS = 'PENDING' AND DECIDED_BY_USER_ID IS NULL AND DECIDED_AT IS NULL) OR
     (REQUEST_STATUS IN ('APPROVED','REJECTED') AND DECIDED_BY_USER_ID IS NOT NULL AND DECIDED_AT IS NOT NULL) OR
     (REQUEST_STATUS = 'CANCELLED' AND DECIDED_BY_USER_ID IS NOT NULL AND DECIDED_AT IS NOT NULL)),
  CONSTRAINT MB_ACCT_CLOSE_CK_CLEARANCE CHECK
    (REQUEST_STATUS <> 'APPROVED' OR
     (SETTLEMENT_CLEARANCE_REF IS NOT NULL AND SETTLEMENT_CHECKED_AT IS NOT NULL
      AND CLEARED_ACCOUNT_ROW_VERSION IS NOT NULL)),
  CONSTRAINT MB_ACCT_CLOSE_CK_SEPARATION CHECK
    (DECIDED_BY_USER_ID IS NULL OR DECIDED_BY_USER_ID <> REQUESTED_BY_USER_ID),
  CONSTRAINT MB_ACCT_CLOSE_CK_REJECTION CHECK
    (REQUEST_STATUS <> 'REJECTED' OR REJECTION_REASON IS NOT NULL)
);
CREATE INDEX M04_ACCT_CLOSE_IX_ACCOUNT
  ON M04_ACCOUNT_CLOSURE_REQUEST(ACCOUNT_ID, REQUEST_STATUS);
CREATE UNIQUE INDEX M04_ACCT_CLOSE_UQ_PENDING
  ON M04_ACCOUNT_CLOSURE_REQUEST
    (CASE WHEN REQUEST_STATUS = 'PENDING' THEN ACCOUNT_ID END);
-- Enter CLOSING under an account lock, publish a versioned control event, and
-- wait for Module 5 to acknowledge a closed posting fence. Allow only controlled
-- settlement, return, reversal, and fee flows. Drain Module 5 holds and unresolved
-- payments; reconcile the ledger, settle accrued interest/fees, then require zero
-- position/hold/lien balances and no active restriction. Approval needs current IAM authority
-- and a fresh clearance reference tied to the locked account row version;
-- rejection/cancellation restores the prior lifecycle status. CLOSED is
-- terminal and account numbers are never reused. Late ledger postings must
-- be returned or reconciled outside the closed account.

CREATE TABLE M04_ACCOUNT_AUDIT_EVENT (
  AUDIT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  ACCOUNT_ID NUMBER NOT NULL REFERENCES M04_BANK_ACCOUNT(ACCOUNT_ID),
  ACTION_TYPE VARCHAR2(50 CHAR) NOT NULL,
  ACTOR_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  SESSION_ID VARCHAR2(36 CHAR),
  RESULT VARCHAR2(12 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(50 CHAR),
  BEFORE_STATE_HASH CHAR(64),
  AFTER_STATE_HASH CHAR(64),
  DETAILS_JSON CLOB,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_ACCT_AUDIT_CK_RESULT CHECK (RESULT IN ('SUCCESS','DENIED','FAILED')),
  CONSTRAINT MB_ACCT_AUDIT_CK_JSON CHECK (DETAILS_JSON IS JSON)
);
CREATE INDEX M04_ACCT_AUDIT_IX_ACCOUNT
  ON M04_ACCOUNT_AUDIT_EVENT(ACCOUNT_ID, OCCURRED_AT);

CREATE TABLE M04_ACCT_OUTBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(40 CHAR) DEFAULT 'ACCOUNT_MGMT' NOT NULL,
  SCHEMA_VERSION NUMBER(5) NOT NULL,
  AGGREGATE_TYPE VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(40 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(80 CHAR) NOT NULL,
  PAYLOAD CLOB NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  ATTEMPT_COUNT NUMBER(6) DEFAULT 0 NOT NULL,
  CONSTRAINT MB_ACCT_OUTBOX_CK_JSON CHECK (PAYLOAD IS JSON),
  CONSTRAINT MB_ACCT_OUTBOX_CK_ATTEMPTS CHECK (ATTEMPT_COUNT >= 0)
);
CREATE INDEX M04_ACCT_OUTBOX_IX_PENDING
  ON M04_ACCT_OUTBOX_EVENT(PUBLISHED_AT, OCCURRED_AT);

CREATE TABLE M04_ACCT_INBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(80 CHAR) NOT NULL,
  PRODUCER VARCHAR2(60 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(80 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE
);
CREATE INDEX M04_ACCT_INBOX_IX_PENDING
  ON M04_ACCT_INBOX_EVENT(PROCESSED_AT, RECEIVED_AT);

--------------------------------------------------------------------------------
-- MODULES 5 AND 6
--------------------------------------------------------------------------------
-- MODULE 5 - MB_TXN
--------------------------------------------------------------------------------

CREATE TABLE M05_TXN_TRANSACTION_LOG (
    TXN_ID                  NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ORIGINATOR_ID           VARCHAR2(64 CHAR) NOT NULL,
    CHANNEL_CODE            VARCHAR2(20 CHAR) NOT NULL,
    REQUEST_KEY             VARCHAR2(100 CHAR) NOT NULL,
    REQUEST_HASH            RAW(32) NOT NULL,
    CORRELATION_ID          VARCHAR2(100 CHAR) NOT NULL,
    TXN_TYPE                VARCHAR2(30 CHAR) NOT NULL,
    STATUS                  VARCHAR2(30 CHAR) NOT NULL,
    SOURCE_ACCOUNT_ID       NUMBER(19),
    TARGET_ACCOUNT_ID       NUMBER(19),
    LOAN_FACILITY_ID        NUMBER(19),
    PRODUCT_VERSION_ID      NUMBER(19),
    ACCOUNT_RESTRICTION_VERSION NUMBER(19),
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    VALUE_DATE              DATE NOT NULL,
    REVERSAL_OF_TXN_ID      NUMBER(19),
    FAILURE_CODE            VARCHAR2(50 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_TXN_TRANSACTION_LOG PRIMARY KEY (TXN_ID),
    CONSTRAINT MB_UK_TXN_REQUEST UNIQUE (ORIGINATOR_ID, CHANNEL_CODE, REQUEST_KEY),
    CONSTRAINT MB_FK_TXN_REVERSAL FOREIGN KEY (REVERSAL_OF_TXN_ID)
        REFERENCES M05_TXN_TRANSACTION_LOG (TXN_ID),
    CONSTRAINT MB_CK_TXN_AMOUNT_POSITIVE CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_TXN_CURRENCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_TXN_TYPE CHECK (TXN_TYPE IN
        ('OPENING_FUNDING','DEPOSIT','WITHDRAWAL','INTERNAL_TRANSFER','FEE','INTEREST',
         'ADJUSTMENT','REVERSAL','PAYMENT_DEBIT','PAYMENT_REFUND','SETTLEMENT','RETURN',
         'LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_ACCRUAL','LOAN_FEE',
         'LOAN_WAIVER','LOAN_WRITE_OFF','LOAN_SETTLEMENT')),
    CONSTRAINT MB_CK_TXN_STATUS CHECK (STATUS IN
        ('RECEIVED','VALIDATED','APPROVAL_PENDING','HELD','POSTED','REJECTED','REVERSED','FAILED','CANCELLED'))
);

CREATE INDEX M05_IX_TXN_SOURCE_ACCOUNT
    ON M05_TXN_TRANSACTION_LOG (SOURCE_ACCOUNT_ID, CREATED_AT);
CREATE INDEX M05_IX_TXN_TARGET_ACCOUNT
    ON M05_TXN_TRANSACTION_LOG (TARGET_ACCOUNT_ID, CREATED_AT);
CREATE INDEX M05_IX_TXN_CORRELATION
    ON M05_TXN_TRANSACTION_LOG (CORRELATION_ID);
CREATE INDEX M05_IX_TXN_LOAN_FACILITY
    ON M05_TXN_TRANSACTION_LOG (LOAN_FACILITY_ID, CREATED_AT);

CREATE TABLE M05_TXN_STATUS_HISTORY (
    TXN_STATUS_HISTORY_ID   NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    TXN_ID                  NUMBER(19) NOT NULL,
    FROM_STATUS             VARCHAR2(30 CHAR),
    TO_STATUS               VARCHAR2(30 CHAR) NOT NULL,
    ACTOR_ID                VARCHAR2(64 CHAR),
    REASON_CODE             VARCHAR2(50 CHAR),
    REASON_TEXT             VARCHAR2(500 CHAR),
    CHANGED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_TXN_STATUS_HISTORY PRIMARY KEY (TXN_STATUS_HISTORY_ID),
    CONSTRAINT MB_FK_TXN_STATUS_TXN FOREIGN KEY (TXN_ID)
        REFERENCES M05_TXN_TRANSACTION_LOG (TXN_ID)
);

CREATE INDEX M05_IX_TXN_STATUS_HISTORY
    ON M05_TXN_STATUS_HISTORY (TXN_ID, CHANGED_AT);

CREATE TABLE M05_GL_ACCOUNT (
    GL_ACCOUNT_ID           NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    GL_CODE                 VARCHAR2(40 CHAR) NOT NULL,
    GL_NAME                 VARCHAR2(120 CHAR) NOT NULL,
    ACCOUNT_CLASS           VARCHAR2(20 CHAR) NOT NULL,
    NORMAL_SIDE             CHAR(2 CHAR) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    ACTIVE_FLAG             CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_GL_ACCOUNT PRIMARY KEY (GL_ACCOUNT_ID),
    CONSTRAINT MB_UK_GL_ACCOUNT_CODE UNIQUE (GL_CODE),
    CONSTRAINT MB_CK_GL_ACCOUNT_CLASS CHECK (ACCOUNT_CLASS IN
        ('ASSET','LIABILITY','EQUITY','INCOME','EXPENSE')), 
    CONSTRAINT MB_CK_GL_NORMAL_SIDE CHECK (NORMAL_SIDE IN ('DR','CR')),
    CONSTRAINT MB_CK_GL_ACCOUNT_ACTIVE CHECK (ACTIVE_FLAG IN ('Y','N')),
    CONSTRAINT MB_CK_GL_ACCOUNT_CCY CHECK (CURRENCY_CODE = 'INR')
);

CREATE TABLE M05_GL_JOURNAL (
    JOURNAL_ID              NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    POSTING_KEY             VARCHAR2(120 CHAR) NOT NULL,
    TXN_ID                  NUMBER(19),
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    LOAN_FACILITY_ID        NUMBER(19),
    JOURNAL_TYPE            VARCHAR2(30 CHAR) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    BOOKED_AT               TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    VALUE_DATE              DATE NOT NULL,
    REVERSAL_OF_JOURNAL_ID  NUMBER(19),
    DESCRIPTION             VARCHAR2(500 CHAR),
    CREATED_BY              VARCHAR2(64 CHAR) NOT NULL,
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_GL_JOURNAL PRIMARY KEY (JOURNAL_ID),
    CONSTRAINT MB_UK_GL_POSTING_KEY UNIQUE (POSTING_KEY),
    CONSTRAINT MB_FK_GL_JOURNAL_TXN FOREIGN KEY (TXN_ID)
        REFERENCES M05_TXN_TRANSACTION_LOG (TXN_ID),
    CONSTRAINT MB_FK_GL_JOURNAL_REVERSAL FOREIGN KEY (REVERSAL_OF_JOURNAL_ID)
        REFERENCES M05_GL_JOURNAL (JOURNAL_ID),
    CONSTRAINT MB_UK_GL_JOURNAL_REVERSAL UNIQUE (REVERSAL_OF_JOURNAL_ID),
    CONSTRAINT MB_CK_GL_JOURNAL_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_GL_JOURNAL_TYPE CHECK (JOURNAL_TYPE IN
        ('OPENING_FUNDING','DEPOSIT','WITHDRAWAL','TRANSFER','FEE','INTEREST','ADJUSTMENT',
         'PAYMENT_PROVISIONAL','PAYMENT_REFUND','SETTLEMENT','RETURN',
         'LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_ACCRUAL','LOAN_FEE',
         'LOAN_WAIVER','LOAN_WRITE_OFF','LOAN_SETTLEMENT')),
    CONSTRAINT MB_CK_GL_JOURNAL_SCOPE CHECK
        ((TXN_ID IS NOT NULL OR PAYMENT_ID IS NOT NULL OR SETTLEMENT_CYCLE_ID IS NOT NULL)
         AND NOT (PAYMENT_ID IS NOT NULL AND SETTLEMENT_CYCLE_ID IS NOT NULL)),
    CONSTRAINT MB_UK_GL_JOURNAL_CCY UNIQUE (JOURNAL_ID, CURRENCY_CODE)
);

CREATE INDEX M05_IX_GL_JOURNAL_TXN ON M05_GL_JOURNAL (TXN_ID);
CREATE INDEX M05_IX_GL_JOURNAL_PAYMENT ON M05_GL_JOURNAL (PAYMENT_ID);
CREATE INDEX M05_IX_GL_JOURNAL_BOOKED ON M05_GL_JOURNAL (BOOKED_AT);
CREATE INDEX M05_IX_GL_JOURNAL_LOAN
    ON M05_GL_JOURNAL (LOAN_FACILITY_ID, BOOKED_AT);

CREATE TABLE M05_GL_POSTING (
    POSTING_ID              NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    JOURNAL_ID              NUMBER(19) NOT NULL,
    LINE_NO                 NUMBER(5) NOT NULL,
    GL_ACCOUNT_ID           NUMBER(19) NOT NULL,
    BANK_ACCOUNT_ID         NUMBER(19),
    LOAN_FACILITY_ID        NUMBER(19),
    LOAN_COMPONENT_CODE     VARCHAR2(20 CHAR),
    ENTRY_SIDE              CHAR(2 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    NARRATIVE               VARCHAR2(250 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_GL_POSTING PRIMARY KEY (POSTING_ID),
    CONSTRAINT MB_UK_GL_POSTING_LINE UNIQUE (JOURNAL_ID, LINE_NO),
    CONSTRAINT MB_FK_GL_POSTING_JOURNAL FOREIGN KEY (JOURNAL_ID, CURRENCY_CODE)
        REFERENCES M05_GL_JOURNAL (JOURNAL_ID, CURRENCY_CODE),
    CONSTRAINT MB_FK_GL_POSTING_ACCOUNT FOREIGN KEY (GL_ACCOUNT_ID)
        REFERENCES M05_GL_ACCOUNT (GL_ACCOUNT_ID),
    CONSTRAINT MB_CK_GL_POSTING_SIDE CHECK (ENTRY_SIDE IN ('DR','CR')),
    CONSTRAINT MB_CK_GL_POSTING_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_GL_POSTING_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_GL_POSTING_DIMENSION CHECK
      (NOT (BANK_ACCOUNT_ID IS NOT NULL AND LOAN_FACILITY_ID IS NOT NULL)),
    CONSTRAINT MB_CK_GL_POSTING_LOAN_COMPONENT CHECK
      ((LOAN_FACILITY_ID IS NULL AND LOAN_COMPONENT_CODE IS NULL) OR
       (LOAN_FACILITY_ID IS NOT NULL AND LOAN_COMPONENT_CODE IN
         ('PRINCIPAL','INTEREST','FEE','PENALTY','SUSPENSE','WRITE_OFF')))
);

CREATE INDEX M05_IX_GL_POSTING_ACCOUNT
    ON M05_GL_POSTING (GL_ACCOUNT_ID, JOURNAL_ID);
CREATE INDEX M05_IX_GL_POSTING_BANK_ACCOUNT
    ON M05_GL_POSTING (BANK_ACCOUNT_ID, JOURNAL_ID);
CREATE INDEX M05_IX_GL_POSTING_LOAN
    ON M05_GL_POSTING (LOAN_FACILITY_ID, LOAN_COMPONENT_CODE, JOURNAL_ID);

CREATE TABLE M05_ACCOUNT_POSITION (
    BANK_ACCOUNT_ID         NUMBER(19) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    POSTED_BALANCE          NUMBER(18,2) DEFAULT 0 NOT NULL,
    ACTIVE_HOLD_AMOUNT      NUMBER(18,2) DEFAULT 0 NOT NULL,
    ACTIVE_LIEN_AMOUNT      NUMBER(18,2) DEFAULT 0 NOT NULL,
    ACTIVE_BLOCK_AMOUNT     NUMBER(18,2) DEFAULT 0 NOT NULL,
    OVERDRAFT_LIMIT         NUMBER(18,2) DEFAULT 0 NOT NULL,
    SPENDABLE_BALANCE       NUMBER(18,2) GENERATED ALWAYS AS
        (POSTED_BALANCE - ACTIVE_HOLD_AMOUNT - ACTIVE_LIEN_AMOUNT
         - ACTIVE_BLOCK_AMOUNT + OVERDRAFT_LIMIT) VIRTUAL,
    LAST_JOURNAL_ID         NUMBER(19),
    POSITION_VERSION        NUMBER(19) DEFAULT 0 NOT NULL,
    APPLIED_CONTROL_VERSION NUMBER(19) DEFAULT 0 NOT NULL,
    AS_OF                   TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_ACCOUNT_POSITION PRIMARY KEY (BANK_ACCOUNT_ID, CURRENCY_CODE),
    CONSTRAINT MB_FK_POSITION_JOURNAL FOREIGN KEY (LAST_JOURNAL_ID)
        REFERENCES M05_GL_JOURNAL (JOURNAL_ID),
    CONSTRAINT MB_CK_POSITION_AMOUNTS CHECK
        (ACTIVE_HOLD_AMOUNT >= 0 AND ACTIVE_LIEN_AMOUNT >= 0
         AND ACTIVE_BLOCK_AMOUNT >= 0 AND OVERDRAFT_LIMIT >= 0),
    CONSTRAINT MB_CK_POSITION_VERSIONS CHECK
        (POSITION_VERSION >= 0 AND APPLIED_CONTROL_VERSION >= 0),
    CONSTRAINT MB_CK_POSITION_CCY CHECK (CURRENCY_CODE = 'INR')
);
-- POSTED_BALANCE is customer-facing (credits increase it and debits decrease it),
-- while GL_POSTING retains the bank's accounting DR/CR perspective.

CREATE TABLE M05_FUNDS_HOLD (
    HOLD_ID                 NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    BANK_ACCOUNT_ID         NUMBER(19) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'ACTIVE' NOT NULL,
    TXN_ID                  NUMBER(19),
    PAYMENT_ID              NUMBER(19),
    HOLD_KEY                VARCHAR2(120 CHAR) NOT NULL,
    EXPIRES_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSUMED_BY_JOURNAL_ID  NUMBER(19),
    RELEASE_REASON          VARCHAR2(50 CHAR),
    CLOSED_AT               TIMESTAMP(6) WITH TIME ZONE,
    VERSION_NO              NUMBER(10) DEFAULT 0 NOT NULL,
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_FUNDS_HOLD PRIMARY KEY (HOLD_ID),
    CONSTRAINT MB_UK_FUNDS_HOLD_KEY UNIQUE (HOLD_KEY),
    CONSTRAINT MB_FK_HOLD_TXN FOREIGN KEY (TXN_ID)
        REFERENCES M05_TXN_TRANSACTION_LOG (TXN_ID),
    CONSTRAINT MB_FK_HOLD_JOURNAL FOREIGN KEY (CONSUMED_BY_JOURNAL_ID)
        REFERENCES M05_GL_JOURNAL (JOURNAL_ID),
    CONSTRAINT MB_CK_HOLD_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_HOLD_STATUS CHECK (STATUS IN ('ACTIVE','CONSUMED','RELEASED','EXPIRED')),
    CONSTRAINT MB_CK_HOLD_OWNER CHECK
        ((TXN_ID IS NOT NULL AND PAYMENT_ID IS NULL) OR
         (TXN_ID IS NULL AND PAYMENT_ID IS NOT NULL)),
    CONSTRAINT MB_CK_HOLD_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_HOLD_TERMINAL CHECK
        ((STATUS = 'ACTIVE' AND CLOSED_AT IS NULL AND CONSUMED_BY_JOURNAL_ID IS NULL) OR
         (STATUS = 'CONSUMED' AND CLOSED_AT IS NOT NULL AND CONSUMED_BY_JOURNAL_ID IS NOT NULL) OR
         (STATUS IN ('RELEASED','EXPIRED') AND CLOSED_AT IS NOT NULL AND CONSUMED_BY_JOURNAL_ID IS NULL)),
    CONSTRAINT MB_CK_HOLD_RELEASE_REASON CHECK
        ((STATUS IN ('RELEASED','EXPIRED') AND RELEASE_REASON IS NOT NULL) OR
         (STATUS IN ('ACTIVE','CONSUMED') AND RELEASE_REASON IS NULL))
);
CREATE UNIQUE INDEX M05_UX_HOLD_TXN
    ON M05_FUNDS_HOLD (CASE WHEN TXN_ID IS NOT NULL THEN TXN_ID END);
CREATE UNIQUE INDEX M05_UX_HOLD_PAYMENT
    ON M05_FUNDS_HOLD (CASE WHEN PAYMENT_ID IS NOT NULL THEN PAYMENT_ID END);
CREATE INDEX M05_IX_HOLD_ACCOUNT_STATUS
    ON M05_FUNDS_HOLD (BANK_ACCOUNT_ID, STATUS, EXPIRES_AT);
-- Expiry is not authority to release an externally uncertain payment. The hold
-- service must reconcile payment state before moving ACTIVE to EXPIRED/RELEASED.

CREATE TABLE M05_POSTING_FENCE (
    BANK_ACCOUNT_ID         NUMBER(19) NOT NULL,
    DEBIT_STATUS            VARCHAR2(10 CHAR) DEFAULT 'CLOSED' NOT NULL,
    CREDIT_STATUS           VARCHAR2(10 CHAR) DEFAULT 'CLOSED' NOT NULL,
    CONTROL_VERSION         NUMBER(19) DEFAULT 0 NOT NULL,
    SOURCE_EVENT_ID         RAW(16),
    REASON_CODE             VARCHAR2(50 CHAR),
    CHANGED_BY              VARCHAR2(64 CHAR) NOT NULL,
    CHANGED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_POSTING_FENCE PRIMARY KEY (BANK_ACCOUNT_ID),
    CONSTRAINT MB_UK_POSTING_FENCE_EVENT UNIQUE (SOURCE_EVENT_ID),
    CONSTRAINT MB_CK_FENCE_DEBIT CHECK (DEBIT_STATUS IN ('OPEN','CLOSED')),
    CONSTRAINT MB_CK_FENCE_CREDIT CHECK (CREDIT_STATUS IN ('OPEN','CLOSED')),
    CONSTRAINT MB_CK_FENCE_VERSION CHECK (CONTROL_VERSION >= 0)
);

CREATE TABLE M05_POSTING_FENCE_HISTORY (
    FENCE_HISTORY_ID        NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    BANK_ACCOUNT_ID         NUMBER(19) NOT NULL,
    CONTROL_VERSION         NUMBER(19) NOT NULL,
    SOURCE_EVENT_ID         RAW(16) NOT NULL,
    OLD_DEBIT_STATUS        VARCHAR2(10 CHAR),
    NEW_DEBIT_STATUS        VARCHAR2(10 CHAR) NOT NULL,
    OLD_CREDIT_STATUS       VARCHAR2(10 CHAR),
    NEW_CREDIT_STATUS       VARCHAR2(10 CHAR) NOT NULL,
    LIEN_AMOUNT_AFTER       NUMBER(18,2) NOT NULL,
    BLOCK_AMOUNT_AFTER      NUMBER(18,2) NOT NULL,
    REASON_CODE             VARCHAR2(50 CHAR),
    APPLIED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_POSTING_FENCE_HISTORY PRIMARY KEY (FENCE_HISTORY_ID),
    CONSTRAINT MB_FK_FENCE_HISTORY_FENCE FOREIGN KEY (BANK_ACCOUNT_ID)
        REFERENCES M05_POSTING_FENCE (BANK_ACCOUNT_ID),
    CONSTRAINT MB_UK_FENCE_HISTORY_VERSION UNIQUE (BANK_ACCOUNT_ID, CONTROL_VERSION),
    CONSTRAINT MB_UK_FENCE_HISTORY_EVENT UNIQUE (SOURCE_EVENT_ID),
    CONSTRAINT MB_CK_FENCE_HISTORY_DEBIT CHECK
        (NEW_DEBIT_STATUS IN ('OPEN','CLOSED') AND (OLD_DEBIT_STATUS IS NULL OR OLD_DEBIT_STATUS IN ('OPEN','CLOSED'))),
    CONSTRAINT MB_CK_FENCE_HISTORY_CREDIT CHECK
        (NEW_CREDIT_STATUS IN ('OPEN','CLOSED') AND (OLD_CREDIT_STATUS IS NULL OR OLD_CREDIT_STATUS IN ('OPEN','CLOSED'))),
    CONSTRAINT MB_CK_FENCE_HISTORY_AMOUNTS CHECK
        (LIEN_AMOUNT_AFTER >= 0 AND BLOCK_AMOUNT_AFTER >= 0)
);
CREATE INDEX M05_IX_FENCE_HISTORY_ACCOUNT
    ON M05_POSTING_FENCE_HISTORY(BANK_ACCOUNT_ID, APPLIED_AT);
-- New accounts begin closed. Activation opens the permitted directions only
-- after Account Management's versioned control event is applied under the same
-- lock used for spend checks. Stale or out-of-order versions are rejected.

CREATE TABLE M05_IDEMPOTENCY_RECORD (
    IDEMPOTENCY_ID          NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ORIGINATOR_ID           VARCHAR2(64 CHAR) NOT NULL,
    CHANNEL_CODE            VARCHAR2(20 CHAR) NOT NULL,
    REQUEST_KEY             VARCHAR2(100 CHAR) NOT NULL,
    REQUEST_HASH            RAW(32) NOT NULL,
    RESOURCE_TYPE           VARCHAR2(30 CHAR) NOT NULL,
    RESOURCE_ID             NUMBER(19),
    HTTP_STATUS             NUMBER(3),
    RESPONSE_REF            VARCHAR2(250 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    EXPIRES_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_TXN_IDEMPOTENCY PRIMARY KEY (IDEMPOTENCY_ID),
    CONSTRAINT MB_UK_TXN_IDEMPOTENCY UNIQUE (ORIGINATOR_ID, CHANNEL_CODE, REQUEST_KEY)
);

CREATE TABLE M05_VELOCITY_USAGE (
    SUBJECT_TYPE            VARCHAR2(20 CHAR) NOT NULL,
    SUBJECT_ID              VARCHAR2(100 CHAR) NOT NULL,
    CONTROL_CODE            VARCHAR2(50 CHAR) NOT NULL,
    WINDOW_START            TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    WINDOW_START_UTC        TIMESTAMP(6) GENERATED ALWAYS AS (SYS_EXTRACT_UTC(WINDOW_START)) VIRTUAL,
    WINDOW_END              TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    TXN_COUNT               NUMBER(10) DEFAULT 0 NOT NULL,
    TOTAL_AMOUNT            NUMBER(18,2) DEFAULT 0 NOT NULL,
    VERSION_NO              NUMBER(10) DEFAULT 0 NOT NULL,
    UPDATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_VELOCITY_USAGE PRIMARY KEY
        (SUBJECT_TYPE, SUBJECT_ID, CONTROL_CODE, WINDOW_START_UTC),
    CONSTRAINT MB_CK_VELOCITY_SUBJECT CHECK (SUBJECT_TYPE IN
        ('ACCOUNT','CUSTOMER','CHANNEL','BENEFICIARY')),
    CONSTRAINT MB_CK_VELOCITY_WINDOW CHECK (WINDOW_END > WINDOW_START),
    CONSTRAINT MB_CK_VELOCITY_VALUES CHECK (TXN_COUNT >= 0 AND TOTAL_AMOUNT >= 0)
);

CREATE INDEX M05_IX_VELOCITY_EXPIRY
    ON M05_VELOCITY_USAGE (WINDOW_END);

CREATE TABLE M05_TXN_APPROVAL (
    APPROVAL_ID             NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    APPROVAL_KEY            VARCHAR2(120 CHAR) NOT NULL,
    TXN_ID                  NUMBER(19) NOT NULL,
    ACTION_CODE             VARCHAR2(30 CHAR) NOT NULL,
    MAKER_ID                VARCHAR2(64 CHAR) NOT NULL,
    CHECKER_ID              VARCHAR2(64 CHAR),
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    REASON_TEXT             VARCHAR2(500 CHAR) NOT NULL,
    REQUESTED_AT            TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    DECIDED_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_TXN_APPROVAL PRIMARY KEY (APPROVAL_ID),
    CONSTRAINT MB_FK_TXN_APPROVAL_TXN FOREIGN KEY (TXN_ID)
        REFERENCES M05_TXN_TRANSACTION_LOG (TXN_ID),
    CONSTRAINT MB_UK_TXN_APPROVAL_KEY UNIQUE (APPROVAL_KEY),
    CONSTRAINT MB_CK_TXN_APPROVAL_ACTION CHECK (ACTION_CODE IN
        ('ADJUSTMENT','REVERSAL','MANUAL_POSTING')),
    CONSTRAINT MB_CK_TXN_APPROVAL_STATUS CHECK (STATUS IN
        ('PENDING','APPROVED','REJECTED','CANCELLED')),
    CONSTRAINT MB_CK_TXN_APPROVAL_SOD CHECK
        (CHECKER_ID IS NULL OR CHECKER_ID <> MAKER_ID),
    CONSTRAINT MB_CK_TXN_APPROVAL_DECISION CHECK
        ((STATUS = 'PENDING' AND CHECKER_ID IS NULL AND DECIDED_AT IS NULL) OR
         (STATUS IN ('APPROVED','REJECTED') AND CHECKER_ID IS NOT NULL AND DECIDED_AT IS NOT NULL) OR
         (STATUS = 'CANCELLED' AND DECIDED_AT IS NOT NULL))
);

CREATE TABLE M05_SECURITY_AUDIT_EVENT (
    AUDIT_EVENT_ID          NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ACTOR_ID                VARCHAR2(64 CHAR) NOT NULL,
    SESSION_ID              VARCHAR2(100 CHAR),
    CORRELATION_ID          VARCHAR2(100 CHAR),
    ACTION_CODE             VARCHAR2(80 CHAR) NOT NULL,
    RESOURCE_TYPE           VARCHAR2(40 CHAR) NOT NULL,
    RESOURCE_ID             VARCHAR2(100 CHAR),
    RESULT_CODE             VARCHAR2(30 CHAR) NOT NULL,
    REASON_CODE             VARCHAR2(50 CHAR),
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_TXN_SECURITY_AUDIT PRIMARY KEY (AUDIT_EVENT_ID)
);

CREATE INDEX M05_IX_TXN_AUDIT_RESOURCE
    ON M05_SECURITY_AUDIT_EVENT (RESOURCE_TYPE, RESOURCE_ID, OCCURRED_AT);

CREATE TABLE M05_OUTBOX_EVENT (
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    SCHEMA_VERSION          NUMBER(5) NOT NULL,
    AGGREGATE_TYPE          VARCHAR2(30 CHAR) NOT NULL,
    AGGREGATE_ID            VARCHAR2(100 CHAR) NOT NULL,
    CORRELATION_ID          VARCHAR2(100 CHAR),
    CAUSATION_ID            VARCHAR2(100 CHAR),
    PARTITION_KEY           VARCHAR2(100 CHAR) NOT NULL,
    PAYLOAD_JSON            CLOB NOT NULL,
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    AVAILABLE_AT            TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PUBLISH_STATUS          VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    PUBLISHED_AT            TIMESTAMP(6) WITH TIME ZONE,
    PUBLISH_ATTEMPTS        NUMBER(10) DEFAULT 0 NOT NULL,
    LOCKED_BY               VARCHAR2(100 CHAR),
    LOCKED_UNTIL            TIMESTAMP(6) WITH TIME ZONE,
    LAST_ERROR              VARCHAR2(1000 CHAR),
    CONSTRAINT MB_PK_TXN_OUTBOX PRIMARY KEY (EVENT_ID),
    CONSTRAINT MB_CK_TXN_OUTBOX_JSON CHECK (PAYLOAD_JSON IS JSON),
    CONSTRAINT MB_CK_TXN_OUTBOX_STATUS CHECK (PUBLISH_STATUS IN
        ('PENDING','CLAIMED','PUBLISHED','DEAD_LETTER')),
    CONSTRAINT MB_CK_TXN_OUTBOX_PUBLISHED CHECK
        ((PUBLISH_STATUS = 'PUBLISHED' AND PUBLISHED_AT IS NOT NULL) OR
         (PUBLISH_STATUS <> 'PUBLISHED' AND PUBLISHED_AT IS NULL))
);

CREATE INDEX M05_IX_TXN_OUTBOX_PENDING
    ON M05_OUTBOX_EVENT (PUBLISH_STATUS, AVAILABLE_AT, LOCKED_UNTIL);

CREATE TABLE M05_CONSUMER_INBOX (
    CONSUMER_NAME           VARCHAR2(100 CHAR) NOT NULL,
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    RECEIVED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PROCESSED_AT            TIMESTAMP(6) WITH TIME ZONE,
    RESULT_CODE             VARCHAR2(30 CHAR),
    CONSTRAINT MB_PK_TXN_CONSUMER_INBOX PRIMARY KEY (CONSUMER_NAME, EVENT_ID)
);

--------------------------------------------------------------------------------
CREATE TABLE M05_TXN_STATE_TRANSITION (
    FROM_STATUS VARCHAR2(30 CHAR) NOT NULL,
    TO_STATUS VARCHAR2(30 CHAR) NOT NULL,
    CONSTRAINT MB_PK_TXN_STATE_TRANSITION PRIMARY KEY (FROM_STATUS, TO_STATUS)
);

INSERT ALL
  INTO M05_TXN_STATE_TRANSITION VALUES ('RECEIVED','VALIDATED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('RECEIVED','APPROVAL_PENDING')
  INTO M05_TXN_STATE_TRANSITION VALUES ('RECEIVED','REJECTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('RECEIVED','FAILED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('RECEIVED','CANCELLED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('APPROVAL_PENDING','VALIDATED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('APPROVAL_PENDING','REJECTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('APPROVAL_PENDING','CANCELLED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('VALIDATED','HELD')
  INTO M05_TXN_STATE_TRANSITION VALUES ('VALIDATED','POSTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('VALIDATED','REJECTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('VALIDATED','FAILED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('HELD','POSTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('HELD','REJECTED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('HELD','FAILED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('HELD','CANCELLED')
  INTO M05_TXN_STATE_TRANSITION VALUES ('POSTED','REVERSED')
SELECT 1 FROM DUAL;

ALTER TABLE M05_TXN_STATUS_HISTORY ADD CONSTRAINT MB_CK_TXN_HISTORY_TO_STATUS
  CHECK (TO_STATUS IN ('RECEIVED','VALIDATED','APPROVAL_PENDING','HELD','POSTED','REJECTED','REVERSED','FAILED','CANCELLED'));
ALTER TABLE M05_TXN_STATUS_HISTORY ADD CONSTRAINT MB_CK_TXN_HISTORY_FROM_STATUS
  CHECK (FROM_STATUS IS NULL OR FROM_STATUS IN ('RECEIVED','VALIDATED','APPROVAL_PENDING','HELD','POSTED','REJECTED','REVERSED','FAILED','CANCELLED'));
ALTER TABLE M05_TXN_STATUS_HISTORY ADD CONSTRAINT MB_FK_TXN_HISTORY_TRANSITION
  FOREIGN KEY (FROM_STATUS, TO_STATUS)
  REFERENCES M05_TXN_STATE_TRANSITION(FROM_STATUS, TO_STATUS);

-- MODULE 6 - MB_PAY
--------------------------------------------------------------------------------

CREATE TABLE M06_PAYMENT_INSTRUCTION (
    PAYMENT_ID              NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ORIGINATOR_ID           VARCHAR2(64 CHAR) NOT NULL,
    CHANNEL_CODE            VARCHAR2(20 CHAR) NOT NULL,
    REQUEST_KEY             VARCHAR2(100 CHAR) NOT NULL,
    REQUEST_HASH            RAW(32) NOT NULL,
    CORRELATION_ID          VARCHAR2(100 CHAR) NOT NULL,
    END_TO_END_ID           VARCHAR2(100 CHAR) NOT NULL,
    PAYMENT_DIRECTION       VARCHAR2(10 CHAR) DEFAULT 'OUTBOUND' NOT NULL,
    PAYMENT_KIND            VARCHAR2(10 CHAR) DEFAULT 'PAYMENT' NOT NULL,
    ORIGINAL_PAYMENT_ID     NUMBER(19),
    SOURCE_ACCOUNT_ID       NUMBER(19),
    SOURCE_CIF_ID           VARCHAR2(36 CHAR),
    DESTINATION_ACCOUNT_ID  NUMBER(19),
    DESTINATION_CIF_ID      VARCHAR2(36 CHAR),
    BENEFICIARY_TOKEN_REF   VARCHAR2(120 CHAR),
    BENEFICIARY_BANK_CODE   VARCHAR2(30 CHAR),
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    REQUESTED_EXECUTION_DATE DATE NOT NULL,
    STATUS                  VARCHAR2(30 CHAR) NOT NULL,
    VERSION_NO              NUMBER(10) DEFAULT 0 NOT NULL,
    HOLD_ID                 NUMBER(19),
    CUSTOMER_TXN_ID         NUMBER(19),
    CLEARING_BATCH_ID       NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    LIQUIDITY_HOLD_ID       NUMBER(19),
    RAIL_MESSAGE_ID         VARCHAR2(100 CHAR),
    RAIL_REFERENCE          VARCHAR2(100 CHAR),
    REASON_CODE             VARCHAR2(50 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_PAYMENT_INSTRUCTION PRIMARY KEY (PAYMENT_ID),
    CONSTRAINT MB_UK_PAYMENT_REQUEST UNIQUE (ORIGINATOR_ID, CHANNEL_CODE, REQUEST_KEY),
    CONSTRAINT MB_UK_PAYMENT_END_TO_END UNIQUE (END_TO_END_ID),
    CONSTRAINT MB_FK_PAYMENT_ORIGINAL FOREIGN KEY (ORIGINAL_PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_CK_PAYMENT_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_PAYMENT_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_PAYMENT_RAIL CHECK (RAIL_CODE IN ('UPI','IMPS','NEFT','RTGS')),
    CONSTRAINT MB_CK_PAYMENT_DIRECTION CHECK (PAYMENT_DIRECTION IN ('OUTBOUND','INBOUND')),
    CONSTRAINT MB_CK_PAYMENT_KIND CHECK (PAYMENT_KIND IN ('PAYMENT','RETURN')),
    CONSTRAINT MB_CK_PAYMENT_RETURN_LINK CHECK
        ((PAYMENT_KIND = 'PAYMENT' AND ORIGINAL_PAYMENT_ID IS NULL) OR
         (PAYMENT_KIND = 'RETURN' AND ORIGINAL_PAYMENT_ID IS NOT NULL)),
    CONSTRAINT MB_CK_PAYMENT_PARTIES CHECK
        ((PAYMENT_DIRECTION = 'OUTBOUND' AND SOURCE_ACCOUNT_ID IS NOT NULL
          AND SOURCE_CIF_ID IS NOT NULL AND BENEFICIARY_TOKEN_REF IS NOT NULL
          AND BENEFICIARY_BANK_CODE IS NOT NULL) OR
         (PAYMENT_DIRECTION = 'INBOUND' AND DESTINATION_ACCOUNT_ID IS NOT NULL
          AND DESTINATION_CIF_ID IS NOT NULL)),
    CONSTRAINT MB_CK_PAYMENT_STATUS CHECK (STATUS IN
        ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN',
         'SETTLEMENT_PENDING','SETTLED','REJECTED','REFUNDED','CANCELLED'))
);

CREATE INDEX M06_IX_PAYMENT_SOURCE_ACCOUNT
    ON M06_PAYMENT_INSTRUCTION (SOURCE_ACCOUNT_ID, CREATED_AT);
CREATE INDEX M06_IX_PAYMENT_DEST_ACCOUNT
    ON M06_PAYMENT_INSTRUCTION (DESTINATION_ACCOUNT_ID, CREATED_AT);
CREATE INDEX M06_IX_PAYMENT_ORIGINAL
    ON M06_PAYMENT_INSTRUCTION (ORIGINAL_PAYMENT_ID);
CREATE INDEX M06_IX_PAYMENT_STATUS
    ON M06_PAYMENT_INSTRUCTION (STATUS, UPDATED_AT);
CREATE INDEX M06_IX_PAYMENT_BATCH
    ON M06_PAYMENT_INSTRUCTION (CLEARING_BATCH_ID);

-- Function-based unique indexes allow many NULL values while enforcing uniqueness
-- once the rail identifiers are assigned.
CREATE UNIQUE INDEX M06_UX_PAYMENT_RAIL_MESSAGE
    ON M06_PAYMENT_INSTRUCTION (
        CASE WHEN RAIL_MESSAGE_ID IS NOT NULL THEN RAIL_CODE END,
        CASE WHEN RAIL_MESSAGE_ID IS NOT NULL THEN RAIL_MESSAGE_ID END
    );

CREATE UNIQUE INDEX M06_UX_PAYMENT_RAIL_REFERENCE
    ON M06_PAYMENT_INSTRUCTION (
        CASE WHEN RAIL_REFERENCE IS NOT NULL THEN RAIL_CODE END,
        CASE WHEN RAIL_REFERENCE IS NOT NULL THEN RAIL_REFERENCE END
    );

CREATE TABLE M06_PAYMENT_STATUS_HISTORY (
    PAYMENT_STATUS_HISTORY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    FROM_STATUS             VARCHAR2(30 CHAR),
    TO_STATUS               VARCHAR2(30 CHAR) NOT NULL,
    ACTOR_TYPE              VARCHAR2(20 CHAR) NOT NULL,
    ACTOR_ID                VARCHAR2(64 CHAR),
    REASON_CODE             VARCHAR2(50 CHAR),
    EVIDENCE_ID             NUMBER(19),
    CHANGED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_PAYMENT_STATUS_HISTORY PRIMARY KEY (PAYMENT_STATUS_HISTORY_ID),
    CONSTRAINT MB_FK_PAYMENT_STATUS_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_CK_PAYMENT_ACTOR_TYPE CHECK (ACTOR_TYPE IN
        ('USER','SERVICE','RAIL','TREASURY','OPERATIONS'))
);

CREATE INDEX M06_IX_PAYMENT_STATUS_HISTORY
    ON M06_PAYMENT_STATUS_HISTORY (PAYMENT_ID, CHANGED_AT);

CREATE TABLE M06_RAIL_DISPATCH (
    DISPATCH_ID             NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    RAIL_MESSAGE_ID         VARCHAR2(100 CHAR) NOT NULL,
    PAYLOAD_REF             VARCHAR2(250 CHAR) NOT NULL,
    DISPATCH_STATUS         VARCHAR2(20 CHAR) NOT NULL,
    ATTEMPT_COUNT           NUMBER(10) DEFAULT 0 NOT NULL,
    FIRST_DISPATCHED_AT     TIMESTAMP(6) WITH TIME ZONE,
    LAST_ATTEMPT_AT         TIMESTAMP(6) WITH TIME ZONE,
    LAST_ERROR_CODE         VARCHAR2(50 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_RAIL_DISPATCH PRIMARY KEY (DISPATCH_ID),
    CONSTRAINT MB_FK_DISPATCH_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_UK_DISPATCH_PAYMENT UNIQUE (PAYMENT_ID),
    CONSTRAINT MB_UK_DISPATCH_MESSAGE UNIQUE (RAIL_CODE, RAIL_MESSAGE_ID),
    CONSTRAINT MB_CK_DISPATCH_STATUS CHECK (DISPATCH_STATUS IN
        ('READY','SENDING','SENT','ACKNOWLEDGED','INQUIRY_REQUIRED','FAILED'))
);

CREATE TABLE M06_RAIL_DISPATCH_ATTEMPT (
    DISPATCH_ATTEMPT_ID     NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    DISPATCH_ID             NUMBER(19) NOT NULL,
    ATTEMPT_NO              NUMBER(10) NOT NULL,
    ATTEMPT_TYPE            VARCHAR2(20 CHAR) NOT NULL,
    OUTCOME_CODE            VARCHAR2(30 CHAR) NOT NULL,
    TRANSPORT_REFERENCE     VARCHAR2(120 CHAR),
    ERROR_CODE              VARCHAR2(50 CHAR),
    STARTED_AT              TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    COMPLETED_AT            TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_RAIL_DISPATCH_ATTEMPT PRIMARY KEY (DISPATCH_ATTEMPT_ID),
    CONSTRAINT MB_FK_DISPATCH_ATTEMPT FOREIGN KEY (DISPATCH_ID)
        REFERENCES M06_RAIL_DISPATCH (DISPATCH_ID),
    CONSTRAINT MB_UK_DISPATCH_ATTEMPT UNIQUE (DISPATCH_ID, ATTEMPT_NO),
    CONSTRAINT MB_CK_DISPATCH_ATTEMPT_TYPE CHECK (ATTEMPT_TYPE IN ('SEND','INQUIRY')),
    CONSTRAINT MB_CK_DISPATCH_OUTCOME CHECK (OUTCOME_CODE IN
        ('STARTED','SENT','ACKNOWLEDGED','TIMEOUT','REJECTED','ERROR'))
);

CREATE TABLE M06_RAIL_STATUS_EVIDENCE (
    EVIDENCE_ID             NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    RAIL_MESSAGE_ID         VARCHAR2(100 CHAR) NOT NULL,
    EXTERNAL_REFERENCE      VARCHAR2(120 CHAR),
    EVIDENCE_TYPE           VARCHAR2(30 CHAR) NOT NULL,
    RAIL_STATUS             VARCHAR2(30 CHAR) NOT NULL,
    REASON_CODE             VARCHAR2(50 CHAR),
    EVIDENCE_HASH           RAW(32) NOT NULL,
    EVIDENCE_REF            VARCHAR2(250 CHAR),
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE,
    RECEIVED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_RAIL_STATUS_EVIDENCE PRIMARY KEY (EVIDENCE_ID),
    CONSTRAINT MB_FK_EVIDENCE_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_UK_RAIL_EVIDENCE_HASH UNIQUE (RAIL_CODE, EVIDENCE_HASH),
    CONSTRAINT MB_CK_EVIDENCE_TYPE CHECK (EVIDENCE_TYPE IN
        ('ACKNOWLEDGEMENT','CALLBACK','INQUIRY','CLEARING','SETTLEMENT','RETURN')),
    CONSTRAINT MB_CK_RAIL_STATUS CHECK (RAIL_STATUS IN
        ('ACCEPTED','REJECTED','PENDING','SETTLED','RETURNED','UNKNOWN'))
);

CREATE INDEX M06_IX_EVIDENCE_PAYMENT
    ON M06_RAIL_STATUS_EVIDENCE (PAYMENT_ID, RECEIVED_AT);

ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_FK_PAY_STATUS_EVIDENCE
    FOREIGN KEY (EVIDENCE_ID) REFERENCES M06_RAIL_STATUS_EVIDENCE (EVIDENCE_ID);

CREATE TABLE M06_CLEARING_BATCH (
    CLEARING_BATCH_ID       NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    BATCH_REFERENCE         VARCHAR2(100 CHAR) NOT NULL,
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    BATCH_STATUS            VARCHAR2(20 CHAR) NOT NULL,
    BATCH_DIRECTION         VARCHAR2(10 CHAR) DEFAULT 'NET' NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    ITEM_COUNT              NUMBER(10) DEFAULT 0 NOT NULL,
    TOTAL_AMOUNT            NUMBER(18,2) DEFAULT 0 NOT NULL,
    GROSS_OUT_AMOUNT        NUMBER(18,2) DEFAULT 0 NOT NULL,
    GROSS_IN_AMOUNT         NUMBER(18,2) DEFAULT 0 NOT NULL,
    NET_AMOUNT              NUMBER(18,2) DEFAULT 0 NOT NULL,
    NET_MOVEMENT_SIDE       VARCHAR2(3 CHAR),
    OPENED_AT               TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CLOSED_AT               TIMESTAMP(6) WITH TIME ZONE,
    SETTLED_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_CLEARING_BATCH PRIMARY KEY (CLEARING_BATCH_ID),
    CONSTRAINT MB_UK_CLEARING_BATCH_REF UNIQUE (RAIL_CODE, BATCH_REFERENCE),
    CONSTRAINT MB_CK_BATCH_STATUS CHECK (BATCH_STATUS IN
        ('OPEN','CLOSED','SUBMITTED','SETTLEMENT_PENDING','SETTLED','EXCEPTION')),
    CONSTRAINT MB_CK_BATCH_TOTALS CHECK (ITEM_COUNT >= 0 AND TOTAL_AMOUNT >= 0),
    CONSTRAINT MB_CK_BATCH_GROSS CHECK (GROSS_OUT_AMOUNT >= 0 AND GROSS_IN_AMOUNT >= 0),
    CONSTRAINT MB_CK_BATCH_DIRECTION CHECK (BATCH_DIRECTION IN ('OUTBOUND','INBOUND','NET')),
    CONSTRAINT MB_CK_BATCH_NET_SIDE CHECK (NET_MOVEMENT_SIDE IS NULL OR NET_MOVEMENT_SIDE IN ('IN','OUT')),
    CONSTRAINT MB_CK_BATCH_CCY CHECK (CURRENCY_CODE = 'INR')
);

CREATE INDEX M06_IX_CLEARING_BATCH_STATUS
    ON M06_CLEARING_BATCH (BATCH_STATUS, OPENED_AT);

CREATE TABLE M06_CLEARING_BATCH_ITEM (
    CLEARING_BATCH_ITEM_ID  NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    CLEARING_BATCH_ID       NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    MOVEMENT_SIDE           VARCHAR2(3 CHAR) NOT NULL,
    ITEM_STATUS             VARCHAR2(20 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    EXTERNAL_ITEM_REF       VARCHAR2(120 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_CLEARING_BATCH_ITEM PRIMARY KEY (CLEARING_BATCH_ITEM_ID),
    CONSTRAINT MB_FK_BATCH_ITEM_BATCH FOREIGN KEY (CLEARING_BATCH_ID)
        REFERENCES M06_CLEARING_BATCH (CLEARING_BATCH_ID),
    CONSTRAINT MB_FK_BATCH_ITEM_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_UK_BATCH_ITEM_PAYMENT UNIQUE (PAYMENT_ID),
    CONSTRAINT MB_CK_BATCH_ITEM_SIDE CHECK (MOVEMENT_SIDE IN ('IN','OUT')),
    CONSTRAINT MB_CK_BATCH_ITEM_STATUS CHECK (ITEM_STATUS IN
        ('ACCEPTED','REJECTED','SETTLEMENT_PENDING','SETTLED','RETURNED','EXCEPTION')),
    CONSTRAINT MB_CK_BATCH_ITEM_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_BATCH_ITEM_CCY CHECK (CURRENCY_CODE = 'INR')
);

CREATE INDEX M06_IX_BATCH_ITEM_BATCH
    ON M06_CLEARING_BATCH_ITEM (CLEARING_BATCH_ID, ITEM_STATUS);

CREATE TABLE M06_PAYMENT_RECONCILIATION (
    RECONCILIATION_ID       NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    RECONCILIATION_STATUS   VARCHAR2(20 CHAR) NOT NULL,
    CUSTOMER_JOURNAL_ID     NUMBER(19),
    REFUND_JOURNAL_ID       NUMBER(19),
    SETTLEMENT_JOURNAL_ID   NUMBER(19),
    RAIL_EVIDENCE_ID        NUMBER(19),
    TREASURY_ENTRY_ID       NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    EXTERNAL_SETTLEMENT_REF VARCHAR2(120 CHAR),
    EXPECTED_AMOUNT         NUMBER(18,2) NOT NULL,
    RECONCILED_AMOUNT       NUMBER(18,2) NOT NULL,
    CHECK_VERSION           NUMBER(19) DEFAULT 0 NOT NULL,
    LAST_CHECKED_AT         TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    RECONCILED_AT           TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_PAYMENT_RECON PRIMARY KEY (RECONCILIATION_ID),
    CONSTRAINT MB_UK_PAYMENT_RECON UNIQUE (PAYMENT_ID),
    CONSTRAINT MB_FK_PAYMENT_RECON_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_FK_PAYMENT_RECON_EVIDENCE FOREIGN KEY (RAIL_EVIDENCE_ID)
        REFERENCES M06_RAIL_STATUS_EVIDENCE (EVIDENCE_ID),
    CONSTRAINT MB_CK_PAYMENT_RECON_STATUS CHECK (RECONCILIATION_STATUS IN
        ('PENDING','MATCHED','MISMATCH','EXCEPTION')),
    CONSTRAINT MB_CK_PAYMENT_RECON_AMOUNTS CHECK
        (EXPECTED_AMOUNT > 0 AND RECONCILED_AMOUNT >= 0 AND CHECK_VERSION >= 0),
    CONSTRAINT MB_CK_PAYMENT_RECON_COMPLETE CHECK
        ((RECONCILIATION_STATUS = 'MATCHED' AND RECONCILED_AT IS NOT NULL) OR
         (RECONCILIATION_STATUS <> 'MATCHED' AND RECONCILED_AT IS NULL))
);

CREATE TABLE M06_PAYMENT_RECONCILIATION_RUN (
    RECONCILIATION_RUN_ID   NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    CHECK_VERSION           NUMBER(19) NOT NULL,
    RESULT_STATUS           VARCHAR2(20 CHAR) NOT NULL,
    CUSTOMER_POSTING_MATCH  CHAR(1 CHAR) NOT NULL,
    SUSPENSE_MATCH          CHAR(1 CHAR) NOT NULL,
    RAIL_EVIDENCE_MATCH     CHAR(1 CHAR) NOT NULL,
    RESERVE_MATCH           CHAR(1 CHAR) NOT NULL,
    DETAIL_JSON             CLOB,
    CHECKED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_PAYMENT_RECON_RUN PRIMARY KEY (RECONCILIATION_RUN_ID),
    CONSTRAINT MB_FK_PAYMENT_RECON_RUN_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION(PAYMENT_ID),
    CONSTRAINT MB_UK_PAYMENT_RECON_RUN UNIQUE (PAYMENT_ID, CHECK_VERSION),
    CONSTRAINT MB_CK_PAY_RECON_RUN_STATUS CHECK (RESULT_STATUS IN ('MATCHED','MISMATCH','EXCEPTION')),
    CONSTRAINT MB_CK_PAY_RECON_RUN_FLAGS CHECK
        (CUSTOMER_POSTING_MATCH IN ('Y','N') AND SUSPENSE_MATCH IN ('Y','N')
         AND RAIL_EVIDENCE_MATCH IN ('Y','N') AND RESERVE_MATCH IN ('Y','N')),
    CONSTRAINT MB_CK_PAY_RECON_RUN_JSON CHECK (DETAIL_JSON IS JSON)
);
CREATE INDEX M06_IX_PAYMENT_RECON_RUN
  ON M06_PAYMENT_RECONCILIATION_RUN(PAYMENT_ID, CHECKED_AT);
-- Journal and treasury identifiers above are cross-service evidence references,
-- deliberately not foreign keys. Each reconciliation run is append-only; the
-- PAYMENT_RECONCILIATION row is the current summary.

CREATE TABLE M06_RECONCILIATION_EXCEPTION (
    EXCEPTION_ID            NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    MISMATCH_KEY            VARCHAR2(150 CHAR) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    CLEARING_BATCH_ID       NUMBER(19),
    EXCEPTION_TYPE          VARCHAR2(40 CHAR) NOT NULL,
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'OPEN' NOT NULL,
    SEVERITY                VARCHAR2(10 CHAR) NOT NULL,
    OWNER_ID                VARCHAR2(64 CHAR),
    EVIDENCE_JSON           CLOB,
    RESOLUTION_CODE         VARCHAR2(50 CHAR),
    RESOLUTION_TEXT         VARCHAR2(1000 CHAR),
    OPENED_AT               TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    RESOLVED_AT             TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_RECON_EXCEPTION PRIMARY KEY (EXCEPTION_ID),
    CONSTRAINT MB_UK_RECON_MISMATCH UNIQUE (MISMATCH_KEY),
    CONSTRAINT MB_FK_RECON_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_FK_RECON_BATCH FOREIGN KEY (CLEARING_BATCH_ID)
        REFERENCES M06_CLEARING_BATCH (CLEARING_BATCH_ID),
    CONSTRAINT MB_CK_RECON_SCOPE CHECK (PAYMENT_ID IS NOT NULL OR CLEARING_BATCH_ID IS NOT NULL),
    CONSTRAINT MB_CK_RECON_STATUS CHECK (STATUS IN ('OPEN','ASSIGNED','RESOLVED','WAIVED')),
    CONSTRAINT MB_CK_RECON_SEVERITY CHECK (SEVERITY IN ('LOW','MEDIUM','HIGH','CRITICAL')),
    CONSTRAINT MB_CK_RECON_EVIDENCE_JSON CHECK (EVIDENCE_JSON IS JSON)
);

CREATE TABLE M06_RECONCILIATION_EXCEPTION_HISTORY (
    EXCEPTION_HISTORY_ID    NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    EXCEPTION_ID            NUMBER(19) NOT NULL,
    FROM_STATUS             VARCHAR2(20 CHAR),
    TO_STATUS               VARCHAR2(20 CHAR) NOT NULL,
    ACTOR_ID                VARCHAR2(64 CHAR) NOT NULL,
    ACTION_CODE             VARCHAR2(30 CHAR) NOT NULL,
    REASON_TEXT             VARCHAR2(1000 CHAR),
    CHANGED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_RECON_EXCEPTION_HISTORY PRIMARY KEY (EXCEPTION_HISTORY_ID),
    CONSTRAINT MB_FK_RECON_EXCEPTION_HISTORY FOREIGN KEY (EXCEPTION_ID)
        REFERENCES M06_RECONCILIATION_EXCEPTION (EXCEPTION_ID)
);

CREATE INDEX M06_IX_RECON_EXCEPTION_HISTORY
    ON M06_RECONCILIATION_EXCEPTION_HISTORY (EXCEPTION_ID, CHANGED_AT);

CREATE INDEX M06_IX_RECON_QUEUE
    ON M06_RECONCILIATION_EXCEPTION (STATUS, SEVERITY, OPENED_AT);

CREATE TABLE M06_PAYMENT_APPROVAL (
    APPROVAL_ID             NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    APPROVAL_KEY            VARCHAR2(120 CHAR) NOT NULL,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    EXCEPTION_ID            NUMBER(19),
    ACTION_CODE             VARCHAR2(30 CHAR) NOT NULL,
    MAKER_ID                VARCHAR2(64 CHAR) NOT NULL,
    CHECKER_ID              VARCHAR2(64 CHAR),
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    REASON_TEXT             VARCHAR2(500 CHAR) NOT NULL,
    REQUESTED_AT            TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    DECIDED_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_PAYMENT_APPROVAL PRIMARY KEY (APPROVAL_ID),
    CONSTRAINT MB_FK_PAYMENT_APPROVAL_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID),
    CONSTRAINT MB_FK_PAYMENT_APPROVAL_EXCEPTION FOREIGN KEY (EXCEPTION_ID)
        REFERENCES M06_RECONCILIATION_EXCEPTION (EXCEPTION_ID),
    CONSTRAINT MB_UK_PAYMENT_APPROVAL_KEY UNIQUE (APPROVAL_KEY),
    CONSTRAINT MB_CK_PAYMENT_APPROVAL_ACTION CHECK (ACTION_CODE IN
        ('MANUAL_RETURN','EXCEPTION_CORRECTION','MANUAL_STATUS_RESOLUTION')),
    CONSTRAINT MB_CK_PAYMENT_APPROVAL_STATUS CHECK (STATUS IN
        ('PENDING','APPROVED','REJECTED','CANCELLED')),
    CONSTRAINT MB_CK_PAYMENT_APPROVAL_SOD CHECK
        (CHECKER_ID IS NULL OR CHECKER_ID <> MAKER_ID),
    CONSTRAINT MB_CK_PAYMENT_APPROVAL_DECISION CHECK
        ((STATUS = 'PENDING' AND CHECKER_ID IS NULL AND DECIDED_AT IS NULL) OR
         (STATUS IN ('APPROVED','REJECTED') AND CHECKER_ID IS NOT NULL AND DECIDED_AT IS NOT NULL) OR
         (STATUS = 'CANCELLED' AND DECIDED_AT IS NOT NULL))
);

CREATE TABLE M06_SECURITY_AUDIT_EVENT (
    AUDIT_EVENT_ID          NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ACTOR_ID                VARCHAR2(64 CHAR) NOT NULL,
    SESSION_ID              VARCHAR2(100 CHAR),
    CORRELATION_ID          VARCHAR2(100 CHAR),
    ACTION_CODE             VARCHAR2(80 CHAR) NOT NULL,
    RESOURCE_TYPE           VARCHAR2(40 CHAR) NOT NULL,
    RESOURCE_ID             VARCHAR2(100 CHAR),
    RESULT_CODE             VARCHAR2(30 CHAR) NOT NULL,
    REASON_CODE             VARCHAR2(50 CHAR),
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_PAY_SECURITY_AUDIT PRIMARY KEY (AUDIT_EVENT_ID)
);

CREATE INDEX M06_IX_PAY_AUDIT_RESOURCE
    ON M06_SECURITY_AUDIT_EVENT (RESOURCE_TYPE, RESOURCE_ID, OCCURRED_AT);

CREATE TABLE M06_IDEMPOTENCY_RECORD (
    IDEMPOTENCY_ID          NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ORIGINATOR_ID           VARCHAR2(64 CHAR) NOT NULL,
    CHANNEL_CODE            VARCHAR2(20 CHAR) NOT NULL,
    REQUEST_KEY             VARCHAR2(100 CHAR) NOT NULL,
    REQUEST_HASH            RAW(32) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    HTTP_STATUS             NUMBER(3),
    RESPONSE_REF            VARCHAR2(250 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    EXPIRES_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_PAY_IDEMPOTENCY PRIMARY KEY (IDEMPOTENCY_ID),
    CONSTRAINT MB_UK_PAY_IDEMPOTENCY UNIQUE (ORIGINATOR_ID, CHANNEL_CODE, REQUEST_KEY),
    CONSTRAINT MB_FK_PAY_IDEMPOTENCY_PAYMENT FOREIGN KEY (PAYMENT_ID)
        REFERENCES M06_PAYMENT_INSTRUCTION (PAYMENT_ID)
);

CREATE TABLE M06_OUTBOX_EVENT (
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    SCHEMA_VERSION          NUMBER(5) NOT NULL,
    AGGREGATE_TYPE          VARCHAR2(30 CHAR) NOT NULL,
    AGGREGATE_ID            VARCHAR2(100 CHAR) NOT NULL,
    CORRELATION_ID          VARCHAR2(100 CHAR),
    CAUSATION_ID            VARCHAR2(100 CHAR),
    PARTITION_KEY           VARCHAR2(100 CHAR) NOT NULL,
    PAYLOAD_JSON            CLOB NOT NULL,
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    AVAILABLE_AT            TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PUBLISH_STATUS          VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    PUBLISHED_AT            TIMESTAMP(6) WITH TIME ZONE,
    PUBLISH_ATTEMPTS        NUMBER(10) DEFAULT 0 NOT NULL,
    LOCKED_BY               VARCHAR2(100 CHAR),
    LOCKED_UNTIL            TIMESTAMP(6) WITH TIME ZONE,
    LAST_ERROR              VARCHAR2(1000 CHAR),
    CONSTRAINT MB_PK_PAY_OUTBOX PRIMARY KEY (EVENT_ID),
    CONSTRAINT MB_CK_PAY_OUTBOX_JSON CHECK (PAYLOAD_JSON IS JSON),
    CONSTRAINT MB_CK_PAY_OUTBOX_STATUS CHECK (PUBLISH_STATUS IN
        ('PENDING','CLAIMED','PUBLISHED','DEAD_LETTER')),
    CONSTRAINT MB_CK_PAY_OUTBOX_PUBLISHED CHECK
        ((PUBLISH_STATUS = 'PUBLISHED' AND PUBLISHED_AT IS NOT NULL) OR
         (PUBLISH_STATUS <> 'PUBLISHED' AND PUBLISHED_AT IS NULL))
);

CREATE INDEX M06_IX_PAY_OUTBOX_PENDING
    ON M06_OUTBOX_EVENT (PUBLISH_STATUS, AVAILABLE_AT, LOCKED_UNTIL);

CREATE TABLE M06_CONSUMER_INBOX (
    CONSUMER_NAME           VARCHAR2(100 CHAR) NOT NULL,
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    RECEIVED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PROCESSED_AT            TIMESTAMP(6) WITH TIME ZONE,
    RESULT_CODE             VARCHAR2(30 CHAR),
    CONSTRAINT MB_PK_PAY_CONSUMER_INBOX PRIMARY KEY (CONSUMER_NAME, EVENT_ID)
);

--------------------------------------------------------------------------------

CREATE TABLE M06_PAYMENT_STATE_TRANSITION (
    FROM_STATUS VARCHAR2(30 CHAR) NOT NULL,
    TO_STATUS VARCHAR2(30 CHAR) NOT NULL,
    REQUIRES_RAIL_EVIDENCE CHAR(1 CHAR) DEFAULT 'N' NOT NULL,
    REQUIRES_LEDGER_EVIDENCE CHAR(1 CHAR) DEFAULT 'N' NOT NULL,
    CONSTRAINT MB_PK_PAYMENT_STATE_TRANSITION PRIMARY KEY (FROM_STATUS, TO_STATUS),
    CONSTRAINT MB_CK_PAY_TRANSITION_FLAGS CHECK
      (REQUIRES_RAIL_EVIDENCE IN ('Y','N') AND REQUIRES_LEDGER_EVIDENCE IN ('Y','N'))
);

INSERT ALL
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('RECEIVED','AUTHORIZED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('RECEIVED','REJECTED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('RECEIVED','CANCELLED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('AUTHORIZED','HELD','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('AUTHORIZED','LIQUIDITY_PENDING','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('AUTHORIZED','REJECTED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('AUTHORIZED','CANCELLED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('LIQUIDITY_PENDING','HELD','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('LIQUIDITY_PENDING','REJECTED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('LIQUIDITY_PENDING','CANCELLED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('HELD','DEBIT_POSTED','N','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('HELD','REJECTED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('HELD','CANCELLED','N','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('DEBIT_POSTED','DISPATCHED','N','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('DEBIT_POSTED','REJECTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('DISPATCHED','ACCEPTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('DISPATCHED','UNKNOWN','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('DISPATCHED','REJECTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('ACCEPTED','SETTLEMENT_PENDING','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('ACCEPTED','SETTLED','Y','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('ACCEPTED','UNKNOWN','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('ACCEPTED','REJECTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('UNKNOWN','ACCEPTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('UNKNOWN','SETTLEMENT_PENDING','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('UNKNOWN','SETTLED','Y','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('UNKNOWN','REJECTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('UNKNOWN','REFUNDED','Y','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('SETTLEMENT_PENDING','SETTLED','Y','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('SETTLEMENT_PENDING','UNKNOWN','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('SETTLEMENT_PENDING','REJECTED','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('REJECTED','REFUNDED','Y','Y')
SELECT 1 FROM DUAL;

ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_CK_PAY_HISTORY_TO_STATUS
  CHECK (TO_STATUS IN ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN',
    'SETTLEMENT_PENDING','SETTLED','REJECTED','REFUNDED','CANCELLED'));
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_CK_PAY_HISTORY_FROM_STATUS
  CHECK (FROM_STATUS IS NULL OR FROM_STATUS IN ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN',
    'SETTLEMENT_PENDING','SETTLED','REJECTED','REFUNDED','CANCELLED'));
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_FK_PAY_HISTORY_TRANSITION
  FOREIGN KEY (FROM_STATUS, TO_STATUS)
  REFERENCES M06_PAYMENT_STATE_TRANSITION(FROM_STATUS, TO_STATUS);
ALTER TABLE M06_PAYMENT_INSTRUCTION ADD CONSTRAINT MB_FK_PAYMENT_CLEARING_BATCH
  FOREIGN KEY (CLEARING_BATCH_ID) REFERENCES M06_CLEARING_BATCH(CLEARING_BATCH_ID);
COMMIT;

--------------------------------------------------------------------------------
-- MODULE 7 TREASURY BOUNDARY - MB_TREASURY
--------------------------------------------------------------------------------

CREATE TABLE M07_RESERVE_ACCOUNT (
    RESERVE_ACCOUNT_ID      NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    RESERVE_ACCOUNT_CODE    VARCHAR2(40 CHAR) NOT NULL,
    ACCOUNT_TYPE            VARCHAR2(30 CHAR) NOT NULL,
    EXTERNAL_ACCOUNT_REF    VARCHAR2(120 CHAR) NOT NULL,
    GL_ACCOUNT_ID           NUMBER(19) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    ACCOUNT_STATUS          VARCHAR2(20 CHAR) DEFAULT 'ACTIVE' NOT NULL,
    EFFECTIVE_FROM          TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    EFFECTIVE_TO            TIMESTAMP(6) WITH TIME ZONE,
    SAFETY_BUFFER_AMOUNT    NUMBER(18,2) DEFAULT 0 NOT NULL,
    WARNING_THRESHOLD_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_RESERVE_ACCOUNT PRIMARY KEY (RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_UK_RESERVE_ACCOUNT_CODE UNIQUE (RESERVE_ACCOUNT_CODE),
    CONSTRAINT MB_UK_RESERVE_EXTERNAL_REF UNIQUE (EXTERNAL_ACCOUNT_REF),
    CONSTRAINT MB_CK_RESERVE_ACCOUNT_TYPE CHECK (ACCOUNT_TYPE IN ('RBI_CURRENT','RTGS_SETTLEMENT')),
    CONSTRAINT MB_CK_RESERVE_ACCOUNT_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_RESERVE_ACCOUNT_STATUS CHECK (ACCOUNT_STATUS IN ('ACTIVE','SUSPENDED','CLOSED')),
    CONSTRAINT MB_CK_RESERVE_ACCOUNT_DATES CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM),
    CONSTRAINT MB_CK_RESERVE_ACCOUNT_THRESHOLDS CHECK
      (SAFETY_BUFFER_AMOUNT >= 0 AND WARNING_THRESHOLD_AMOUNT >= 0)
);

CREATE TABLE M07_SETTLEMENT_CYCLE (
    SETTLEMENT_CYCLE_ID     NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    CYCLE_REFERENCE         VARCHAR2(100 CHAR) NOT NULL,
    CLEARING_BATCH_ID       NUMBER(19),
    CYCLE_DIRECTION         VARCHAR2(10 CHAR) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    GROSS_OUT_AMOUNT        NUMBER(18,2) DEFAULT 0 NOT NULL,
    GROSS_IN_AMOUNT         NUMBER(18,2) DEFAULT 0 NOT NULL,
    NET_AMOUNT              NUMBER(18,2) DEFAULT 0 NOT NULL,
    NET_MOVEMENT_SIDE       VARCHAR2(3 CHAR),
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'OPEN' NOT NULL,
    OPENED_AT               TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CLOSED_AT               TIMESTAMP(6) WITH TIME ZONE,
    SETTLED_AT              TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_SETTLEMENT_CYCLE PRIMARY KEY (SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_UK_SETTLEMENT_CYCLE_REF UNIQUE (RAIL_CODE, CYCLE_REFERENCE),
    CONSTRAINT MB_FK_SETTLEMENT_CYCLE_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_RAIL CHECK (RAIL_CODE IN ('UPI','IMPS','NEFT','RTGS')),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_DIRECTION CHECK (CYCLE_DIRECTION IN ('OUTBOUND','INBOUND','NET')),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_AMOUNTS CHECK
      (GROSS_OUT_AMOUNT >= 0 AND GROSS_IN_AMOUNT >= 0 AND NET_AMOUNT >= 0),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_SIDE CHECK
      ((NET_AMOUNT = 0 AND NET_MOVEMENT_SIDE IS NULL) OR
       (NET_AMOUNT > 0 AND NET_MOVEMENT_SIDE IN ('IN','OUT'))),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_STATUS CHECK
      (STATUS IN ('OPEN','CLOSED','SUBMITTED','SETTLEMENT_PENDING','SETTLED','EXCEPTION')),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_TIMES CHECK
      ((STATUS = 'OPEN' AND CLOSED_AT IS NULL AND SETTLED_AT IS NULL) OR
       (STATUS IN ('CLOSED','SUBMITTED','SETTLEMENT_PENDING','EXCEPTION') AND CLOSED_AT IS NOT NULL AND SETTLED_AT IS NULL) OR
       (STATUS = 'SETTLED' AND CLOSED_AT IS NOT NULL AND SETTLED_AT IS NOT NULL))
);
CREATE INDEX M07_IX_SETTLEMENT_CYCLE_STATUS
  ON M07_SETTLEMENT_CYCLE(STATUS, OPENED_AT);
CREATE INDEX M07_IX_SETTLEMENT_CYCLE_ACCOUNT
  ON M07_SETTLEMENT_CYCLE(RESERVE_ACCOUNT_ID, RAIL_CODE, STATUS, OPENED_AT);

CREATE TABLE M07_SETTLEMENT_CYCLE_ITEM (
    SETTLEMENT_CYCLE_ITEM_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    SETTLEMENT_CYCLE_ID     NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19) NOT NULL,
    DIRECTION               VARCHAR2(3 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    ITEM_STATUS             VARCHAR2(25 CHAR) DEFAULT 'INCLUDED' NOT NULL,
    INCLUDED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    RECONCILED_AT           TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_SETTLEMENT_CYCLE_ITEM PRIMARY KEY (SETTLEMENT_CYCLE_ITEM_ID),
    CONSTRAINT MB_UK_SETTLEMENT_CYCLE_ITEM UNIQUE (SETTLEMENT_CYCLE_ID, PAYMENT_ID),
    CONSTRAINT MB_FK_SETTLEMENT_CYCLE_ITEM_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_ITEM_DIRECTION CHECK (DIRECTION IN ('IN','OUT')),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_ITEM_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_ITEM_STATUS CHECK
      (ITEM_STATUS IN ('INCLUDED','SETTLED','RECONCILED','EXCLUDED','EXCEPTION')),
    CONSTRAINT MB_CK_SETTLEMENT_CYCLE_ITEM_RECONCILED CHECK
      ((ITEM_STATUS = 'RECONCILED' AND RECONCILED_AT IS NOT NULL) OR
       (ITEM_STATUS <> 'RECONCILED' AND RECONCILED_AT IS NULL))
);
CREATE INDEX M07_IX_SETTLEMENT_CYCLE_ITEM_STATUS
  ON M07_SETTLEMENT_CYCLE_ITEM(SETTLEMENT_CYCLE_ID, ITEM_STATUS, INCLUDED_AT);

CREATE TABLE M07_SETTLEMENT_EVIDENCE (
    EVIDENCE_ID             NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    EVIDENCE_TYPE           VARCHAR2(30 CHAR) NOT NULL,
    EVIDENCE_STATUS         VARCHAR2(20 CHAR) NOT NULL,
    MOVEMENT_SIDE           VARCHAR2(3 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    EXTERNAL_SETTLEMENT_REF VARCHAR2(120 CHAR) NOT NULL,
    EXTERNAL_STATEMENT_REF  VARCHAR2(120 CHAR),
    EVIDENCE_HASH           RAW(32) NOT NULL,
    EVIDENCE_REF            VARCHAR2(250 CHAR),
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    RECEIVED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_SETTLEMENT_EVIDENCE PRIMARY KEY (EVIDENCE_ID),
    CONSTRAINT MB_FK_SETTLEMENT_EVIDENCE_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_SETTLEMENT_EVIDENCE_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_UK_SETTLEMENT_EVIDENCE_HASH UNIQUE (RAIL_CODE, EVIDENCE_HASH),
    CONSTRAINT MB_UK_SETTLEMENT_EVIDENCE_REF UNIQUE (RESERVE_ACCOUNT_ID, EXTERNAL_SETTLEMENT_REF),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_SCOPE CHECK
      ((PAYMENT_ID IS NOT NULL AND SETTLEMENT_CYCLE_ID IS NULL) OR
       (PAYMENT_ID IS NULL AND SETTLEMENT_CYCLE_ID IS NOT NULL)),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_RAIL CHECK (RAIL_CODE IN ('UPI','IMPS','NEFT','RTGS')),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_TYPE CHECK
      (EVIDENCE_TYPE IN ('RAIL_CONFIRMATION','CLEARING_CONFIRMATION','RESERVE_STATEMENT','MANUAL_VERIFICATION')),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_STATUS CHECK
      (EVIDENCE_STATUS IN ('RECEIVED','VERIFIED','REJECTED','CONFLICT')),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_SIDE CHECK (MOVEMENT_SIDE IN ('IN','OUT')),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_SETTLEMENT_EVIDENCE_CCY CHECK (CURRENCY_CODE = 'INR')
);
CREATE INDEX M07_IX_SETTLEMENT_EVIDENCE_SCOPE
  ON M07_SETTLEMENT_EVIDENCE(PAYMENT_ID, SETTLEMENT_CYCLE_ID, RECEIVED_AT);

CREATE TABLE M07_CENTRAL_TREASURY_LEDGER (
    TREASURY_ENTRY_ID       NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    EVIDENCE_ID             NUMBER(19) NOT NULL,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    MOVEMENT_SIDE           VARCHAR2(3 CHAR) NOT NULL,
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    EXTERNAL_SETTLEMENT_REF VARCHAR2(120 CHAR) NOT NULL,
    EXTERNAL_STATEMENT_REF  VARCHAR2(120 CHAR),
    GL_JOURNAL_ID           NUMBER(19) NOT NULL,
    SETTLED_AT              TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    RECORDED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_CENTRAL_TREASURY_LEDGER PRIMARY KEY (TREASURY_ENTRY_ID),
    CONSTRAINT MB_FK_TREASURY_LEDGER_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_TREASURY_LEDGER_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_FK_TREASURY_LEDGER_EVIDENCE FOREIGN KEY (EVIDENCE_ID)
      REFERENCES M07_SETTLEMENT_EVIDENCE(EVIDENCE_ID),
    CONSTRAINT MB_UK_TREASURY_SETTLEMENT_REF UNIQUE (RESERVE_ACCOUNT_ID, EXTERNAL_SETTLEMENT_REF),
    CONSTRAINT MB_UK_TREASURY_GL_JOURNAL UNIQUE (GL_JOURNAL_ID),
    CONSTRAINT MB_UK_TREASURY_EVIDENCE UNIQUE (EVIDENCE_ID),
    CONSTRAINT MB_CK_TREASURY_LEDGER_SCOPE CHECK
      ((PAYMENT_ID IS NOT NULL AND SETTLEMENT_CYCLE_ID IS NULL) OR
       (PAYMENT_ID IS NULL AND SETTLEMENT_CYCLE_ID IS NOT NULL)),
    CONSTRAINT MB_CK_TREASURY_LEDGER_RAIL CHECK (RAIL_CODE IN ('UPI','IMPS','NEFT','RTGS')),
    CONSTRAINT MB_CK_TREASURY_LEDGER_SIDE CHECK (MOVEMENT_SIDE IN ('IN','OUT')),
    CONSTRAINT MB_CK_TREASURY_LEDGER_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_TREASURY_LEDGER_CCY CHECK (CURRENCY_CODE = 'INR')
);
CREATE INDEX M07_IX_TREASURY_LEDGER_PAYMENT
  ON M07_CENTRAL_TREASURY_LEDGER(PAYMENT_ID);
CREATE INDEX M07_IX_TREASURY_LEDGER_CYCLE
  ON M07_CENTRAL_TREASURY_LEDGER(SETTLEMENT_CYCLE_ID);
CREATE INDEX M07_IX_TREASURY_LEDGER_TIME
  ON M07_CENTRAL_TREASURY_LEDGER(SETTLED_AT);

CREATE TABLE M07_RESERVE_POSITION (
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    CONFIRMED_BALANCE       NUMBER(18,2) DEFAULT 0 NOT NULL,
    ACTIVE_HOLD_AMOUNT      NUMBER(18,2) DEFAULT 0 NOT NULL,
    AVAILABLE_BALANCE       NUMBER(18,2) GENERATED ALWAYS AS
      (CONFIRMED_BALANCE - ACTIVE_HOLD_AMOUNT) VIRTUAL,
    LAST_TREASURY_ENTRY_ID  NUMBER(19),
    VERSION_NO              NUMBER(19) DEFAULT 0 NOT NULL,
    AS_OF                   TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_RESERVE_POSITION PRIMARY KEY (RESERVE_ACCOUNT_ID, CURRENCY_CODE),
    CONSTRAINT MB_FK_RESERVE_POSITION_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_RESERVE_POSITION_ENTRY FOREIGN KEY (LAST_TREASURY_ENTRY_ID)
      REFERENCES M07_CENTRAL_TREASURY_LEDGER(TREASURY_ENTRY_ID),
    CONSTRAINT MB_CK_RESERVE_POSITION_HOLD CHECK (ACTIVE_HOLD_AMOUNT >= 0),
    CONSTRAINT MB_CK_RESERVE_POSITION_VERSION CHECK (VERSION_NO >= 0),
    CONSTRAINT MB_CK_RESERVE_POSITION_CCY CHECK (CURRENCY_CODE = 'INR')
);

CREATE TABLE M07_TREASURY_LIQUIDITY_HOLD (
    LIQUIDITY_HOLD_ID       NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    HOLD_KEY                VARCHAR2(120 CHAR) NOT NULL,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    RAIL_CODE               VARCHAR2(10 CHAR) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    AMOUNT                  NUMBER(18,2) NOT NULL,
    CURRENCY_CODE           CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'REQUESTED' NOT NULL,
    REQUEST_HASH            RAW(32) NOT NULL,
    RESPONSE_REFERENCE      VARCHAR2(120 CHAR) NOT NULL,
    EXPIRES_AT              TIMESTAMP(6) WITH TIME ZONE,
    COMMITTED_AT            TIMESTAMP(6) WITH TIME ZONE,
    CONSUMED_BY_ENTRY_ID    NUMBER(19),
    RELEASE_REASON          VARCHAR2(50 CHAR),
    CREATED_AT              TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CLOSED_AT               TIMESTAMP(6) WITH TIME ZONE,
    VERSION_NO              NUMBER(10) DEFAULT 0 NOT NULL,
    CONSTRAINT MB_PK_TREASURY_LIQUIDITY_HOLD PRIMARY KEY (LIQUIDITY_HOLD_ID),
    CONSTRAINT MB_UK_TREASURY_LIQUIDITY_HOLD_KEY UNIQUE (HOLD_KEY),
    CONSTRAINT MB_UK_TREASURY_LIQUIDITY_HOLD_RESPONSE UNIQUE (RESPONSE_REFERENCE),
    CONSTRAINT MB_UK_TREASURY_LIQUIDITY_HOLD_OBLIGATION UNIQUE (RAIL_CODE, HOLD_KEY),
    CONSTRAINT MB_FK_LIQUIDITY_HOLD_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_LIQUIDITY_HOLD_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_FK_LIQUIDITY_HOLD_ENTRY FOREIGN KEY (CONSUMED_BY_ENTRY_ID)
      REFERENCES M07_CENTRAL_TREASURY_LEDGER(TREASURY_ENTRY_ID),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_SCOPE CHECK
      ((PAYMENT_ID IS NOT NULL AND SETTLEMENT_CYCLE_ID IS NULL) OR
       (PAYMENT_ID IS NULL AND SETTLEMENT_CYCLE_ID IS NOT NULL)),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_AMOUNT CHECK (AMOUNT > 0),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_CCY CHECK (CURRENCY_CODE = 'INR'),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_RAIL CHECK (RAIL_CODE IN ('UPI','IMPS','NEFT','RTGS')),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_STATUS CHECK
      (STATUS IN ('REQUESTED','RESERVED','COMMITTED','CONSUMED','RELEASED','EXPIRED','EXCEPTION')),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_TERMINAL CHECK
      ((STATUS IN ('REQUESTED','RESERVED','COMMITTED') AND CLOSED_AT IS NULL AND CONSUMED_BY_ENTRY_ID IS NULL) OR
       (STATUS = 'CONSUMED' AND CLOSED_AT IS NOT NULL AND CONSUMED_BY_ENTRY_ID IS NOT NULL) OR
       (STATUS IN ('RELEASED','EXPIRED','EXCEPTION') AND CLOSED_AT IS NOT NULL AND CONSUMED_BY_ENTRY_ID IS NULL)),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_REASON CHECK
      ((STATUS IN ('RELEASED','EXPIRED','EXCEPTION') AND RELEASE_REASON IS NOT NULL) OR
       (STATUS IN ('REQUESTED','RESERVED','COMMITTED','CONSUMED') AND RELEASE_REASON IS NULL)),
    CONSTRAINT MB_CK_LIQUIDITY_HOLD_COMMITTED CHECK
      ((STATUS IN ('COMMITTED','CONSUMED') AND COMMITTED_AT IS NOT NULL) OR
       (STATUS NOT IN ('COMMITTED','CONSUMED') AND COMMITTED_AT IS NULL))
);
CREATE UNIQUE INDEX M07_UX_LIQUIDITY_HOLD_PAYMENT
  ON M07_TREASURY_LIQUIDITY_HOLD
    (CASE WHEN PAYMENT_ID IS NOT NULL THEN PAYMENT_ID END);
CREATE UNIQUE INDEX M07_UX_LIQUIDITY_HOLD_CYCLE
  ON M07_TREASURY_LIQUIDITY_HOLD
    (CASE WHEN SETTLEMENT_CYCLE_ID IS NOT NULL THEN SETTLEMENT_CYCLE_ID END);
CREATE INDEX M07_IX_LIQUIDITY_HOLD_ACTIVE
  ON M07_TREASURY_LIQUIDITY_HOLD(RESERVE_ACCOUNT_ID, STATUS, EXPIRES_AT);

CREATE TABLE M07_RECONCILIATION_EXCEPTION (
    EXCEPTION_ID            NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    MISMATCH_KEY            VARCHAR2(150 CHAR) NOT NULL,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    TREASURY_ENTRY_ID       NUMBER(19),
    EXCEPTION_TYPE          VARCHAR2(40 CHAR) NOT NULL,
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'OPEN' NOT NULL,
    SEVERITY                VARCHAR2(10 CHAR) NOT NULL,
    OWNER_ID                VARCHAR2(64 CHAR),
    EVIDENCE_JSON           CLOB,
    RESOLUTION_CODE         VARCHAR2(50 CHAR),
    RESOLUTION_TEXT         VARCHAR2(1000 CHAR),
    OPENED_AT               TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    RESOLVED_AT             TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT MB_PK_TREASURY_RECON_EXCEPTION PRIMARY KEY (EXCEPTION_ID),
    CONSTRAINT MB_UK_TREASURY_RECON_MISMATCH UNIQUE (MISMATCH_KEY),
    CONSTRAINT MB_FK_TREASURY_RECON_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_TREASURY_RECON_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_FK_TREASURY_RECON_ENTRY FOREIGN KEY (TREASURY_ENTRY_ID)
      REFERENCES M07_CENTRAL_TREASURY_LEDGER(TREASURY_ENTRY_ID),
    CONSTRAINT MB_CK_TREASURY_RECON_SCOPE CHECK
      (PAYMENT_ID IS NOT NULL OR SETTLEMENT_CYCLE_ID IS NOT NULL OR TREASURY_ENTRY_ID IS NOT NULL),
    CONSTRAINT MB_CK_TREASURY_RECON_STATUS CHECK (STATUS IN ('OPEN','ASSIGNED','RESOLVED','WAIVED')),
    CONSTRAINT MB_CK_TREASURY_RECON_SEVERITY CHECK (SEVERITY IN ('LOW','MEDIUM','HIGH','CRITICAL')),
    CONSTRAINT MB_CK_TREASURY_RECON_JSON CHECK (EVIDENCE_JSON IS JSON),
    CONSTRAINT MB_CK_TREASURY_RECON_RESOLUTION CHECK
      ((STATUS IN ('RESOLVED','WAIVED') AND RESOLVED_AT IS NOT NULL AND RESOLUTION_CODE IS NOT NULL) OR
       (STATUS IN ('OPEN','ASSIGNED') AND RESOLVED_AT IS NULL))
);
CREATE INDEX M07_IX_TREASURY_RECON_QUEUE
  ON M07_RECONCILIATION_EXCEPTION(STATUS, SEVERITY, OPENED_AT);

CREATE TABLE M07_TREASURY_WORK_ITEM (
    WORK_ITEM_ID            NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    WORK_TYPE               VARCHAR2(30 CHAR) NOT NULL,
    SUBJECT_TYPE            VARCHAR2(30 CHAR) NOT NULL,
    RESERVE_ACCOUNT_ID      NUMBER(19) NOT NULL,
    PAYMENT_ID              NUMBER(19),
    SETTLEMENT_CYCLE_ID     NUMBER(19),
    SOURCE_REFERENCE        VARCHAR2(120 CHAR),
    EXPECTED_AMOUNT         NUMBER(18,2),
    OBSERVED_AMOUNT         NUMBER(18,2),
    DETAIL_TEXT             VARCHAR2(2000 CHAR) NOT NULL,
    EVIDENCE_REFERENCE      VARCHAR2(300 CHAR),
    OWNER_ID                VARCHAR2(64 CHAR) NOT NULL,
    STATUS                  VARCHAR2(20 CHAR) DEFAULT 'OPEN' NOT NULL,
    MAKER_USER_ID           VARCHAR2(36 CHAR),
    MADE_AT                 TIMESTAMP(6) WITH TIME ZONE,
    CHECKER_USER_ID         VARCHAR2(36 CHAR),
    CHECKED_AT              TIMESTAMP(6) WITH TIME ZONE,
    GL_JOURNAL_ID           NUMBER(19),
    OPENED_AT               TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    RESOLVED_AT             TIMESTAMP(6) WITH TIME ZONE,
    VERSION_NO              NUMBER(10) DEFAULT 0 NOT NULL,
    CONSTRAINT MB_PK_TREASURY_WORK_ITEM PRIMARY KEY (WORK_ITEM_ID),
    CONSTRAINT MB_FK_TREASURY_WORK_ACCOUNT FOREIGN KEY (RESERVE_ACCOUNT_ID)
      REFERENCES M07_RESERVE_ACCOUNT(RESERVE_ACCOUNT_ID),
    CONSTRAINT MB_FK_TREASURY_WORK_CYCLE FOREIGN KEY (SETTLEMENT_CYCLE_ID)
      REFERENCES M07_SETTLEMENT_CYCLE(SETTLEMENT_CYCLE_ID),
    CONSTRAINT MB_CK_TREASURY_WORK_TYPE CHECK (WORK_TYPE IN ('RECONCILIATION','FUNDING')),
    CONSTRAINT MB_CK_TREASURY_WORK_SUBJECT CHECK
      (SUBJECT_TYPE IN ('PAYMENT','CYCLE','RESERVE_ACCOUNT')),
    CONSTRAINT MB_CK_TREASURY_WORK_SCOPE CHECK
      ((SUBJECT_TYPE = 'PAYMENT' AND PAYMENT_ID IS NOT NULL AND SETTLEMENT_CYCLE_ID IS NULL) OR
       (SUBJECT_TYPE = 'CYCLE' AND PAYMENT_ID IS NULL AND SETTLEMENT_CYCLE_ID IS NOT NULL) OR
       (SUBJECT_TYPE = 'RESERVE_ACCOUNT' AND PAYMENT_ID IS NULL AND SETTLEMENT_CYCLE_ID IS NULL)),
    CONSTRAINT MB_CK_TREASURY_WORK_STATUS CHECK
      (STATUS IN ('OPEN','ASSIGNED','PENDING_APPROVAL','RESOLVED','WAIVED','REJECTED')),
    CONSTRAINT MB_CK_TREASURY_WORK_SEPARATION CHECK
      (CHECKER_USER_ID IS NULL OR CHECKER_USER_ID <> MAKER_USER_ID),
    CONSTRAINT MB_CK_TREASURY_WORK_DECISION CHECK
      ((STATUS IN ('RESOLVED','WAIVED','REJECTED') AND RESOLVED_AT IS NOT NULL
        AND CHECKER_USER_ID IS NOT NULL AND CHECKED_AT IS NOT NULL) OR
       (STATUS IN ('OPEN','ASSIGNED','PENDING_APPROVAL') AND RESOLVED_AT IS NULL
        AND CHECKER_USER_ID IS NULL AND CHECKED_AT IS NULL)),
    CONSTRAINT MB_CK_TREASURY_WORK_VERSION CHECK (VERSION_NO >= 0)
);
CREATE INDEX M07_IX_TREASURY_WORK_QUEUE
  ON M07_TREASURY_WORK_ITEM(STATUS, OWNER_ID, OPENED_AT);

CREATE TABLE M07_SECURITY_AUDIT_EVENT (
    AUDIT_EVENT_ID          NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ACTOR_ID                VARCHAR2(64 CHAR) NOT NULL,
    SESSION_ID              VARCHAR2(100 CHAR),
    CORRELATION_ID          VARCHAR2(100 CHAR),
    ACTION_CODE             VARCHAR2(80 CHAR) NOT NULL,
    RESOURCE_TYPE           VARCHAR2(40 CHAR) NOT NULL,
    RESOURCE_ID             VARCHAR2(100 CHAR),
    RESULT_CODE             VARCHAR2(30 CHAR) NOT NULL,
    REASON_CODE             VARCHAR2(50 CHAR),
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT MB_PK_TREASURY_SECURITY_AUDIT PRIMARY KEY (AUDIT_EVENT_ID)
);
CREATE INDEX M07_IX_TREASURY_AUDIT_RESOURCE
  ON M07_SECURITY_AUDIT_EVENT(RESOURCE_TYPE, RESOURCE_ID, OCCURRED_AT);

CREATE TABLE M07_OUTBOX_EVENT (
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    SCHEMA_VERSION          NUMBER(5) NOT NULL,
    AGGREGATE_TYPE          VARCHAR2(30 CHAR) NOT NULL,
    AGGREGATE_ID            VARCHAR2(100 CHAR) NOT NULL,
    CORRELATION_ID          VARCHAR2(100 CHAR),
    CAUSATION_ID            VARCHAR2(100 CHAR),
    PARTITION_KEY           VARCHAR2(100 CHAR) NOT NULL,
    PAYLOAD_JSON            CLOB NOT NULL,
    OCCURRED_AT             TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    AVAILABLE_AT            TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PUBLISH_STATUS          VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    PUBLISHED_AT            TIMESTAMP(6) WITH TIME ZONE,
    PUBLISH_ATTEMPTS        NUMBER(10) DEFAULT 0 NOT NULL,
    LOCKED_BY               VARCHAR2(100 CHAR),
    LOCKED_UNTIL            TIMESTAMP(6) WITH TIME ZONE,
    LAST_ERROR              VARCHAR2(1000 CHAR),
    CONSTRAINT MB_PK_TREASURY_OUTBOX PRIMARY KEY (EVENT_ID),
    CONSTRAINT MB_CK_TREASURY_OUTBOX_JSON CHECK (PAYLOAD_JSON IS JSON),
    CONSTRAINT MB_CK_TREASURY_OUTBOX_STATUS CHECK
      (PUBLISH_STATUS IN ('PENDING','CLAIMED','PUBLISHED','DEAD_LETTER')),
    CONSTRAINT MB_CK_TREASURY_OUTBOX_PUBLISHED CHECK
      ((PUBLISH_STATUS = 'PUBLISHED' AND PUBLISHED_AT IS NOT NULL) OR
       (PUBLISH_STATUS <> 'PUBLISHED' AND PUBLISHED_AT IS NULL))
);
CREATE INDEX M07_IX_TREASURY_OUTBOX_PENDING
  ON M07_OUTBOX_EVENT(PUBLISH_STATUS, AVAILABLE_AT, LOCKED_UNTIL);

CREATE TABLE M07_CONSUMER_INBOX (
    CONSUMER_NAME           VARCHAR2(100 CHAR) NOT NULL,
    EVENT_ID                RAW(16) NOT NULL,
    EVENT_TYPE              VARCHAR2(100 CHAR) NOT NULL,
    RECEIVED_AT             TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    PROCESSED_AT            TIMESTAMP(6) WITH TIME ZONE,
    RESULT_CODE             VARCHAR2(30 CHAR),
    CONSTRAINT MB_PK_TREASURY_CONSUMER_INBOX PRIMARY KEY (CONSUMER_NAME, EVENT_ID)
);
CREATE INDEX M07_IX_TREASURY_INBOX_PENDING
  ON M07_CONSUMER_INBOX(PROCESSED_AT, RECEIVED_AT);

--------------------------------------------------------------------------------
-- MODULE 8 - MB_LOAN
--------------------------------------------------------------------------------

CREATE SEQUENCE M08_LOAN_APPLICATION_NO_SEQ START WITH 1 INCREMENT BY 1 NOCYCLE CACHE 100;
CREATE SEQUENCE M08_LOAN_OFFER_NO_SEQ START WITH 1 INCREMENT BY 1 NOCYCLE CACHE 100;
CREATE SEQUENCE M08_LOAN_FACILITY_NO_SEQ START WITH 1 INCREMENT BY 1 NOCYCLE CACHE 100;

CREATE TABLE M08_LOAN_APPLICATION (
  APPLICATION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_NUMBER VARCHAR2(30 CHAR) NOT NULL UNIQUE,
  PRIMARY_CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  PRODUCT_ID NUMBER(19) NOT NULL,
  PRODUCT_VERSION_ID NUMBER(19) NOT NULL,
  PRODUCT_RULE_SET_HASH CHAR(64) NOT NULL,
  BRANCH_CODE VARCHAR2(80 CHAR) NOT NULL,
  CHANNEL_CODE VARCHAR2(20 CHAR) NOT NULL,
  CURRENCY_CODE CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
  REQUESTED_AMOUNT NUMBER(18,2) NOT NULL,
  REQUESTED_TENURE_MONTHS NUMBER(4) NOT NULL,
  LOAN_PURPOSE_CODE VARCHAR2(40 CHAR) NOT NULL,
  STATUS VARCHAR2(24 CHAR) DEFAULT 'DRAFT' NOT NULL,
  CURRENT_REVISION_ID NUMBER(19),
  ASSIGNED_TO_USER_ID VARCHAR2(36 CHAR),
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  SUBMITTED_AT TIMESTAMP(6) WITH TIME ZONE,
  TERMINATED_AT TIMESTAMP(6) WITH TIME ZONE,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR) NOT NULL,
  CONSTRAINT MB_LN_APP_UQ_CONTRACT_SCOPE UNIQUE
    (APPLICATION_ID, PRIMARY_CIF_ID, PRODUCT_ID, PRODUCT_VERSION_ID),
  CONSTRAINT MB_LN_APP_CK_AMOUNT CHECK (REQUESTED_AMOUNT > 0),
  CONSTRAINT MB_LN_APP_CK_TENURE CHECK (REQUESTED_TENURE_MONTHS > 0),
  CONSTRAINT MB_LN_APP_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_LN_APP_CK_STATUS CHECK (STATUS IN
    ('DRAFT','SUBMITTED','UNDER_REVIEW','REFERRED','APPROVED','REJECTED',
     'WITHDRAWN','EXPIRED','OFFERED','ACCEPTED','CONVERTED','CANCELLED')),
  CONSTRAINT MB_LN_APP_CK_SUBMITTED CHECK
    ((STATUS = 'DRAFT' AND SUBMITTED_AT IS NULL) OR
     (STATUS <> 'DRAFT' AND SUBMITTED_AT IS NOT NULL)),
  CONSTRAINT MB_LN_APP_CK_TERMINAL CHECK
    ((STATUS IN ('REJECTED','WITHDRAWN','EXPIRED','CONVERTED','CANCELLED')
      AND TERMINATED_AT IS NOT NULL) OR
     (STATUS NOT IN ('REJECTED','WITHDRAWN','EXPIRED','CONVERTED','CANCELLED')
      AND TERMINATED_AT IS NULL))
);
CREATE INDEX M08_LN_APP_IX_CIF
  ON M08_LOAN_APPLICATION(PRIMARY_CIF_ID, STATUS, CREATED_AT);
CREATE INDEX M08_LN_APP_IX_PRODUCT
  ON M08_LOAN_APPLICATION(PRODUCT_ID, PRODUCT_VERSION_ID, STATUS);
CREATE INDEX M08_LN_APP_IX_QUEUE
  ON M08_LOAN_APPLICATION(STATUS, ASSIGNED_TO_USER_ID, SUBMITTED_AT);

CREATE TABLE M08_LOAN_APPLICATION_PARTY (
  APPLICATION_PARTY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) NOT NULL
    REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  PARTY_ROLE VARCHAR2(20 CHAR) NOT NULL,
  LIABILITY_PCT NUMBER(7,4),
  CONSENT_STATUS VARCHAR2(16 CHAR) DEFAULT 'PENDING' NOT NULL,
  KYC_DECISION_REF VARCHAR2(100 CHAR) NOT NULL,
  KYC_EVALUATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  ADDED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  REMOVED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_APP_PARTY_UQ UNIQUE (APPLICATION_ID, CIF_ID, PARTY_ROLE),
  CONSTRAINT MB_LN_APP_PARTY_CK_ROLE CHECK
    (PARTY_ROLE IN ('PRIMARY_BORROWER','CO_BORROWER','GUARANTOR')),
  CONSTRAINT MB_LN_APP_PARTY_CK_LIABILITY CHECK
    (LIABILITY_PCT IS NULL OR LIABILITY_PCT > 0 AND LIABILITY_PCT <= 100),
  CONSTRAINT MB_LN_APP_PARTY_CK_CONSENT CHECK
    (CONSENT_STATUS IN ('PENDING','GIVEN','DECLINED','REVOKED')),
  CONSTRAINT MB_LN_APP_PARTY_CK_DATES CHECK
    (REMOVED_AT IS NULL OR REMOVED_AT > ADDED_AT)
);
CREATE INDEX M08_LN_APP_PARTY_IX_CIF
  ON M08_LOAN_APPLICATION_PARTY(CIF_ID, PARTY_ROLE);
CREATE UNIQUE INDEX M08_LN_APP_PARTY_UX_PRIMARY
  ON M08_LOAN_APPLICATION_PARTY
    (CASE WHEN PARTY_ROLE = 'PRIMARY_BORROWER' AND REMOVED_AT IS NULL
      THEN APPLICATION_ID END);

CREATE TABLE M08_LOAN_APPLICATION_REVISION (
  APPLICATION_REVISION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) NOT NULL
    REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  REVISION_NO NUMBER(6) NOT NULL,
  REVISION_REASON VARCHAR2(500 CHAR) NOT NULL,
  SNAPSHOT_JSON CLOB NOT NULL,
  CONTENT_HASH CHAR(64) NOT NULL,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  SUBMITTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_APP_REV_UQ_NO UNIQUE (APPLICATION_ID, REVISION_NO),
  CONSTRAINT MB_LN_APP_REV_UQ_SCOPE UNIQUE (APPLICATION_REVISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_APP_REV_CK_NO CHECK (REVISION_NO > 0),
  CONSTRAINT MB_LN_APP_REV_CK_JSON CHECK (SNAPSHOT_JSON IS JSON)
);
ALTER TABLE M08_LOAN_APPLICATION ADD CONSTRAINT MB_LN_APP_FK_CURRENT_REV
  FOREIGN KEY (CURRENT_REVISION_ID, APPLICATION_ID)
  REFERENCES M08_LOAN_APPLICATION_REVISION(APPLICATION_REVISION_ID, APPLICATION_ID);

CREATE TABLE M08_LOAN_ASSESSMENT (
  ASSESSMENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) NOT NULL,
  APPLICATION_REVISION_ID NUMBER(19) NOT NULL,
  ASSESSMENT_TYPE VARCHAR2(20 CHAR) NOT NULL,
  MONTHLY_INCOME NUMBER(18,2),
  MONTHLY_OBLIGATIONS NUMBER(18,2),
  DEBT_TO_INCOME_PCT NUMBER(9,6),
  COLLATERAL_VALUE NUMBER(18,2),
  LOAN_TO_VALUE_PCT NUMBER(9,6),
  CREDIT_SCORE NUMBER(6),
  RISK_GRADE VARCHAR2(20 CHAR),
  RECOMMENDATION VARCHAR2(20 CHAR) NOT NULL,
  RECOMMENDED_AMOUNT NUMBER(18,2),
  RECOMMENDED_TENURE_MONTHS NUMBER(4),
  REASON_CODES VARCHAR2(1000 CHAR) NOT NULL,
  CREDIT_EVIDENCE_REF VARCHAR2(200 CHAR),
  ASSESSED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  ASSESSED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONTENT_HASH CHAR(64) NOT NULL,
  CONSTRAINT MB_LN_ASSESS_UQ_SCOPE UNIQUE (ASSESSMENT_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_ASSESS_FK_REV FOREIGN KEY
    (APPLICATION_REVISION_ID, APPLICATION_ID)
    REFERENCES M08_LOAN_APPLICATION_REVISION(APPLICATION_REVISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_ASSESS_CK_TYPE CHECK
    (ASSESSMENT_TYPE IN ('INITIAL','REASSESSMENT','MANUAL_REVIEW')),
  CONSTRAINT MB_LN_ASSESS_CK_REC CHECK
    (RECOMMENDATION IN ('APPROVE','REJECT','REFER')),
  CONSTRAINT MB_LN_ASSESS_CK_VALUES CHECK
    ((MONTHLY_INCOME IS NULL OR MONTHLY_INCOME >= 0)
     AND (MONTHLY_OBLIGATIONS IS NULL OR MONTHLY_OBLIGATIONS >= 0)
     AND (DEBT_TO_INCOME_PCT IS NULL OR DEBT_TO_INCOME_PCT >= 0)
     AND (COLLATERAL_VALUE IS NULL OR COLLATERAL_VALUE >= 0)
     AND (LOAN_TO_VALUE_PCT IS NULL OR LOAN_TO_VALUE_PCT >= 0)
     AND (CREDIT_SCORE IS NULL OR CREDIT_SCORE >= 0)
     AND (RECOMMENDED_AMOUNT IS NULL OR RECOMMENDED_AMOUNT > 0)
     AND (RECOMMENDED_TENURE_MONTHS IS NULL OR RECOMMENDED_TENURE_MONTHS > 0))
);
CREATE INDEX M08_LN_ASSESS_IX_APP
  ON M08_LOAN_ASSESSMENT(APPLICATION_ID, ASSESSED_AT);

CREATE TABLE M08_LOAN_DECISION (
  DECISION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) NOT NULL,
  APPLICATION_REVISION_ID NUMBER(19) NOT NULL,
  ASSESSMENT_ID NUMBER(19),
  DECISION_CODE VARCHAR2(12 CHAR) NOT NULL,
  SANCTIONED_AMOUNT NUMBER(18,2),
  SANCTIONED_TENURE_MONTHS NUMBER(4),
  INTEREST_TYPE VARCHAR2(10 CHAR),
  ANNUAL_RATE_PCT NUMBER(12,8),
  FIXED_RATE_PCT NUMBER(12,8),
  RATE_INDEX_CODE VARCHAR2(40 CHAR),
  REFERENCE_RATE_PCT NUMBER(12,8),
  SPREAD_PCT NUMBER(12,8),
  RATE_RESET_FREQUENCY_MONTHS NUMBER(4),
  CONDITIONS_TEXT VARCHAR2(2000 CHAR),
  REASON_CODES VARCHAR2(1000 CHAR) NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  MAKER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  APPROVAL_AUTHORITY_CODE VARCHAR2(80 CHAR) NOT NULL,
  AUTHORITY_MAX_AMOUNT NUMBER(18,2) NOT NULL,
  AUTHORITY_EVIDENCE_REF VARCHAR2(100 CHAR) NOT NULL,
  DECISION_SCOPE_HASH CHAR(64) NOT NULL,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_DECISION_UQ_SCOPE UNIQUE (DECISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_DECISION_FK_REV FOREIGN KEY
    (APPLICATION_REVISION_ID, APPLICATION_ID)
    REFERENCES M08_LOAN_APPLICATION_REVISION(APPLICATION_REVISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_DECISION_FK_ASSESS FOREIGN KEY
    (ASSESSMENT_ID, APPLICATION_ID)
    REFERENCES M08_LOAN_ASSESSMENT(ASSESSMENT_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_DECISION_CK_CODE CHECK
    (DECISION_CODE IN ('APPROVE','REJECT','REFER')),
  CONSTRAINT MB_LN_DECISION_CK_SEPARATION CHECK (CHECKER_USER_ID <> MAKER_USER_ID),
  CONSTRAINT MB_LN_DECISION_CK_AUTHORITY CHECK (AUTHORITY_MAX_AMOUNT >= 0),
  CONSTRAINT MB_LN_DECISION_CK_APPROVAL CHECK
    ((DECISION_CODE = 'APPROVE' AND SANCTIONED_AMOUNT > 0
      AND SANCTIONED_TENURE_MONTHS > 0 AND INTEREST_TYPE IS NOT NULL
      AND ANNUAL_RATE_PCT >= 0 AND SANCTIONED_AMOUNT <= AUTHORITY_MAX_AMOUNT) OR
     (DECISION_CODE IN ('REJECT','REFER') AND SANCTIONED_AMOUNT IS NULL
      AND SANCTIONED_TENURE_MONTHS IS NULL AND INTEREST_TYPE IS NULL
      AND ANNUAL_RATE_PCT IS NULL)),
  CONSTRAINT MB_LN_DECISION_CK_INTEREST_TYPE CHECK
    (INTEREST_TYPE IS NULL OR INTEREST_TYPE IN ('FIXED','FLOATING')),
  CONSTRAINT MB_LN_DECISION_CK_RATE CHECK
    ((INTEREST_TYPE IS NULL AND FIXED_RATE_PCT IS NULL AND RATE_INDEX_CODE IS NULL
      AND REFERENCE_RATE_PCT IS NULL AND SPREAD_PCT IS NULL
      AND RATE_RESET_FREQUENCY_MONTHS IS NULL) OR
     (INTEREST_TYPE = 'FIXED' AND FIXED_RATE_PCT IS NOT NULL
      AND RATE_INDEX_CODE IS NULL AND REFERENCE_RATE_PCT IS NULL
      AND SPREAD_PCT IS NULL AND RATE_RESET_FREQUENCY_MONTHS IS NULL
      AND ANNUAL_RATE_PCT = FIXED_RATE_PCT) OR
     (INTEREST_TYPE = 'FLOATING' AND FIXED_RATE_PCT IS NULL
      AND RATE_INDEX_CODE IS NOT NULL AND REFERENCE_RATE_PCT IS NOT NULL
      AND SPREAD_PCT IS NOT NULL AND RATE_RESET_FREQUENCY_MONTHS > 0
      AND ANNUAL_RATE_PCT = REFERENCE_RATE_PCT + SPREAD_PCT))
);
CREATE INDEX M08_LN_DECISION_IX_APP
  ON M08_LOAN_DECISION(APPLICATION_ID, DECIDED_AT);

CREATE TABLE M08_LOAN_OFFER (
  OFFER_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  OFFER_NUMBER VARCHAR2(30 CHAR) NOT NULL UNIQUE,
  APPLICATION_ID NUMBER(19) NOT NULL
    REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  DECISION_ID NUMBER(19) NOT NULL UNIQUE,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'ISSUED' NOT NULL,
  TERMS_HASH CHAR(64) NOT NULL,
  OFFER_DOCUMENT_REF VARCHAR2(300 CHAR) NOT NULL,
  ISSUED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  DISBURSEMENT_ACCOUNT_ID NUMBER(19),
  REPAYMENT_ACCOUNT_ID NUMBER(19),
  ACCEPTED_BY_USER_ID VARCHAR2(36 CHAR),
  ACCEPTED_AT TIMESTAMP(6) WITH TIME ZONE,
  TERMINATED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_OFFER_UQ_SCOPE UNIQUE (OFFER_ID, APPLICATION_ID, DECISION_ID),
  CONSTRAINT MB_LN_OFFER_UQ_ACCOUNTS UNIQUE
    (OFFER_ID, DISBURSEMENT_ACCOUNT_ID, REPAYMENT_ACCOUNT_ID),
  CONSTRAINT MB_LN_OFFER_FK_DECISION FOREIGN KEY (DECISION_ID, APPLICATION_ID)
    REFERENCES M08_LOAN_DECISION(DECISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_OFFER_CK_STATUS CHECK
    (STATUS IN ('ISSUED','ACCEPTED','DECLINED','EXPIRED','WITHDRAWN')),
  CONSTRAINT MB_LN_OFFER_CK_EXPIRY CHECK (EXPIRES_AT > ISSUED_AT),
  CONSTRAINT MB_LN_OFFER_CK_ACCEPTED CHECK
    ((STATUS = 'ACCEPTED' AND ACCEPTED_BY_USER_ID IS NOT NULL
      AND ACCEPTED_AT IS NOT NULL AND ACCEPTED_AT <= EXPIRES_AT
      AND DISBURSEMENT_ACCOUNT_ID IS NOT NULL AND REPAYMENT_ACCOUNT_ID IS NOT NULL) OR
     (STATUS <> 'ACCEPTED' AND ACCEPTED_BY_USER_ID IS NULL AND ACCEPTED_AT IS NULL)),
  CONSTRAINT MB_LN_OFFER_CK_TERMINAL CHECK
    ((STATUS IN ('DECLINED','EXPIRED','WITHDRAWN') AND TERMINATED_AT IS NOT NULL) OR
     (STATUS IN ('ISSUED','ACCEPTED') AND TERMINATED_AT IS NULL))
);
CREATE INDEX M08_LN_OFFER_IX_APP
  ON M08_LOAN_OFFER(APPLICATION_ID, STATUS, EXPIRES_AT);
CREATE UNIQUE INDEX M08_LN_OFFER_UX_ACCEPTED
  ON M08_LOAN_OFFER(CASE WHEN STATUS = 'ACCEPTED' THEN APPLICATION_ID END);

CREATE TABLE M08_LOAN_FACILITY (
  FACILITY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_NUMBER VARCHAR2(30 CHAR) NOT NULL UNIQUE,
  APPLICATION_ID NUMBER(19) NOT NULL UNIQUE
    REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  DECISION_ID NUMBER(19) NOT NULL UNIQUE,
  OFFER_ID NUMBER(19) NOT NULL UNIQUE,
  PRIMARY_CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  PRODUCT_ID NUMBER(19) NOT NULL,
  PRODUCT_VERSION_ID NUMBER(19) NOT NULL,
  PRODUCT_RULE_SET_HASH CHAR(64) NOT NULL,
  BRANCH_CODE VARCHAR2(80 CHAR) NOT NULL,
  CURRENCY_CODE CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
  PRINCIPAL_AMOUNT NUMBER(18,2) NOT NULL,
  TOTAL_DISBURSED_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,
  TENURE_MONTHS NUMBER(4) NOT NULL,
  DISBURSEMENT_MODE VARCHAR2(12 CHAR) NOT NULL,
  REPAYMENT_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  AMORTIZATION_METHOD VARCHAR2(24 CHAR) NOT NULL,
  DAY_COUNT_BASIS VARCHAR2(20 CHAR) NOT NULL,
  INTEREST_TYPE VARCHAR2(10 CHAR) NOT NULL,
  ANNUAL_RATE_PCT NUMBER(12,8) NOT NULL,
  FIXED_RATE_PCT NUMBER(12,8),
  RATE_INDEX_CODE VARCHAR2(40 CHAR),
  REFERENCE_RATE_PCT NUMBER(12,8),
  SPREAD_PCT NUMBER(12,8),
  RATE_RESET_FREQUENCY_MONTHS NUMBER(4),
  LAST_RATE_RESET_DATE DATE,
  NEXT_RATE_RESET_DATE DATE,
  DISBURSEMENT_ACCOUNT_ID NUMBER(19) NOT NULL,
  REPAYMENT_ACCOUNT_ID NUMBER(19) NOT NULL,
  STATUS VARCHAR2(24 CHAR) DEFAULT 'PENDING_DISBURSEMENT' NOT NULL,
  START_DATE DATE,
  MATURITY_DATE DATE,
  CLOSED_AT TIMESTAMP(6) WITH TIME ZONE,
  PRINCIPAL_OUTSTANDING NUMBER(18,2) DEFAULT 0 NOT NULL,
  INTEREST_OUTSTANDING NUMBER(18,2) DEFAULT 0 NOT NULL,
  FEE_OUTSTANDING NUMBER(18,2) DEFAULT 0 NOT NULL,
  PENALTY_OUTSTANDING NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDUE_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,
  FINANCIAL_AS_OF TIMESTAMP(6) WITH TIME ZONE,
  LAST_LEDGER_EVENT_ID RAW(16),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_FACILITY_FK_DECISION FOREIGN KEY (DECISION_ID, APPLICATION_ID)
    REFERENCES M08_LOAN_DECISION(DECISION_ID, APPLICATION_ID),
  CONSTRAINT MB_LN_FACILITY_FK_OFFER FOREIGN KEY (OFFER_ID, APPLICATION_ID, DECISION_ID)
    REFERENCES M08_LOAN_OFFER(OFFER_ID, APPLICATION_ID, DECISION_ID),
  CONSTRAINT MB_LN_FACILITY_FK_APP_SCOPE FOREIGN KEY
    (APPLICATION_ID, PRIMARY_CIF_ID, PRODUCT_ID, PRODUCT_VERSION_ID)
    REFERENCES M08_LOAN_APPLICATION
      (APPLICATION_ID, PRIMARY_CIF_ID, PRODUCT_ID, PRODUCT_VERSION_ID),
  CONSTRAINT MB_LN_FACILITY_FK_OFFER_ACCOUNTS FOREIGN KEY
    (OFFER_ID, DISBURSEMENT_ACCOUNT_ID, REPAYMENT_ACCOUNT_ID)
    REFERENCES M08_LOAN_OFFER
      (OFFER_ID, DISBURSEMENT_ACCOUNT_ID, REPAYMENT_ACCOUNT_ID),
  CONSTRAINT MB_LN_FACILITY_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_LN_FACILITY_CK_AMOUNTS CHECK
    (PRINCIPAL_AMOUNT > 0 AND TOTAL_DISBURSED_AMOUNT >= 0
     AND TOTAL_DISBURSED_AMOUNT <= PRINCIPAL_AMOUNT AND TENURE_MONTHS > 0
     AND PRINCIPAL_OUTSTANDING >= 0 AND INTEREST_OUTSTANDING >= 0
     AND FEE_OUTSTANDING >= 0 AND PENALTY_OUTSTANDING >= 0
     AND OVERDUE_AMOUNT >= 0),
  CONSTRAINT MB_LN_FACILITY_CK_MODE CHECK
    (DISBURSEMENT_MODE IN ('SINGLE','TRANCHE')),
  CONSTRAINT MB_LN_FACILITY_CK_FREQUENCY CHECK
    (REPAYMENT_FREQUENCY IN ('WEEKLY','FORTNIGHTLY','MONTHLY','QUARTERLY','BULLET')),
  CONSTRAINT MB_LN_FACILITY_CK_AMORTIZATION CHECK
    (AMORTIZATION_METHOD IN ('REDUCING_BALANCE','FLAT','BULLET','CUSTOM')),
  CONSTRAINT MB_LN_FACILITY_CK_STATUS CHECK (STATUS IN
    ('PENDING_DISBURSEMENT','ACTIVE','MORATORIUM','DELINQUENT','RESTRUCTURED',
     'SETTLEMENT_PENDING','CLOSED','WRITTEN_OFF','CANCELLED')),
  CONSTRAINT MB_LN_FACILITY_CK_DATES CHECK
    (MATURITY_DATE IS NULL OR START_DATE IS NOT NULL AND MATURITY_DATE >= START_DATE),
  CONSTRAINT MB_LN_FACILITY_CK_CLOSED CHECK
    ((STATUS IN ('CLOSED','WRITTEN_OFF','CANCELLED') AND CLOSED_AT IS NOT NULL) OR
     (STATUS NOT IN ('CLOSED','WRITTEN_OFF','CANCELLED') AND CLOSED_AT IS NULL)),
  CONSTRAINT MB_LN_FACILITY_CK_RATE CHECK
    ((INTEREST_TYPE = 'FIXED' AND FIXED_RATE_PCT IS NOT NULL
      AND RATE_INDEX_CODE IS NULL AND REFERENCE_RATE_PCT IS NULL
      AND SPREAD_PCT IS NULL AND RATE_RESET_FREQUENCY_MONTHS IS NULL
      AND LAST_RATE_RESET_DATE IS NULL AND NEXT_RATE_RESET_DATE IS NULL
      AND ANNUAL_RATE_PCT = FIXED_RATE_PCT) OR
     (INTEREST_TYPE = 'FLOATING' AND FIXED_RATE_PCT IS NULL
      AND RATE_INDEX_CODE IS NOT NULL AND REFERENCE_RATE_PCT IS NOT NULL
      AND SPREAD_PCT IS NOT NULL AND RATE_RESET_FREQUENCY_MONTHS > 0
      AND NEXT_RATE_RESET_DATE IS NOT NULL
      AND ANNUAL_RATE_PCT = REFERENCE_RATE_PCT + SPREAD_PCT))
);
CREATE INDEX M08_LN_FACILITY_IX_CIF
  ON M08_LOAN_FACILITY(PRIMARY_CIF_ID, STATUS);
CREATE INDEX M08_LN_FACILITY_IX_PRODUCT
  ON M08_LOAN_FACILITY(PRODUCT_ID, PRODUCT_VERSION_ID, STATUS);
CREATE INDEX M08_LN_FACILITY_IX_ACCOUNTS
  ON M08_LOAN_FACILITY(REPAYMENT_ACCOUNT_ID, DISBURSEMENT_ACCOUNT_ID);

CREATE TABLE M08_LOAN_REPAYMENT_MANDATE (
  MANDATE_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  BANK_ACCOUNT_ID NUMBER(19) NOT NULL,
  MANDATE_TYPE VARCHAR2(24 CHAR) NOT NULL,
  EXTERNAL_MANDATE_REF VARCHAR2(120 CHAR),
  MAX_DEBIT_AMOUNT NUMBER(18,2),
  DEBIT_FREQUENCY VARCHAR2(20 CHAR) NOT NULL,
  VALID_FROM DATE NOT NULL,
  VALID_TO DATE,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'PENDING' NOT NULL,
  CUSTOMER_CONSENT_REF VARCHAR2(120 CHAR) NOT NULL,
  CONSENTED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  REVOKED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_MANDATE_UQ_REF UNIQUE (EXTERNAL_MANDATE_REF),
  CONSTRAINT MB_LN_MANDATE_CK_TYPE CHECK
    (MANDATE_TYPE IN ('INTERNAL_AUTODEBIT','STANDING_INSTRUCTION','NACH','UPI_AUTOPAY')),
  CONSTRAINT MB_LN_MANDATE_CK_AMOUNT CHECK
    (MAX_DEBIT_AMOUNT IS NULL OR MAX_DEBIT_AMOUNT > 0),
  CONSTRAINT MB_LN_MANDATE_CK_FREQUENCY CHECK
    (DEBIT_FREQUENCY IN ('WEEKLY','FORTNIGHTLY','MONTHLY','QUARTERLY','ON_DEMAND')),
  CONSTRAINT MB_LN_MANDATE_CK_DATES CHECK
    (VALID_TO IS NULL OR VALID_TO >= VALID_FROM),
  CONSTRAINT MB_LN_MANDATE_CK_STATUS CHECK
    (STATUS IN ('PENDING','ACTIVE','SUSPENDED','REVOKED','EXPIRED','REJECTED')),
  CONSTRAINT MB_LN_MANDATE_CK_REVOKED CHECK
    ((STATUS = 'REVOKED' AND REVOKED_AT IS NOT NULL) OR
     (STATUS <> 'REVOKED' AND REVOKED_AT IS NULL))
);
CREATE UNIQUE INDEX M08_LN_MANDATE_UX_ACTIVE
  ON M08_LOAN_REPAYMENT_MANDATE(CASE WHEN STATUS = 'ACTIVE' THEN FACILITY_ID END);
CREATE INDEX M08_LN_MANDATE_IX_ACCOUNT
  ON M08_LOAN_REPAYMENT_MANDATE(BANK_ACCOUNT_ID, STATUS);

CREATE TABLE M08_LOAN_DISBURSEMENT (
  DISBURSEMENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  DISBURSEMENT_SEQ_NO NUMBER(5) NOT NULL,
  TARGET_ACCOUNT_ID NUMBER(19) NOT NULL,
  AMOUNT NUMBER(18,2) NOT NULL,
  VALUE_DATE DATE NOT NULL,
  STATUS VARCHAR2(20 CHAR) DEFAULT 'REQUESTED' NOT NULL,
  REQUEST_KEY VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  REQUESTED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  APPROVED_BY_USER_ID VARCHAR2(36 CHAR),
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVAL_AUTHORITY_CODE VARCHAR2(80 CHAR),
  TXN_ID NUMBER(19),
  GL_JOURNAL_ID NUMBER(19),
  POSTED_AT TIMESTAMP(6) WITH TIME ZONE,
  FAILURE_CODE VARCHAR2(80 CHAR),
  REVERSAL_OF_DISBURSEMENT_ID NUMBER(19)
    REFERENCES M08_LOAN_DISBURSEMENT(DISBURSEMENT_ID),
  CONSTRAINT MB_LN_DISB_UQ_SEQ UNIQUE (FACILITY_ID, DISBURSEMENT_SEQ_NO),
  CONSTRAINT MB_LN_DISB_UQ_REVERSAL UNIQUE (REVERSAL_OF_DISBURSEMENT_ID),
  CONSTRAINT MB_LN_DISB_CK_AMOUNT CHECK (AMOUNT > 0),
  CONSTRAINT MB_LN_DISB_CK_STATUS CHECK
    (STATUS IN ('REQUESTED','APPROVED','POSTING','POSTED','FAILED','REVERSED','CANCELLED')),
  CONSTRAINT MB_LN_DISB_CK_SEPARATION CHECK
    (APPROVED_BY_USER_ID IS NULL OR APPROVED_BY_USER_ID <> REQUESTED_BY_USER_ID),
  CONSTRAINT MB_LN_DISB_CK_APPROVAL CHECK
    ((STATUS = 'REQUESTED' AND APPROVED_BY_USER_ID IS NULL AND APPROVED_AT IS NULL) OR
     (STATUS IN ('APPROVED','POSTING','POSTED','FAILED','REVERSED')
      AND APPROVED_BY_USER_ID IS NOT NULL AND APPROVED_AT IS NOT NULL
      AND APPROVAL_AUTHORITY_CODE IS NOT NULL) OR
     (STATUS = 'CANCELLED')),
  CONSTRAINT MB_LN_DISB_CK_POSTING CHECK
    ((STATUS IN ('POSTED','REVERSED') AND TXN_ID IS NOT NULL
      AND GL_JOURNAL_ID IS NOT NULL AND POSTED_AT IS NOT NULL) OR
     (STATUS NOT IN ('POSTED','REVERSED') AND POSTED_AT IS NULL)),
  CONSTRAINT MB_LN_DISB_CK_FAILURE CHECK
    ((STATUS = 'FAILED' AND FAILURE_CODE IS NOT NULL) OR
     (STATUS <> 'FAILED' AND FAILURE_CODE IS NULL))
);
CREATE INDEX M08_LN_DISB_IX_FACILITY
  ON M08_LOAN_DISBURSEMENT(FACILITY_ID, STATUS, VALUE_DATE);
CREATE UNIQUE INDEX M08_LN_DISB_UX_TXN
  ON M08_LOAN_DISBURSEMENT(CASE WHEN TXN_ID IS NOT NULL THEN TXN_ID END);
CREATE UNIQUE INDEX M08_LN_DISB_UX_JOURNAL
  ON M08_LOAN_DISBURSEMENT(CASE WHEN GL_JOURNAL_ID IS NOT NULL THEN GL_JOURNAL_ID END);

CREATE TABLE M08_LOAN_RATE_HISTORY (
  RATE_HISTORY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  EFFECTIVE_FROM_DATE DATE NOT NULL,
  EFFECTIVE_TO_DATE DATE,
  INTEREST_TYPE VARCHAR2(10 CHAR) NOT NULL,
  ANNUAL_RATE_PCT NUMBER(12,8) NOT NULL,
  FIXED_RATE_PCT NUMBER(12,8),
  RATE_INDEX_CODE VARCHAR2(40 CHAR),
  REFERENCE_RATE_PCT NUMBER(12,8),
  SPREAD_PCT NUMBER(12,8),
  RESET_REASON VARCHAR2(40 CHAR) NOT NULL,
  RATE_SOURCE_REF VARCHAR2(120 CHAR),
  SERVICE_REQUEST_ID NUMBER(19),
  RECORDED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  RECORDED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_RATE_UQ_START UNIQUE (FACILITY_ID, EFFECTIVE_FROM_DATE),
  CONSTRAINT MB_LN_RATE_CK_DATES CHECK
    (EFFECTIVE_TO_DATE IS NULL OR EFFECTIVE_TO_DATE >= EFFECTIVE_FROM_DATE),
  CONSTRAINT MB_LN_RATE_CK_REASON CHECK
    (RESET_REASON IN ('ORIGINATION','INDEX_RESET','APPROVED_OVERRIDE','RESTRUCTURE')),
  CONSTRAINT MB_LN_RATE_CK_VALUES CHECK
    ((INTEREST_TYPE = 'FIXED' AND FIXED_RATE_PCT IS NOT NULL
      AND RATE_INDEX_CODE IS NULL AND REFERENCE_RATE_PCT IS NULL AND SPREAD_PCT IS NULL
      AND ANNUAL_RATE_PCT = FIXED_RATE_PCT) OR
     (INTEREST_TYPE = 'FLOATING' AND FIXED_RATE_PCT IS NULL
      AND RATE_INDEX_CODE IS NOT NULL AND REFERENCE_RATE_PCT IS NOT NULL
      AND SPREAD_PCT IS NOT NULL
      AND ANNUAL_RATE_PCT = REFERENCE_RATE_PCT + SPREAD_PCT))
);
CREATE INDEX M08_LN_RATE_IX_FACILITY
  ON M08_LOAN_RATE_HISTORY(FACILITY_ID, EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE);

CREATE TABLE M08_LOAN_SCHEDULE (
  SCHEDULE_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  SCHEDULE_SEQ_NO NUMBER(6) NOT NULL,
  GENERATION_REASON VARCHAR2(20 CHAR) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'DRAFT' NOT NULL,
  EFFECTIVE_FROM_DATE DATE NOT NULL,
  INSTALLMENT_COUNT NUMBER(6) NOT NULL,
  TOTAL_PRINCIPAL NUMBER(18,2) NOT NULL,
  TOTAL_INTEREST NUMBER(18,2) NOT NULL,
  TOTAL_FEES NUMBER(18,2) DEFAULT 0 NOT NULL,
  SCHEDULE_HASH CHAR(64) NOT NULL,
  CREATED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ACTIVATED_AT TIMESTAMP(6) WITH TIME ZONE,
  SUPERSEDED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_SCHEDULE_UQ_SEQ UNIQUE (FACILITY_ID, SCHEDULE_SEQ_NO),
  CONSTRAINT MB_LN_SCHEDULE_CK_REASON CHECK
    (GENERATION_REASON IN ('ORIGINATION','RATE_RESET','RESTRUCTURE','PREPAYMENT','MORATORIUM','CORRECTION')),
  CONSTRAINT MB_LN_SCHEDULE_CK_STATUS CHECK
    (STATUS IN ('DRAFT','ACTIVE','SUPERSEDED','CANCELLED')),
  CONSTRAINT MB_LN_SCHEDULE_CK_TOTALS CHECK
    (INSTALLMENT_COUNT > 0 AND TOTAL_PRINCIPAL >= 0
     AND TOTAL_INTEREST >= 0 AND TOTAL_FEES >= 0),
  CONSTRAINT MB_LN_SCHEDULE_CK_TIMES CHECK
    ((STATUS = 'DRAFT' AND ACTIVATED_AT IS NULL AND SUPERSEDED_AT IS NULL) OR
     (STATUS = 'ACTIVE' AND ACTIVATED_AT IS NOT NULL AND SUPERSEDED_AT IS NULL) OR
     (STATUS = 'SUPERSEDED' AND ACTIVATED_AT IS NOT NULL AND SUPERSEDED_AT IS NOT NULL) OR
     (STATUS = 'CANCELLED' AND SUPERSEDED_AT IS NOT NULL))
);
CREATE UNIQUE INDEX M08_LN_SCHEDULE_UX_ACTIVE
  ON M08_LOAN_SCHEDULE(CASE WHEN STATUS = 'ACTIVE' THEN FACILITY_ID END);

CREATE TABLE M08_LOAN_SCHEDULE_ITEM (
  SCHEDULE_ITEM_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  SCHEDULE_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_SCHEDULE(SCHEDULE_ID),
  INSTALLMENT_NO NUMBER(6) NOT NULL,
  DUE_DATE DATE NOT NULL,
  OPENING_PRINCIPAL NUMBER(18,2) NOT NULL,
  PRINCIPAL_DUE NUMBER(18,2) DEFAULT 0 NOT NULL,
  INTEREST_DUE NUMBER(18,2) DEFAULT 0 NOT NULL,
  FEE_DUE NUMBER(18,2) DEFAULT 0 NOT NULL,
  PENALTY_DUE NUMBER(18,2) DEFAULT 0 NOT NULL,
  PRINCIPAL_PAID NUMBER(18,2) DEFAULT 0 NOT NULL,
  INTEREST_PAID NUMBER(18,2) DEFAULT 0 NOT NULL,
  FEE_PAID NUMBER(18,2) DEFAULT 0 NOT NULL,
  PENALTY_PAID NUMBER(18,2) DEFAULT 0 NOT NULL,
  PRINCIPAL_WAIVED NUMBER(18,2) DEFAULT 0 NOT NULL,
  INTEREST_WAIVED NUMBER(18,2) DEFAULT 0 NOT NULL,
  FEE_WAIVED NUMBER(18,2) DEFAULT 0 NOT NULL,
  PENALTY_WAIVED NUMBER(18,2) DEFAULT 0 NOT NULL,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'PENDING' NOT NULL,
  SETTLED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_SCHEDULE_ITEM_UQ UNIQUE (SCHEDULE_ID, INSTALLMENT_NO),
  CONSTRAINT MB_LN_SCHEDULE_ITEM_CK_NO CHECK (INSTALLMENT_NO > 0),
  CONSTRAINT MB_LN_SCHEDULE_ITEM_CK_AMOUNTS CHECK
    (OPENING_PRINCIPAL >= 0 AND PRINCIPAL_DUE >= 0 AND INTEREST_DUE >= 0
     AND FEE_DUE >= 0 AND PENALTY_DUE >= 0 AND PRINCIPAL_PAID >= 0
     AND INTEREST_PAID >= 0 AND FEE_PAID >= 0 AND PENALTY_PAID >= 0
     AND PRINCIPAL_WAIVED >= 0 AND INTEREST_WAIVED >= 0
     AND FEE_WAIVED >= 0 AND PENALTY_WAIVED >= 0
     AND PRINCIPAL_PAID + PRINCIPAL_WAIVED <= PRINCIPAL_DUE
     AND INTEREST_PAID + INTEREST_WAIVED <= INTEREST_DUE
     AND FEE_PAID + FEE_WAIVED <= FEE_DUE
     AND PENALTY_PAID + PENALTY_WAIVED <= PENALTY_DUE),
  CONSTRAINT MB_LN_SCHEDULE_ITEM_CK_STATUS CHECK
    (STATUS IN ('PENDING','PART_PAID','PAID','OVERDUE','WAIVED','CANCELLED')),
  CONSTRAINT MB_LN_SCHEDULE_ITEM_CK_SETTLED CHECK
    ((STATUS IN ('PAID','WAIVED','CANCELLED') AND SETTLED_AT IS NOT NULL) OR
     (STATUS IN ('PENDING','PART_PAID','OVERDUE') AND SETTLED_AT IS NULL))
);
CREATE INDEX M08_LN_SCHEDULE_ITEM_IX_DUE
  ON M08_LOAN_SCHEDULE_ITEM(SCHEDULE_ID, STATUS, DUE_DATE);

CREATE TABLE M08_LOAN_ACCRUAL (
  ACCRUAL_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  SCHEDULE_ITEM_ID NUMBER(19) REFERENCES M08_LOAN_SCHEDULE_ITEM(SCHEDULE_ITEM_ID),
  ACCRUAL_DATE DATE NOT NULL,
  ACCRUAL_TYPE VARCHAR2(12 CHAR) NOT NULL,
  PRINCIPAL_BASIS NUMBER(18,2) NOT NULL,
  RATE_PCT NUMBER(12,8) NOT NULL,
  ACCRUED_AMOUNT NUMBER(18,2) NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'CALCULATED' NOT NULL,
  TXN_ID NUMBER(19),
  GL_JOURNAL_ID NUMBER(19),
  REVERSAL_OF_ACCRUAL_ID NUMBER(19) REFERENCES M08_LOAN_ACCRUAL(ACCRUAL_ID),
  CALCULATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  POSTED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_ACCRUAL_UQ UNIQUE (FACILITY_ID, ACCRUAL_DATE, ACCRUAL_TYPE),
  CONSTRAINT MB_LN_ACCRUAL_UQ_REV UNIQUE (REVERSAL_OF_ACCRUAL_ID),
  CONSTRAINT MB_LN_ACCRUAL_CK_TYPE CHECK
    (ACCRUAL_TYPE IN ('INTEREST','PENALTY','FEE')),
  CONSTRAINT MB_LN_ACCRUAL_CK_AMOUNT CHECK
    (PRINCIPAL_BASIS >= 0 AND RATE_PCT >= 0 AND ACCRUED_AMOUNT >= 0),
  CONSTRAINT MB_LN_ACCRUAL_CK_STATUS CHECK
    (STATUS IN ('CALCULATED','POSTED','REVERSED','CANCELLED')),
  CONSTRAINT MB_LN_ACCRUAL_CK_POSTING CHECK
    ((STATUS IN ('POSTED','REVERSED') AND TXN_ID IS NOT NULL
      AND GL_JOURNAL_ID IS NOT NULL AND POSTED_AT IS NOT NULL) OR
     (STATUS IN ('CALCULATED','CANCELLED') AND POSTED_AT IS NULL))
);
CREATE INDEX M08_LN_ACCRUAL_IX_FACILITY
  ON M08_LOAN_ACCRUAL(FACILITY_ID, ACCRUAL_DATE, STATUS);

CREATE TABLE M08_LOAN_PAYMENT (
  LOAN_PAYMENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  PAYMENT_SOURCE_CODE VARCHAR2(20 CHAR) NOT NULL,
  SOURCE_ACCOUNT_ID NUMBER(19),
  SOURCE_PAYMENT_ID NUMBER(19),
  TXN_ID NUMBER(19) NOT NULL,
  GL_JOURNAL_ID NUMBER(19) NOT NULL,
  REQUEST_KEY VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  AMOUNT NUMBER(18,2) NOT NULL,
  CURRENCY_CODE CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
  VALUE_DATE DATE NOT NULL,
  BOOKED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'POSTED' NOT NULL,
  PAYMENT_KIND VARCHAR2(10 CHAR) DEFAULT 'ORIGINAL' NOT NULL,
  REVERSAL_OF_PAYMENT_ID NUMBER(19) REFERENCES M08_LOAN_PAYMENT(LOAN_PAYMENT_ID),
  REVERSAL_REASON VARCHAR2(500 CHAR),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_PAYMENT_UQ_TXN UNIQUE (TXN_ID),
  CONSTRAINT MB_LN_PAYMENT_UQ_JOURNAL UNIQUE (GL_JOURNAL_ID),
  CONSTRAINT MB_LN_PAYMENT_UQ_REV UNIQUE (REVERSAL_OF_PAYMENT_ID),
  CONSTRAINT MB_LN_PAYMENT_CK_AMOUNT CHECK (AMOUNT > 0),
  CONSTRAINT MB_LN_PAYMENT_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_LN_PAYMENT_CK_STATUS CHECK
    (STATUS IN ('POSTED','ALLOCATED','PART_ALLOCATED','REVERSED')),
  CONSTRAINT MB_LN_PAYMENT_CK_SOURCE CHECK
    ((PAYMENT_SOURCE_CODE = 'ACCOUNT' AND SOURCE_ACCOUNT_ID IS NOT NULL
      AND SOURCE_PAYMENT_ID IS NULL) OR
     (PAYMENT_SOURCE_CODE = 'PAYMENT_RAIL' AND SOURCE_PAYMENT_ID IS NOT NULL) OR
     (PAYMENT_SOURCE_CODE IN ('CASH','ADJUSTMENT')
      AND SOURCE_ACCOUNT_ID IS NULL AND SOURCE_PAYMENT_ID IS NULL)),
  CONSTRAINT MB_LN_PAYMENT_CK_KIND CHECK
    (PAYMENT_KIND IN ('ORIGINAL','REVERSAL')),
  CONSTRAINT MB_LN_PAYMENT_CK_REVERSAL CHECK
    ((PAYMENT_KIND = 'ORIGINAL' AND REVERSAL_OF_PAYMENT_ID IS NULL
      AND REVERSAL_REASON IS NULL) OR
     (PAYMENT_KIND = 'REVERSAL' AND REVERSAL_OF_PAYMENT_ID IS NOT NULL
      AND REVERSAL_REASON IS NOT NULL)),
  CONSTRAINT MB_LN_PAYMENT_CK_REVERSED_STATUS CHECK
    (STATUS <> 'REVERSED' OR PAYMENT_KIND = 'ORIGINAL')
);
CREATE INDEX M08_LN_PAYMENT_IX_FACILITY
  ON M08_LOAN_PAYMENT(FACILITY_ID, VALUE_DATE, STATUS);

CREATE TABLE M08_LOAN_PAYMENT_ALLOCATION (
  PAYMENT_ALLOCATION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  LOAN_PAYMENT_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_PAYMENT(LOAN_PAYMENT_ID),
  ALLOCATION_SEQ_NO NUMBER(5) NOT NULL,
  SCHEDULE_ITEM_ID NUMBER(19) REFERENCES M08_LOAN_SCHEDULE_ITEM(SCHEDULE_ITEM_ID),
  ALLOCATION_TYPE VARCHAR2(12 CHAR) NOT NULL,
  AMOUNT NUMBER(18,2) NOT NULL,
  ALLOCATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  ALLOCATION_RULE_CODE VARCHAR2(40 CHAR) NOT NULL,
  CONSTRAINT MB_LN_ALLOC_UQ_SEQ UNIQUE (LOAN_PAYMENT_ID, ALLOCATION_SEQ_NO),
  CONSTRAINT MB_LN_ALLOC_CK_TYPE CHECK
    (ALLOCATION_TYPE IN ('PRINCIPAL','INTEREST','FEE','PENALTY','UNAPPLIED','REFUND')),
  CONSTRAINT MB_LN_ALLOC_CK_AMOUNT CHECK (AMOUNT > 0),
  CONSTRAINT MB_LN_ALLOC_CK_ITEM CHECK
    ((ALLOCATION_TYPE IN ('UNAPPLIED','REFUND') AND SCHEDULE_ITEM_ID IS NULL) OR
     (ALLOCATION_TYPE IN ('PRINCIPAL','INTEREST','FEE','PENALTY')
      AND SCHEDULE_ITEM_ID IS NOT NULL))
);
CREATE INDEX M08_LN_ALLOC_IX_ITEM
  ON M08_LOAN_PAYMENT_ALLOCATION(SCHEDULE_ITEM_ID, ALLOCATION_TYPE);

CREATE TABLE M08_LOAN_COLLATERAL (
  COLLATERAL_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  FACILITY_ID NUMBER(19) REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  OWNER_CIF_ID VARCHAR2(36 CHAR) NOT NULL,
  COLLATERAL_TYPE VARCHAR2(30 CHAR) NOT NULL,
  EXTERNAL_REFERENCE VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  DESCRIPTION VARCHAR2(1000 CHAR) NOT NULL,
  VALUATION_AMOUNT NUMBER(18,2),
  CURRENCY_CODE CHAR(3 CHAR) DEFAULT 'INR' NOT NULL,
  VALUED_AT DATE,
  VALUATION_EXPIRES_AT DATE,
  LIEN_STATUS VARCHAR2(16 CHAR) DEFAULT 'PROPOSED' NOT NULL,
  CUSTODIAN_REFERENCE VARCHAR2(120 CHAR),
  RELEASED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_LN_COLLATERAL_CK_SCOPE CHECK
    (APPLICATION_ID IS NOT NULL OR FACILITY_ID IS NOT NULL),
  CONSTRAINT MB_LN_COLLATERAL_CK_VALUE CHECK
    (VALUATION_AMOUNT IS NULL OR VALUATION_AMOUNT >= 0),
  CONSTRAINT MB_LN_COLLATERAL_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_LN_COLLATERAL_CK_VAL_DATE CHECK
    (VALUATION_EXPIRES_AT IS NULL OR VALUED_AT IS NOT NULL
     AND VALUATION_EXPIRES_AT >= VALUED_AT),
  CONSTRAINT MB_LN_COLLATERAL_CK_LIEN CHECK
    (LIEN_STATUS IN ('PROPOSED','PERFECTED','RELEASE_PENDING','RELEASED','REJECTED')),
  CONSTRAINT MB_LN_COLLATERAL_CK_RELEASE CHECK
    ((LIEN_STATUS = 'RELEASED' AND RELEASED_AT IS NOT NULL) OR
     (LIEN_STATUS <> 'RELEASED' AND RELEASED_AT IS NULL))
);
CREATE INDEX M08_LN_COLLATERAL_IX_APP
  ON M08_LOAN_COLLATERAL(APPLICATION_ID, LIEN_STATUS);
CREATE INDEX M08_LN_COLLATERAL_IX_FACILITY
  ON M08_LOAN_COLLATERAL(FACILITY_ID, LIEN_STATUS);

CREATE TABLE M08_LOAN_SERVICE_REQUEST (
  SERVICE_REQUEST_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  REQUEST_TYPE VARCHAR2(24 CHAR) NOT NULL,
  STATUS VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL,
  REQUESTED_AMOUNT NUMBER(18,2),
  PROPOSED_TERMS_JSON CLOB,
  PROPOSED_TERMS_HASH CHAR(64),
  REASON VARCHAR2(1000 CHAR) NOT NULL,
  REQUEST_KEY VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  REQUESTED_BY_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  SUBMITTED_AT TIMESTAMP(6) WITH TIME ZONE,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  APPLIED_AT TIMESTAMP(6) WITH TIME ZONE,
  CLEARANCE_REFERENCE VARCHAR2(120 CHAR),
  CONSTRAINT MB_LN_SERVICE_UQ_MAKER UNIQUE (SERVICE_REQUEST_ID, REQUESTED_BY_USER_ID),
  CONSTRAINT MB_LN_SERVICE_CK_TYPE CHECK (REQUEST_TYPE IN
    ('RESTRUCTURE','PREPAYMENT','SETTLEMENT','WAIVER','WRITE_OFF','CLOSE',
     'ACCOUNT_CHANGE','MORATORIUM','RATE_EXCEPTION','COLLATERAL_RELEASE')),
  CONSTRAINT MB_LN_SERVICE_CK_STATUS CHECK
    (STATUS IN ('DRAFT','SUBMITTED','APPROVED','REJECTED','APPLYING','APPLIED','FAILED','CANCELLED')),
  CONSTRAINT MB_LN_SERVICE_CK_AMOUNT CHECK
    (REQUESTED_AMOUNT IS NULL OR REQUESTED_AMOUNT > 0),
  CONSTRAINT MB_LN_SERVICE_CK_JSON CHECK
    (PROPOSED_TERMS_JSON IS NULL OR PROPOSED_TERMS_JSON IS JSON),
  CONSTRAINT MB_LN_SERVICE_CK_HASH CHECK
    ((PROPOSED_TERMS_JSON IS NULL AND PROPOSED_TERMS_HASH IS NULL) OR
     (PROPOSED_TERMS_JSON IS NOT NULL AND PROPOSED_TERMS_HASH IS NOT NULL)),
  CONSTRAINT MB_LN_SERVICE_CK_TIMES CHECK
    ((STATUS = 'DRAFT' AND SUBMITTED_AT IS NULL AND DECIDED_AT IS NULL AND APPLIED_AT IS NULL) OR
     (STATUS = 'SUBMITTED' AND SUBMITTED_AT IS NOT NULL AND DECIDED_AT IS NULL AND APPLIED_AT IS NULL) OR
     (STATUS IN ('APPROVED','REJECTED') AND SUBMITTED_AT IS NOT NULL
      AND DECIDED_AT IS NOT NULL AND APPLIED_AT IS NULL) OR
     (STATUS IN ('APPLYING','FAILED') AND SUBMITTED_AT IS NOT NULL
      AND DECIDED_AT IS NOT NULL AND APPLIED_AT IS NULL) OR
     (STATUS = 'APPLIED' AND SUBMITTED_AT IS NOT NULL
      AND DECIDED_AT IS NOT NULL AND APPLIED_AT IS NOT NULL) OR
     (STATUS = 'CANCELLED'))
);
CREATE INDEX M08_LN_SERVICE_IX_QUEUE
  ON M08_LOAN_SERVICE_REQUEST(STATUS, REQUEST_TYPE, SUBMITTED_AT);

CREATE TABLE M08_LOAN_SERVICE_APPROVAL (
  SERVICE_APPROVAL_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  SERVICE_REQUEST_ID NUMBER(19) NOT NULL UNIQUE
    REFERENCES M08_LOAN_SERVICE_REQUEST(SERVICE_REQUEST_ID),
  DECISION_CODE VARCHAR2(10 CHAR) NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_SESSION_ID VARCHAR2(36 CHAR) NOT NULL,
  APPROVAL_AUTHORITY_CODE VARCHAR2(80 CHAR) NOT NULL,
  AUTHORITY_MAX_AMOUNT NUMBER(18,2),
  AUTHORITY_EVIDENCE_REF VARCHAR2(100 CHAR) NOT NULL,
  DECISION_SCOPE_HASH CHAR(64) NOT NULL,
  DECISION_REASON VARCHAR2(1000 CHAR) NOT NULL,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_SERVICE_APPR_CK_DECISION CHECK
    (DECISION_CODE IN ('APPROVE','REJECT')),
  CONSTRAINT MB_LN_SERVICE_APPR_FK_MAKER FOREIGN KEY
    (SERVICE_REQUEST_ID, MAKER_USER_ID)
    REFERENCES M08_LOAN_SERVICE_REQUEST(SERVICE_REQUEST_ID, REQUESTED_BY_USER_ID),
  CONSTRAINT MB_LN_SERVICE_APPR_CK_SEPARATION CHECK
    (CHECKER_USER_ID <> MAKER_USER_ID),
  CONSTRAINT MB_LN_SERVICE_APPR_CK_LIMIT CHECK
    (AUTHORITY_MAX_AMOUNT IS NULL OR AUTHORITY_MAX_AMOUNT >= 0)
);

ALTER TABLE M08_LOAN_RATE_HISTORY ADD CONSTRAINT MB_LN_RATE_FK_SERVICE_REQUEST
  FOREIGN KEY (SERVICE_REQUEST_ID)
  REFERENCES M08_LOAN_SERVICE_REQUEST(SERVICE_REQUEST_ID);

CREATE TABLE M08_LOAN_DOCUMENT_REF (
  DOCUMENT_REF_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  APPLICATION_ID NUMBER(19) REFERENCES M08_LOAN_APPLICATION(APPLICATION_ID),
  FACILITY_ID NUMBER(19) REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  SERVICE_REQUEST_ID NUMBER(19) REFERENCES M08_LOAN_SERVICE_REQUEST(SERVICE_REQUEST_ID),
  DOCUMENT_TYPE VARCHAR2(40 CHAR) NOT NULL,
  STORAGE_REFERENCE VARCHAR2(500 CHAR) NOT NULL,
  CONTENT_HASH CHAR(64) NOT NULL,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'RECEIVED' NOT NULL,
  VERIFIED_BY_USER_ID VARCHAR2(36 CHAR),
  VERIFIED_AT TIMESTAMP(6) WITH TIME ZONE,
  RETAIN_UNTIL DATE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_DOC_UQ_HASH UNIQUE (STORAGE_REFERENCE, CONTENT_HASH),
  CONSTRAINT MB_LN_DOC_CK_SCOPE CHECK
    (APPLICATION_ID IS NOT NULL OR FACILITY_ID IS NOT NULL OR SERVICE_REQUEST_ID IS NOT NULL),
  CONSTRAINT MB_LN_DOC_CK_STATUS CHECK
    (STATUS IN ('RECEIVED','VERIFIED','REJECTED','EXPIRED','SUPERSEDED')),
  CONSTRAINT MB_LN_DOC_CK_VERIFIED CHECK
    ((STATUS = 'VERIFIED' AND VERIFIED_BY_USER_ID IS NOT NULL AND VERIFIED_AT IS NOT NULL) OR
     (STATUS <> 'VERIFIED' AND VERIFIED_BY_USER_ID IS NULL AND VERIFIED_AT IS NULL))
);
CREATE INDEX M08_LN_DOC_IX_APP
  ON M08_LOAN_DOCUMENT_REF(APPLICATION_ID, DOCUMENT_TYPE, STATUS);
CREATE INDEX M08_LN_DOC_IX_FACILITY
  ON M08_LOAN_DOCUMENT_REF(FACILITY_ID, DOCUMENT_TYPE, STATUS);

CREATE TABLE M08_LOAN_DELINQUENCY_SNAPSHOT (
  DELINQUENCY_SNAPSHOT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  AS_OF_DATE DATE NOT NULL,
  DAYS_PAST_DUE NUMBER(6) DEFAULT 0 NOT NULL,
  DELINQUENCY_BUCKET VARCHAR2(20 CHAR) NOT NULL,
  CLASSIFICATION_CODE VARCHAR2(20 CHAR) NOT NULL,
  OVERDUE_PRINCIPAL NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDUE_INTEREST NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDUE_FEES NUMBER(18,2) DEFAULT 0 NOT NULL,
  OVERDUE_PENALTIES NUMBER(18,2) DEFAULT 0 NOT NULL,
  EARLIEST_UNPAID_DUE_DATE DATE,
  SOURCE_EVENT_ID RAW(16) NOT NULL,
  RECORDED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_DELINQ_UQ_DATE UNIQUE (FACILITY_ID, AS_OF_DATE),
  CONSTRAINT MB_LN_DELINQ_UQ_EVENT UNIQUE (SOURCE_EVENT_ID),
  CONSTRAINT MB_LN_DELINQ_CK_DPD CHECK (DAYS_PAST_DUE >= 0),
  CONSTRAINT MB_LN_DELINQ_CK_BUCKET CHECK
    (DELINQUENCY_BUCKET IN ('CURRENT','DPD_1_30','DPD_31_60','DPD_61_90','DPD_90_PLUS')),
  CONSTRAINT MB_LN_DELINQ_CK_AMOUNTS CHECK
    (OVERDUE_PRINCIPAL >= 0 AND OVERDUE_INTEREST >= 0
     AND OVERDUE_FEES >= 0 AND OVERDUE_PENALTIES >= 0)
);
-- LN_DELINQ_UQ_DATE already indexes (FACILITY_ID, AS_OF_DATE).

CREATE TABLE M08_LOAN_STATUS_HISTORY (
  STATUS_HISTORY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  RESOURCE_TYPE VARCHAR2(24 CHAR) NOT NULL,
  RESOURCE_ID NUMBER(19) NOT NULL,
  FROM_STATUS VARCHAR2(24 CHAR),
  TO_STATUS VARCHAR2(24 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR) NOT NULL,
  REASON_TEXT VARCHAR2(1000 CHAR),
  ACTOR_USER_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  CORRELATION_ID VARCHAR2(100 CHAR) NOT NULL,
  CHANGED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_STATUS_CK_RESOURCE CHECK
    (RESOURCE_TYPE IN ('APPLICATION','OFFER','FACILITY','DISBURSEMENT','SERVICE_REQUEST'))
);
CREATE INDEX M08_LN_STATUS_IX_RESOURCE
  ON M08_LOAN_STATUS_HISTORY(RESOURCE_TYPE, RESOURCE_ID, CHANGED_AT);

CREATE TABLE M08_LOAN_IDEMPOTENCY_RECORD (
  ACTOR_ID VARCHAR2(64 CHAR) NOT NULL,
  OPERATION_CODE VARCHAR2(50 CHAR) NOT NULL,
  IDEMPOTENCY_KEY VARCHAR2(120 CHAR) NOT NULL,
  REQUEST_HASH RAW(32) NOT NULL,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'IN_PROGRESS' NOT NULL,
  RESPONSE_CODE VARCHAR2(30 CHAR),
  RESPONSE_JSON CLOB,
  RESOURCE_TYPE VARCHAR2(30 CHAR),
  RESOURCE_ID VARCHAR2(80 CHAR),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  CONSTRAINT MB_PK_LN_IDEMPOTENCY PRIMARY KEY (ACTOR_ID, OPERATION_CODE, IDEMPOTENCY_KEY),
  CONSTRAINT MB_LN_IDEMP_CK_STATUS CHECK
    (STATUS IN ('IN_PROGRESS','SUCCEEDED','FAILED')),
  CONSTRAINT MB_LN_IDEMP_CK_JSON CHECK (RESPONSE_JSON IS NULL OR RESPONSE_JSON IS JSON),
  CONSTRAINT MB_LN_IDEMP_CK_COMPLETE CHECK
    ((STATUS = 'IN_PROGRESS' AND COMPLETED_AT IS NULL) OR
     (STATUS IN ('SUCCEEDED','FAILED') AND COMPLETED_AT IS NOT NULL)),
  CONSTRAINT MB_LN_IDEMP_CK_EXPIRY CHECK (EXPIRES_AT > CREATED_AT)
);

CREATE TABLE M08_LOAN_RECONCILIATION_EXCEPTION (
  RECONCILIATION_EXCEPTION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  EXCEPTION_TYPE VARCHAR2(30 CHAR) NOT NULL,
  SOURCE_REFERENCE VARCHAR2(120 CHAR) NOT NULL,
  EXPECTED_AMOUNT NUMBER(18,2),
  OBSERVED_AMOUNT NUMBER(18,2),
  STATUS VARCHAR2(16 CHAR) DEFAULT 'OPEN' NOT NULL,
  OWNER_USER_ID VARCHAR2(36 CHAR),
  DETAIL_TEXT VARCHAR2(2000 CHAR) NOT NULL,
  OPENED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  RESOLVED_AT TIMESTAMP(6) WITH TIME ZONE,
  RESOLUTION_TEXT VARCHAR2(2000 CHAR),
  CONSTRAINT MB_LN_RECON_CK_TYPE CHECK (EXCEPTION_TYPE IN
    ('DISBURSEMENT','REPAYMENT','ACCRUAL','ALLOCATION','FACILITY_BALANCE','SCHEDULE')),
  CONSTRAINT MB_LN_RECON_CK_STATUS CHECK
    (STATUS IN ('OPEN','ASSIGNED','RESOLVED','WAIVED')),
  CONSTRAINT MB_LN_RECON_CK_RESOLVED CHECK
    ((STATUS IN ('RESOLVED','WAIVED') AND RESOLVED_AT IS NOT NULL
      AND RESOLUTION_TEXT IS NOT NULL) OR
     (STATUS IN ('OPEN','ASSIGNED') AND RESOLVED_AT IS NULL))
);
CREATE INDEX M08_LN_RECON_IX_QUEUE
  ON M08_LOAN_RECONCILIATION_EXCEPTION(STATUS, EXCEPTION_TYPE, OPENED_AT);

CREATE TABLE M08_SECURITY_AUDIT_EVENT (
  AUDIT_EVENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  ACTOR_USER_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  CORRELATION_ID VARCHAR2(100 CHAR) NOT NULL,
  ACTION_CODE VARCHAR2(80 CHAR) NOT NULL,
  RESOURCE_TYPE VARCHAR2(40 CHAR) NOT NULL,
  RESOURCE_ID VARCHAR2(100 CHAR),
  RESULT_CODE VARCHAR2(20 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(80 CHAR),
  BEFORE_STATE_HASH CHAR(64),
  AFTER_STATE_HASH CHAR(64),
  MAKER_USER_ID VARCHAR2(36 CHAR),
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  APPROVAL_AUTHORITY_CODE VARCHAR2(80 CHAR),
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_LN_AUDIT_CK_RESULT CHECK
    (RESULT_CODE IN ('SUCCESS','DENIED','FAILED')),
  CONSTRAINT MB_LN_AUDIT_CK_SEPARATION CHECK
    (CHECKER_USER_ID IS NULL OR CHECKER_USER_ID <> MAKER_USER_ID)
);
CREATE INDEX M08_LN_AUDIT_IX_RESOURCE
  ON M08_SECURITY_AUDIT_EVENT(RESOURCE_TYPE, RESOURCE_ID, OCCURRED_AT);

CREATE TABLE M08_OUTBOX_EVENT (
  EVENT_ID RAW(16) PRIMARY KEY,
  EVENT_TYPE VARCHAR2(100 CHAR) NOT NULL,
  SCHEMA_VERSION NUMBER(5) NOT NULL,
  AGGREGATE_TYPE VARCHAR2(30 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(100 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  CAUSATION_ID VARCHAR2(100 CHAR),
  PARTITION_KEY VARCHAR2(100 CHAR) NOT NULL,
  PAYLOAD_JSON CLOB NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  AVAILABLE_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISH_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  PUBLISH_ATTEMPTS NUMBER(10) DEFAULT 0 NOT NULL,
  LOCKED_BY VARCHAR2(100 CHAR),
  LOCKED_UNTIL TIMESTAMP(6) WITH TIME ZONE,
  LAST_ERROR VARCHAR2(1000 CHAR),
  CONSTRAINT MB_LN_OUTBOX_CK_JSON CHECK (PAYLOAD_JSON IS JSON),
  CONSTRAINT MB_LN_OUTBOX_CK_STATUS CHECK
    (PUBLISH_STATUS IN ('PENDING','CLAIMED','PUBLISHED','DEAD_LETTER')),
  CONSTRAINT MB_LN_OUTBOX_CK_PUBLISHED CHECK
    ((PUBLISH_STATUS = 'PUBLISHED' AND PUBLISHED_AT IS NOT NULL) OR
     (PUBLISH_STATUS <> 'PUBLISHED' AND PUBLISHED_AT IS NULL))
);
CREATE INDEX M08_LN_OUTBOX_IX_PENDING
  ON M08_OUTBOX_EVENT(PUBLISH_STATUS, AVAILABLE_AT, LOCKED_UNTIL);

CREATE TABLE M08_CONSUMER_INBOX (
  CONSUMER_NAME VARCHAR2(100 CHAR) NOT NULL,
  EVENT_ID RAW(16) NOT NULL,
  EVENT_TYPE VARCHAR2(100 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE,
  RESULT_CODE VARCHAR2(30 CHAR),
  CONSTRAINT MB_PK_LN_CONSUMER_INBOX PRIMARY KEY (CONSUMER_NAME, EVENT_ID)
);
CREATE INDEX M08_LN_INBOX_IX_PENDING
  ON M08_CONSUMER_INBOX(PROCESSED_AT, RECEIVED_AT);

--------------------------------------------------------------------------------
