CREATE VIEW M05_V_GL_JOURNAL_CONTROL AS
SELECT
    J.JOURNAL_ID,
    J.CURRENCY_CODE,
    COUNT(P.POSTING_ID) AS LINE_COUNT,
    NVL(SUM(CASE WHEN P.ENTRY_SIDE = 'DR' THEN P.AMOUNT ELSE 0 END), 0) AS DEBIT_TOTAL,
    NVL(SUM(CASE WHEN P.ENTRY_SIDE = 'CR' THEN P.AMOUNT ELSE 0 END), 0) AS CREDIT_TOTAL,
    NVL(SUM(CASE WHEN P.ENTRY_SIDE = 'DR' THEN P.AMOUNT ELSE -P.AMOUNT END), 0) AS BALANCE_DIFFERENCE,
    CASE
      WHEN COUNT(P.POSTING_ID) >= 2
       AND NVL(SUM(CASE WHEN P.ENTRY_SIDE = 'DR' THEN P.AMOUNT ELSE -P.AMOUNT END), 0) = 0
      THEN 'Y' ELSE 'N'
    END AS IS_BALANCED
FROM M05_GL_JOURNAL J
LEFT JOIN M05_GL_POSTING P ON P.JOURNAL_ID = J.JOURNAL_ID
GROUP BY J.JOURNAL_ID, J.CURRENCY_CODE;

CREATE VIEW M05_V_ACCOUNT_POSITION_RECON AS
WITH DERIVED AS (
  SELECT
      P.BANK_ACCOUNT_ID,
      P.CURRENCY_CODE,
      SUM(CASE WHEN P.ENTRY_SIDE = 'CR' THEN P.AMOUNT ELSE -P.AMOUNT END) AS GL_DERIVED_BALANCE
  FROM M05_GL_POSTING P
  WHERE P.BANK_ACCOUNT_ID IS NOT NULL
  GROUP BY P.BANK_ACCOUNT_ID, P.CURRENCY_CODE
)
SELECT
    A.BANK_ACCOUNT_ID,
    A.CURRENCY_CODE,
    A.POSTED_BALANCE,
    NVL(D.GL_DERIVED_BALANCE, 0) AS GL_DERIVED_BALANCE,
    A.POSTED_BALANCE - NVL(D.GL_DERIVED_BALANCE, 0) AS DIFFERENCE,
    CASE WHEN A.POSTED_BALANCE = NVL(D.GL_DERIVED_BALANCE, 0) THEN 'Y' ELSE 'N' END AS IS_MATCHED,
    A.AS_OF
FROM M05_ACCOUNT_POSITION A
LEFT JOIN DERIVED D
  ON D.BANK_ACCOUNT_ID = A.BANK_ACCOUNT_ID
 AND D.CURRENCY_CODE = A.CURRENCY_CODE;

CREATE VIEW M05_V_LOAN_RECEIVABLE_POSITION AS
SELECT
    P.LOAN_FACILITY_ID,
    P.LOAN_COMPONENT_CODE,
    P.CURRENCY_CODE,
    SUM(CASE WHEN P.ENTRY_SIDE = 'DR' THEN P.AMOUNT ELSE -P.AMOUNT END) AS RECEIVABLE_BALANCE,
    MAX(J.BOOKED_AT) AS AS_OF
FROM M05_GL_POSTING P
JOIN M05_GL_JOURNAL J ON J.JOURNAL_ID = P.JOURNAL_ID
WHERE P.LOAN_FACILITY_ID IS NOT NULL
GROUP BY P.LOAN_FACILITY_ID, P.LOAN_COMPONENT_CODE, P.CURRENCY_CODE;

CREATE VIEW M08_V_PAYMENT_ALLOCATION_CONTROL AS
SELECT
    P.LOAN_PAYMENT_ID,
    P.FACILITY_ID,
    P.AMOUNT AS PAYMENT_AMOUNT,
    NVL(SUM(A.AMOUNT), 0) AS ALLOCATED_AMOUNT,
    P.AMOUNT - NVL(SUM(A.AMOUNT), 0) AS UNALLOCATED_AMOUNT,
    CASE WHEN P.AMOUNT = NVL(SUM(A.AMOUNT), 0) THEN 'Y' ELSE 'N' END AS IS_FULLY_ALLOCATED
FROM M08_LOAN_PAYMENT P
LEFT JOIN M08_LOAN_PAYMENT_ALLOCATION A
  ON A.LOAN_PAYMENT_ID = P.LOAN_PAYMENT_ID
GROUP BY P.LOAN_PAYMENT_ID, P.FACILITY_ID, P.AMOUNT;

CREATE VIEW M08_V_SCHEDULE_TOTAL_CONTROL AS
SELECT
    S.SCHEDULE_ID,
    S.FACILITY_ID,
    S.TOTAL_PRINCIPAL,
    S.TOTAL_INTEREST,
    S.TOTAL_FEES,
    NVL(SUM(I.PRINCIPAL_DUE), 0) AS ITEM_PRINCIPAL,
    NVL(SUM(I.INTEREST_DUE), 0) AS ITEM_INTEREST,
    NVL(SUM(I.FEE_DUE), 0) AS ITEM_FEES,
    CASE
      WHEN S.TOTAL_PRINCIPAL = NVL(SUM(I.PRINCIPAL_DUE), 0)
       AND S.TOTAL_INTEREST = NVL(SUM(I.INTEREST_DUE), 0)
       AND S.TOTAL_FEES = NVL(SUM(I.FEE_DUE), 0)
      THEN 'Y' ELSE 'N'
    END AS IS_MATCHED
FROM M08_LOAN_SCHEDULE S
LEFT JOIN M08_LOAN_SCHEDULE_ITEM I ON I.SCHEDULE_ID = S.SCHEDULE_ID
GROUP BY S.SCHEDULE_ID, S.FACILITY_ID,
         S.TOTAL_PRINCIPAL, S.TOTAL_INTEREST, S.TOTAL_FEES;

CREATE VIEW M08_V_DISBURSEMENT_CONTROL AS
SELECT
    F.FACILITY_ID,
    F.PRINCIPAL_AMOUNT,
    F.TOTAL_DISBURSED_AMOUNT,
    NVL(SUM(CASE WHEN D.STATUS = 'POSTED' THEN D.AMOUNT ELSE 0 END), 0) AS POSTED_DISBURSEMENTS,
    F.TOTAL_DISBURSED_AMOUNT
      - NVL(SUM(CASE WHEN D.STATUS = 'POSTED' THEN D.AMOUNT ELSE 0 END), 0) AS DIFFERENCE,
    CASE
      WHEN F.TOTAL_DISBURSED_AMOUNT
        = NVL(SUM(CASE WHEN D.STATUS = 'POSTED' THEN D.AMOUNT ELSE 0 END), 0)
      THEN 'Y' ELSE 'N'
    END AS IS_MATCHED
FROM M08_LOAN_FACILITY F
LEFT JOIN M08_LOAN_DISBURSEMENT D ON D.FACILITY_ID = F.FACILITY_ID
GROUP BY F.FACILITY_ID, F.PRINCIPAL_AMOUNT, F.TOTAL_DISBURSED_AMOUNT;

CREATE VIEW M07_V_RESERVE_POSITION_RECON AS
WITH DERIVED AS (
  SELECT
      RESERVE_ACCOUNT_ID,
      CURRENCY_CODE,
      SUM(CASE WHEN MOVEMENT_SIDE = 'IN' THEN AMOUNT ELSE -AMOUNT END) AS LEDGER_BALANCE
  FROM M07_CENTRAL_TREASURY_LEDGER
  GROUP BY RESERVE_ACCOUNT_ID, CURRENCY_CODE
)
SELECT
    P.RESERVE_ACCOUNT_ID,
    P.CURRENCY_CODE,
    P.CONFIRMED_BALANCE,
    NVL(D.LEDGER_BALANCE, 0) AS LEDGER_BALANCE,
    P.CONFIRMED_BALANCE - NVL(D.LEDGER_BALANCE, 0) AS DIFFERENCE,
    CASE WHEN P.CONFIRMED_BALANCE = NVL(D.LEDGER_BALANCE, 0) THEN 'Y' ELSE 'N' END AS IS_MATCHED,
    P.AS_OF
FROM M07_RESERVE_POSITION P
LEFT JOIN DERIVED D
  ON D.RESERVE_ACCOUNT_ID = P.RESERVE_ACCOUNT_ID
 AND D.CURRENCY_CODE = P.CURRENCY_CODE;

-- Deployment privilege boundary (replace role names with environment-specific
-- roles and execute after creating the definer-rights posting package):
--   REVOKE INSERT, UPDATE, DELETE ON MB_TXN.GL_JOURNAL FROM <txn_app_role>;
--   REVOKE INSERT, UPDATE, DELETE ON MB_TXN.GL_POSTING FROM <txn_app_role>;
--   GRANT EXECUTE ON MB_TXN.<posting_api_package> TO <txn_app_role>;
--   GRANT EXECUTE ON MB_TXN.<posting_api_package> TO <loan_app_role>;
--   GRANT SELECT ON MB_TXN.V_LOAN_RECEIVABLE_POSITION TO <loan_app_role>;
-- The posting API must lock ACCOUNT_POSITION and POSTING_FENCE rows in ascending
-- account ID order; validate account controls, funds, product/account limits, and
-- idempotency; insert at least two same-currency lines; prove total DR = total CR;
-- update positions and holds; append status history; and write OUTBOX_EVENT before
-- one commit. The views above are independent reconciliation controls, not posting
-- authorization. Seed an initial verified reserve movement before comparing a
-- non-zero opening reserve position with V_RESERVE_POSITION_RECON.

-- Cross-module contract for Modules 1-8:
-- * IAM authorizes the caller and scope at decision time. CIF/KYC supplies current
--   customer and beneficiary eligibility. Product Master supplies the adopted,
--   immutable product version and transaction rules. Stored references do not
--   confer authority and are never validated by cross-schema joins.
-- * Account Management owns account lifecycle and restrictions. It increments
--   FINANCIAL_CONTROL_VERSION and publishes each control change. Module 5 applies
--   versions in order under the account-position/fence lock and acknowledges them.
--   Apply is effective only after the fence closes; removal is effective only
--   after the fence or financial block is released.
-- * Module 5 owns financial holds, customer-facing positions, double-entry
--   journals, and posting lines. Every posting, position update, hold transition,
--   status-history row, and outbox event commits atomically. A committed journal
--   is never updated or deleted; a reversal is a separately linked journal.
-- * Account Management financial columns and ACCOUNT_FINANCIAL_PROJECTION_EVENT
--   are event-fed read models. They can be displayed with BALANCE_AS_OF but cannot
--   approve a debit. Closure requires a fresh Module 5 clearance confirming zero
--   position, no active holds, and no unresolved payment exposure.
-- * Module 6 owns payment intent and the long-running rail state machine. A timeout
--   becomes UNKNOWN, not failure. Dispatch/inquiry reuse one stable rail message
--   ID. Explicit pre-settlement rejection is refunded by a new Module 5 journal;
--   a post-settlement return is a new linked payment.
-- * Treasury owns liquidity holds and the append-only local reserve mirror. Module
--   6 requests an earmark before dispatch; Module 5 posts the reserve journal only
--   against confirmed settlement evidence; all three services reconcile by opaque
--   IDs and stable external references without cross-schema foreign keys.
-- * Module 8 owns loan applications, immutable submitted revisions, assessments,
--   approval evidence, offers, facilities, schedules, allocations, and servicing
--   state. A facility is not a BANK_ACCOUNT and never stores the authoritative
--   general-ledger balance. Its financial columns are event-fed projections.
-- * A loan pins one approved LOAN product version and RULE_SET_HASH. Product Master
--   supplies loan limits and pricing policy; approved customer terms are copied to
--   the decision/facility so later product changes cannot rewrite the contract.
-- * CIF/KYC validates every borrower, co-borrower, guarantor, and collateral owner.
--   IAM validates current product, branch, risk, and amount authority. Stored
--   approval authority is evidence only. Maker and checker must remain distinct.
-- * Account Management validates the customer-owned disbursement and repayment
--   accounts immediately before use. Loan Service references those account IDs but
--   does not create deposit accounts or authorize debits from projected balances.
--   A repayment account link is not debit authority; automated collection also
--   requires a current customer mandate and the normal Module 5/6 controls.
-- * Loan disbursement, repayment, accrual, waiver, settlement, and write-off use
--   idempotent Module 5 transactions. Only a confirmed Module 5 posting event may
--   activate a facility or alter its financial projection. Principal, interest,
--   fee, penalty, suspense, and write-off posting lines carry the facility ID and
--   component code for subledger reconciliation.
-- * Repayments are allocated only after confirmed posting. Partial payments,
--   unapplied funds, prepayments, reversals, rate resets, moratoria, restructuring,
--   settlement, and write-off preserve the old schedule and evidence rather than
--   overwriting history. Closure requires current ledger clearance and no pending
--   disbursement, accrual, allocation, or servicing exception.
-- * Each producer writes an outbox row in its local transaction. Each consumer
--   inserts (consumer name, event ID) in its inbox in the same transaction as its
--   effect. API idempotency, Kafka event deduplication, and rail-message uniqueness
--   are independent controls and must all be preserved.

-- Privacy, Consent, Audit and Compliance (module 9).
-- MB_PRIVACY owns shared policy, decision history, rights cases, retention,
-- legal holds, and consolidated evidence. The existing CIF_KYC.CIF_CONSENT
-- remains the operational customer consent record; it is not duplicated.
-- Purpose/notice versions and all consent decisions are retained here as
-- append-only history. CIF_KYC projects applicable grant/withdrawal state
-- from those decisions through its existing inbox and outbox contracts.
-- Its added privacy decision pointer prevents an old or redelivered event
-- from replacing a newer decision. Existing CIF consent columns are retained.
-- Source-service identifiers are opaque API/event references. In particular,
-- resource IDs are text because Modules 1-4 use UUIDs and Modules 5-8 also
-- use numeric IDs. They are never cross-schema foreign keys.

CREATE TABLE M09_PRIVACY_PROCESSING_PURPOSE (
  PROCESSING_PURPOSE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PURPOSE_CODE VARCHAR2(80 CHAR) NOT NULL,
  PURPOSE_VERSION NUMBER(10) NOT NULL,
  PURPOSE_NAME VARCHAR2(200 CHAR) NOT NULL,
  OWNER_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  LEGAL_BASIS_CODE VARCHAR2(40 CHAR) NOT NULL,
  NOTICE_URI VARCHAR2(1000 CHAR),
  NOTICE_SHA256 CHAR(64),
  STATUS VARCHAR2(20 CHAR) NOT NULL,
  EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_TO TIMESTAMP(6) WITH TIME ZONE,
  REVIEW_DUE_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_BY VARCHAR2(36 CHAR),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_PURPOSE_UQ_CODE_VER UNIQUE (PURPOSE_CODE, PURPOSE_VERSION),
  CONSTRAINT MB_PRIV_PURPOSE_CK_DATES CHECK
    (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM),
  CONSTRAINT MB_PRIV_PURPOSE_CK_VER CHECK (PURPOSE_VERSION > 0 AND VERSION_NO > 0),
  CONSTRAINT MB_PRIV_PURPOSE_CK_SOD CHECK
    (APPROVED_BY IS NULL OR APPROVED_BY <> CREATED_BY),
  CONSTRAINT MB_PRIV_PURPOSE_CK_ACTIVE CHECK
    (STATUS <> 'ACTIVE' OR (APPROVED_AT IS NOT NULL AND APPROVED_BY IS NOT NULL))
);

-- One row per decision, including denial, withdrawal, expiry, and supersession.
-- A SOURCE_CONSENT_ID links to the existing CIF record when one exists; a
-- denied decision need not create a CIF consent row. Current optional-processing
-- eligibility comes from the latest effective decision for the exact purpose
-- version and the purpose's active status, never from a historical grant alone.
-- DECISION_NO orders decisions within one subject and purpose version, including
-- events that arrive out of order at CIF_KYC.
CREATE TABLE M09_PRIVACY_CONSENT_HISTORY (
  CONSENT_DECISION_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PROCESSING_PURPOSE_ID VARCHAR2(36 CHAR) NOT NULL
    REFERENCES M09_PRIVACY_PROCESSING_PURPOSE(PROCESSING_PURPOSE_ID),
  SUBJECT_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  SUBJECT_EXTERNAL_ID VARCHAR2(100 CHAR) NOT NULL,
  SOURCE_CONSENT_ID VARCHAR2(36 CHAR),
  DECISION_NO NUMBER(19) NOT NULL,
  DECISION VARCHAR2(20 CHAR) NOT NULL,
  CHANNEL_CODE VARCHAR2(50 CHAR) NOT NULL,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE,
  ACTOR_EXTERNAL_ID VARCHAR2(36 CHAR),
  AUTH_STRENGTH_CODE VARCHAR2(40 CHAR),
  NOTICE_SHA256 CHAR(64),
  EVIDENCE_URI VARCHAR2(1000 CHAR),
  EVIDENCE_SHA256 CHAR(64),
  CORRELATION_ID VARCHAR2(100 CHAR) NOT NULL,
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_PRIV_CONSENT_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_CONSENT_UQ_ORDER UNIQUE
    (SUBJECT_SERVICE, SUBJECT_EXTERNAL_ID, PROCESSING_PURPOSE_ID, DECISION_NO),
  CONSTRAINT MB_PRIV_CONSENT_CK_DECISION CHECK
    (DECISION IN ('GRANTED','DENIED','WITHDRAWN','EXPIRED','SUPERSEDED')),
  CONSTRAINT MB_PRIV_CONSENT_CK_DATES CHECK
    (EXPIRES_AT IS NULL OR EXPIRES_AT > EFFECTIVE_AT),
  CONSTRAINT MB_PRIV_CONSENT_CK_ORDER CHECK (DECISION_NO > 0),
  CONSTRAINT MB_PRIV_CONSENT_CK_ACTOR CHECK
    (DECISION NOT IN ('GRANTED','DENIED','WITHDRAWN') OR
     (ACTOR_EXTERNAL_ID IS NOT NULL AND AUTH_STRENGTH_CODE IS NOT NULL)),
  CONSTRAINT MB_PRIV_CONSENT_CK_NOTICE CHECK
    (DECISION NOT IN ('GRANTED','DENIED') OR NOTICE_SHA256 IS NOT NULL)
);
CREATE INDEX M09_PRIV_CONSENT_IX_SUBJECT
  ON M09_PRIVACY_CONSENT_HISTORY
    (SUBJECT_SERVICE, SUBJECT_EXTERNAL_ID, PROCESSING_PURPOSE_ID, EFFECTIVE_AT);
CREATE INDEX M09_PRIV_CONSENT_IX_CIF
  ON M09_PRIVACY_CONSENT_HISTORY(SOURCE_CONSENT_ID);

-- CIF_KYC.CIF_CONSENT remains the existing operational record. These nullable
-- additions support legacy rows and record the last applied privacy decision.
-- The privacy service remains authoritative for current optional processing.
ALTER TABLE M02_CIF_CONSENT ADD (
  PRIVACY_PURPOSE_ID VARCHAR2(36 CHAR),
  PRIVACY_DECISION_ID VARCHAR2(36 CHAR),
  PRIVACY_DECISION_NO NUMBER(19)
);
ALTER TABLE M02_CIF_CONSENT ADD CONSTRAINT MB_CIF_CONSENT_CK_PRIV_PTR CHECK
  ((PRIVACY_PURPOSE_ID IS NULL AND PRIVACY_DECISION_ID IS NULL
    AND PRIVACY_DECISION_NO IS NULL) OR
   (PRIVACY_PURPOSE_ID IS NOT NULL AND PRIVACY_DECISION_ID IS NOT NULL
    AND PRIVACY_DECISION_NO IS NOT NULL AND PRIVACY_DECISION_NO > 0));

CREATE TABLE M09_PRIVACY_DATA_ASSET (
  DATA_ASSET_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  OWNING_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  ASSET_CODE VARCHAR2(160 CHAR) NOT NULL,
  ASSET_TYPE VARCHAR2(40 CHAR) NOT NULL,
  LOCATION_REF VARCHAR2(240 CHAR),
  STATUS VARCHAR2(20 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_ASSET_UQ_OWNER_CODE UNIQUE (OWNING_SERVICE, ASSET_CODE),
  CONSTRAINT MB_PRIV_ASSET_CK_VERSION CHECK (VERSION_NO > 0)
);

-- Field policy refers to the approved record-category retention schedule below.
CREATE TABLE M09_PRIVACY_DATA_CONTROL (
  DATA_CONTROL_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  DATA_ASSET_ID VARCHAR2(36 CHAR) NOT NULL
    REFERENCES M09_PRIVACY_DATA_ASSET(DATA_ASSET_ID),
  FIELD_NAME VARCHAR2(200 CHAR) NOT NULL,
  DATA_CATEGORY VARCHAR2(80 CHAR) NOT NULL,
  SENSITIVITY_LEVEL VARCHAR2(20 CHAR) NOT NULL,
  IS_DIRECT_IDENTIFIER CHAR(1) NOT NULL,
  ENCRYPTION_REQUIRED CHAR(1) NOT NULL,
  MASKING_METHOD VARCHAR2(30 CHAR) NOT NULL,
  LOG_ALLOWED CHAR(1) NOT NULL,
  NON_PROD_ALLOWED CHAR(1) NOT NULL,
  RETENTION_SCHEDULE_ID VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  APPROVED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_CONTROL_UQ_ASSET_FIELD UNIQUE (DATA_ASSET_ID, FIELD_NAME),
  CONSTRAINT MB_PRIV_CONTROL_CK_LEVEL CHECK
    (SENSITIVITY_LEVEL IN ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED')),
  CONSTRAINT MB_PRIV_CONTROL_CK_FLAGS CHECK
    (IS_DIRECT_IDENTIFIER IN ('Y','N') AND ENCRYPTION_REQUIRED IN ('Y','N')
     AND LOG_ALLOWED IN ('Y','N') AND NON_PROD_ALLOWED IN ('Y','N')),
  CONSTRAINT MB_PRIV_CONTROL_CK_VERSION CHECK (VERSION_NO > 0),
  CONSTRAINT MB_PRIV_CONTROL_CK_SOD CHECK (APPROVED_BY <> CREATED_BY)
);

-- Rights access/correction cases, retention actions, and compliance reviews
-- share one routed case and task workflow. Owning services perform changes.
CREATE TABLE M09_PRIVACY_COMPLIANCE_CASE (
  COMPLIANCE_CASE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  CASE_REFERENCE VARCHAR2(100 CHAR) NOT NULL,
  CASE_TYPE VARCHAR2(40 CHAR) NOT NULL,
  CASE_STATUS VARCHAR2(20 CHAR) NOT NULL,
  PRIORITY VARCHAR2(20 CHAR) NOT NULL,
  REQUESTER_SERVICE VARCHAR2(120 CHAR),
  REQUESTER_EXTERNAL_ID VARCHAR2(100 CHAR),
  REQUESTER_AUTHORITY_REF VARCHAR2(200 CHAR),
  SUBJECT_SERVICE VARCHAR2(120 CHAR),
  SUBJECT_EXTERNAL_ID VARCHAR2(100 CHAR),
  PROCESSING_PURPOSE_ID VARCHAR2(36 CHAR)
    REFERENCES M09_PRIVACY_PROCESSING_PURPOSE(PROCESSING_PURPOSE_ID),
  TARGET_SERVICE VARCHAR2(120 CHAR),
  TARGET_RESOURCE_TYPE VARCHAR2(80 CHAR),
  TARGET_EXTERNAL_ID VARCHAR2(100 CHAR),
  REASON CLOB,
  IDENTITY_VERIFIED_AT TIMESTAMP(6) WITH TIME ZONE,
  REVIEWED_AT TIMESTAMP(6) WITH TIME ZONE,
  REVIEWED_BY VARCHAR2(36 CHAR),
  DUE_AT TIMESTAMP(6) WITH TIME ZONE,
  RESPONSE_DELIVERED_AT TIMESTAMP(6) WITH TIME ZONE,
  CLOSED_AT TIMESTAMP(6) WITH TIME ZONE,
  EVIDENCE_URI VARCHAR2(1000 CHAR),
  EVIDENCE_SHA256 CHAR(64),
  CORRELATION_ID VARCHAR2(100 CHAR),
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_CASE_UQ_REF UNIQUE (CASE_REFERENCE),
  CONSTRAINT MB_PRIV_CASE_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_CASE_CK_VERSION CHECK (VERSION_NO > 0)
);
CREATE INDEX M09_PRIV_CASE_IX_SUBJECT
  ON M09_PRIVACY_COMPLIANCE_CASE
    (SUBJECT_SERVICE, SUBJECT_EXTERNAL_ID, CASE_STATUS);

CREATE TABLE M09_PRIVACY_COMPLIANCE_CASE_TASK (
  CASE_TASK_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  COMPLIANCE_CASE_ID VARCHAR2(36 CHAR) NOT NULL
    REFERENCES M09_PRIVACY_COMPLIANCE_CASE(COMPLIANCE_CASE_ID),
  TARGET_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  ACTION_CODE VARCHAR2(40 CHAR) NOT NULL,
  TASK_STATUS VARCHAR2(20 CHAR) NOT NULL,
  TARGET_RESOURCE_TYPE VARCHAR2(80 CHAR),
  TARGET_EXTERNAL_ID VARCHAR2(100 CHAR),
  RESPONSE_REFERENCE VARCHAR2(200 CHAR),
  FAILURE_REASON CLOB,
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_TASK_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_TASK_CK_VERSION CHECK (VERSION_NO > 0)
);
CREATE INDEX M09_PRIV_TASK_IX_CASE
  ON M09_PRIVACY_COMPLIANCE_CASE_TASK(COMPLIANCE_CASE_ID, TASK_STATUS);

-- Record-category policy covers non-field records such as journals, consent
-- history, security events, and support evidence. Legal/compliance approvals
-- set bank-specific periods; the schema does not prescribe any period.
CREATE TABLE M09_PRIVACY_RETENTION_SCHEDULE (
  RETENTION_SCHEDULE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  OWNING_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  RECORD_CATEGORY VARCHAR2(100 CHAR) NOT NULL,
  POLICY_VERSION NUMBER(10) NOT NULL,
  RETENTION_START_EVENT VARCHAR2(80 CHAR) NOT NULL,
  RETENTION_MONTHS NUMBER(5) NOT NULL,
  DISPOSAL_ACTION VARCHAR2(20 CHAR) NOT NULL,
  STATUS VARCHAR2(20 CHAR) NOT NULL,
  EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_TO TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_BY VARCHAR2(36 CHAR) NOT NULL,
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_PRIV_RET_UQ_CATEGORY_VER UNIQUE
    (OWNING_SERVICE, RECORD_CATEGORY, POLICY_VERSION),
  CONSTRAINT MB_PRIV_RET_CK_PERIOD CHECK
    (RETENTION_MONTHS >= 0 AND POLICY_VERSION > 0),
  CONSTRAINT MB_PRIV_RET_CK_DATES CHECK
    (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM),
  CONSTRAINT MB_PRIV_RET_CK_SOD CHECK (APPROVED_BY <> CREATED_BY)
);

ALTER TABLE M09_PRIVACY_DATA_CONTROL ADD CONSTRAINT MB_PRIV_CONTROL_FK_RET
  FOREIGN KEY (RETENTION_SCHEDULE_ID)
  REFERENCES M09_PRIVACY_RETENTION_SCHEDULE(RETENTION_SCHEDULE_ID);

-- A hold may target a subject, resource, category, time range, or their
-- intersection. Its scope is interpreted by the record-owning service before
-- any disposition. Release is separately authorized and retained as evidence.
CREATE TABLE M09_PRIVACY_LEGAL_HOLD (
  LEGAL_HOLD_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  HOLD_REFERENCE VARCHAR2(100 CHAR) NOT NULL,
  HOLD_STATUS VARCHAR2(20 CHAR) NOT NULL,
  AUTHORITY_REFERENCE VARCHAR2(200 CHAR) NOT NULL,
  REASON CLOB NOT NULL,
  SUBJECT_SERVICE VARCHAR2(120 CHAR),
  SUBJECT_EXTERNAL_ID VARCHAR2(100 CHAR),
  TARGET_SERVICE VARCHAR2(120 CHAR),
  TARGET_RESOURCE_TYPE VARCHAR2(80 CHAR),
  TARGET_EXTERNAL_ID VARCHAR2(100 CHAR),
  RECORD_CATEGORY VARCHAR2(100 CHAR),
  RECORD_FROM_AT TIMESTAMP(6) WITH TIME ZONE,
  RECORD_TO_AT TIMESTAMP(6) WITH TIME ZONE,
  STARTED_AT TIMESTAMP(6) WITH TIME ZONE,
  REVIEW_DUE_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  RELEASED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  APPROVED_BY VARCHAR2(36 CHAR),
  RELEASED_BY VARCHAR2(36 CHAR),
  RELEASE_APPROVED_BY VARCHAR2(36 CHAR),
  RELEASE_AUTHORITY_REF VARCHAR2(200 CHAR),
  CORRELATION_ID VARCHAR2(100 CHAR),
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CONSTRAINT MB_PRIV_HOLD_UQ_REF UNIQUE (HOLD_REFERENCE),
  CONSTRAINT MB_PRIV_HOLD_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_HOLD_CK_STATUS CHECK
    (HOLD_STATUS IN ('PENDING','ACTIVE','REJECTED','RELEASED')),
  CONSTRAINT MB_PRIV_HOLD_CK_SCOPE CHECK
    (SUBJECT_EXTERNAL_ID IS NOT NULL OR TARGET_EXTERNAL_ID IS NOT NULL
     OR RECORD_CATEGORY IS NOT NULL),
  CONSTRAINT MB_PRIV_HOLD_CK_REFS CHECK
    ((SUBJECT_EXTERNAL_ID IS NULL OR SUBJECT_SERVICE IS NOT NULL)
     AND (TARGET_EXTERNAL_ID IS NULL OR
          (TARGET_SERVICE IS NOT NULL AND TARGET_RESOURCE_TYPE IS NOT NULL))),
  CONSTRAINT MB_PRIV_HOLD_CK_RANGE CHECK
    (RECORD_TO_AT IS NULL OR RECORD_FROM_AT IS NULL
     OR RECORD_TO_AT >= RECORD_FROM_AT),
  CONSTRAINT MB_PRIV_HOLD_CK_TIMES CHECK
    ((HOLD_STATUS <> 'ACTIVE' OR STARTED_AT IS NOT NULL)
     AND (HOLD_STATUS <> 'RELEASED' OR
          (STARTED_AT IS NOT NULL AND RELEASED_AT IS NOT NULL
           AND RELEASED_BY IS NOT NULL AND RELEASE_AUTHORITY_REF IS NOT NULL))),
  CONSTRAINT MB_PRIV_HOLD_CK_SOD CHECK
    ((APPROVED_BY IS NULL OR APPROVED_BY <> CREATED_BY)
     AND (RELEASE_APPROVED_BY IS NULL OR RELEASE_APPROVED_BY <> RELEASED_BY))
);
CREATE INDEX M09_PRIV_HOLD_IX_SUBJECT
  ON M09_PRIVACY_LEGAL_HOLD
    (SUBJECT_SERVICE, SUBJECT_EXTERNAL_ID, HOLD_STATUS);
CREATE INDEX M09_PRIV_HOLD_IX_TARGET
  ON M09_PRIVACY_LEGAL_HOLD
    (TARGET_SERVICE, TARGET_RESOURCE_TYPE, TARGET_EXTERNAL_ID, HOLD_STATUS);

-- The immutable audit platform retains source audit tables unchanged. Text
-- source IDs accommodate both UUID and NUMBER(19) source audit keys. A source
-- stream distinguishes numeric keys reused by different source tables. Metadata
-- must be allowlisted and must not contain secrets or unmasked personal data.
-- Case and consent IDs are historical references without foreign keys, so
-- separately approved retention/disposition cannot orphan or block evidence.
CREATE TABLE M09_PRIVACY_AUDIT_EVENT (
  AUDIT_EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  SOURCE_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  SOURCE_STREAM VARCHAR2(80 CHAR) NOT NULL,
  SOURCE_EVENT_ID VARCHAR2(100 CHAR) NOT NULL,
  EVENT_TYPE VARCHAR2(120 CHAR) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  OUTCOME VARCHAR2(20 CHAR) NOT NULL,
  ACTOR_EXTERNAL_ID VARCHAR2(36 CHAR),
  SESSION_EXTERNAL_ID VARCHAR2(36 CHAR),
  ACTOR_ROLE_CODE VARCHAR2(80 CHAR),
  ACTOR_SCOPE_REF VARCHAR2(160 CHAR),
  PURPOSE_CODE VARCHAR2(80 CHAR),
  SUBJECT_EXTERNAL_ID VARCHAR2(100 CHAR),
  RESOURCE_TYPE VARCHAR2(80 CHAR),
  RESOURCE_EXTERNAL_ID VARCHAR2(100 CHAR),
  DATA_CLASSIFICATION VARCHAR2(20 CHAR),
  COMPLIANCE_CASE_ID VARCHAR2(36 CHAR),
  CONSENT_DECISION_ID VARCHAR2(36 CHAR),
  CORRELATION_ID VARCHAR2(100 CHAR),
  REASON_CODE VARCHAR2(80 CHAR),
  EVENT_METADATA CLOB NOT NULL,
  EVENT_SHA256 CHAR(64) NOT NULL,
  RETENTION_UNTIL TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_PRIV_AUDIT_UQ_SOURCE UNIQUE
    (SOURCE_SERVICE, SOURCE_STREAM, SOURCE_EVENT_ID),
  CONSTRAINT MB_PRIV_AUDIT_CK_JSON CHECK (EVENT_METADATA IS JSON)
);
CREATE INDEX M09_PRIV_AUDIT_IX_RESOURCE
  ON M09_PRIVACY_AUDIT_EVENT
    (RESOURCE_TYPE, RESOURCE_EXTERNAL_ID, OCCURRED_AT);
CREATE INDEX M09_PRIV_AUDIT_IX_ACTOR
  ON M09_PRIVACY_AUDIT_EVENT(ACTOR_EXTERNAL_ID, OCCURRED_AT);
CREATE INDEX M09_PRIV_AUDIT_IX_CASE
  ON M09_PRIVACY_AUDIT_EVENT(COMPLIANCE_CASE_ID, OCCURRED_AT);

-- An approved export references a manifest rather than copying business data
-- into the privacy database. Every download is a PRIVACY_AUDIT_EVENT. Its case
-- ID remains historical evidence even if the case is later disposed.
CREATE TABLE M09_PRIVACY_EVIDENCE_EXPORT (
  EVIDENCE_EXPORT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  COMPLIANCE_CASE_ID VARCHAR2(36 CHAR),
  EXPORT_REFERENCE VARCHAR2(100 CHAR) NOT NULL,
  EXPORT_STATUS VARCHAR2(20 CHAR) NOT NULL,
  REQUEST_REASON VARCHAR2(500 CHAR) NOT NULL,
  MANIFEST_URI VARCHAR2(1000 CHAR),
  MANIFEST_SHA256 CHAR(64),
  PACKAGE_URI VARCHAR2(1000 CHAR),
  PACKAGE_SHA256 CHAR(64),
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  REQUESTED_BY VARCHAR2(36 CHAR) NOT NULL,
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE,
  APPROVED_BY VARCHAR2(36 CHAR),
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE,
  CORRELATION_ID VARCHAR2(100 CHAR),
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CONSTRAINT MB_PRIV_EXPORT_UQ_REF UNIQUE (EXPORT_REFERENCE),
  CONSTRAINT MB_PRIV_EXPORT_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_EXPORT_CK_SOD CHECK
    (APPROVED_BY IS NULL OR APPROVED_BY <> REQUESTED_BY),
  CONSTRAINT MB_PRIV_EXPORT_CK_COMPLETE CHECK
    (EXPORT_STATUS <> 'COMPLETED' OR
     (APPROVED_AT IS NOT NULL AND APPROVED_BY IS NOT NULL
      AND MANIFEST_URI IS NOT NULL AND MANIFEST_SHA256 IS NOT NULL
      AND PACKAGE_URI IS NOT NULL AND PACKAGE_SHA256 IS NOT NULL
      AND COMPLETED_AT IS NOT NULL))
);

CREATE TABLE M09_PRIVACY_OUTBOX_EVENT (
  OUTBOX_EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  AGGREGATE_TYPE VARCHAR2(40 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(100 CHAR) NOT NULL,
  EVENT_TYPE VARCHAR2(120 CHAR) NOT NULL,
  EVENT_VERSION NUMBER(10) NOT NULL,
  EVENT_PAYLOAD CLOB NOT NULL,
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  ATTEMPT_COUNT NUMBER(10) DEFAULT 0 NOT NULL,
  LAST_ERROR VARCHAR2(1000 CHAR),
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPDATED_BY VARCHAR2(36 CHAR),
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_PRIV_OUTBOX_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_PRIV_OUTBOX_CK_JSON CHECK (EVENT_PAYLOAD IS JSON),
  CONSTRAINT MB_PRIV_OUTBOX_CK_NUMBERS CHECK
    (ATTEMPT_COUNT >= 0 AND EVENT_VERSION > 0 AND VERSION_NO > 0)
);
CREATE INDEX M09_PRIV_OUTBOX_IX_PENDING
  ON M09_PRIVACY_OUTBOX_EVENT(PUBLISHED_AT, CREATED_AT);

CREATE TABLE M09_PRIVACY_INBOX_EVENT (
  EVENT_ID VARCHAR2(100 CHAR) NOT NULL,
  SOURCE_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  EVENT_TYPE VARCHAR2(120 CHAR) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_PRIV_INBOX_PK PRIMARY KEY (SOURCE_SERVICE, EVENT_ID)
);
CREATE INDEX M09_PRIV_INBOX_IX_PENDING
  ON M09_PRIVACY_INBOX_EVENT(PROCESSED_AT, RECEIVED_AT);

CREATE OR REPLACE TRIGGER M09_TRG_PRIV_PURPOSE_VERSION
BEFORE UPDATE OR DELETE ON M09_PRIVACY_PROCESSING_PURPOSE
FOR EACH ROW
BEGIN
  IF :OLD.APPROVED_AT IS NOT NULL THEN
    IF DELETING THEN
      RAISE_APPLICATION_ERROR(-20040, 'Approved purpose versions cannot be deleted.');
    ELSIF :NEW.PURPOSE_CODE <> :OLD.PURPOSE_CODE
       OR :NEW.PURPOSE_VERSION <> :OLD.PURPOSE_VERSION
       OR :NEW.PURPOSE_NAME <> :OLD.PURPOSE_NAME
       OR :NEW.OWNER_SERVICE <> :OLD.OWNER_SERVICE
       OR :NEW.LEGAL_BASIS_CODE <> :OLD.LEGAL_BASIS_CODE
       OR (:NEW.NOTICE_URI <> :OLD.NOTICE_URI OR (:NEW.NOTICE_URI IS NULL AND :OLD.NOTICE_URI IS NOT NULL) OR (:NEW.NOTICE_URI IS NOT NULL AND :OLD.NOTICE_URI IS NULL))
       OR (:NEW.NOTICE_SHA256 <> :OLD.NOTICE_SHA256 OR (:NEW.NOTICE_SHA256 IS NULL AND :OLD.NOTICE_SHA256 IS NOT NULL) OR (:NEW.NOTICE_SHA256 IS NOT NULL AND :OLD.NOTICE_SHA256 IS NULL))
       OR :NEW.EFFECTIVE_FROM <> :OLD.EFFECTIVE_FROM
       OR :NEW.APPROVED_AT IS NULL
       OR :NEW.APPROVED_AT <> :OLD.APPROVED_AT
       OR :NEW.APPROVED_BY IS NULL
       OR :NEW.APPROVED_BY <> :OLD.APPROVED_BY
       OR :NEW.CREATED_AT <> :OLD.CREATED_AT
       OR :NEW.CREATED_BY <> :OLD.CREATED_BY THEN
      RAISE_APPLICATION_ERROR(-20040, 'Approved purpose content requires a new version.');
    END IF;
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M09_TRG_PRIV_RETENTION_VERSION
BEFORE UPDATE OR DELETE ON M09_PRIVACY_RETENTION_SCHEDULE
FOR EACH ROW
BEGIN
  IF DELETING THEN
    RAISE_APPLICATION_ERROR(-20041, 'Approved retention schedules cannot be deleted.');
  ELSIF :NEW.OWNING_SERVICE <> :OLD.OWNING_SERVICE
     OR :NEW.RECORD_CATEGORY <> :OLD.RECORD_CATEGORY
     OR :NEW.POLICY_VERSION <> :OLD.POLICY_VERSION
     OR :NEW.RETENTION_START_EVENT <> :OLD.RETENTION_START_EVENT
     OR :NEW.RETENTION_MONTHS <> :OLD.RETENTION_MONTHS
     OR :NEW.DISPOSAL_ACTION <> :OLD.DISPOSAL_ACTION
     OR :NEW.EFFECTIVE_FROM <> :OLD.EFFECTIVE_FROM
     OR :NEW.APPROVED_BY <> :OLD.APPROVED_BY
     OR :NEW.APPROVED_AT <> :OLD.APPROVED_AT
     OR :NEW.CREATED_BY <> :OLD.CREATED_BY
     OR :NEW.CREATED_AT <> :OLD.CREATED_AT THEN
    RAISE_APPLICATION_ERROR(-20041, 'Retention rule changes require a new version.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M09_TRG_PRIV_CONSENT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M09_PRIVACY_CONSENT_HISTORY
BEGIN
  RAISE_APPLICATION_ERROR(-20038, 'Privacy consent decisions are append-only.');
END;
/

CREATE OR REPLACE TRIGGER M09_TRG_PRIV_AUDIT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M09_PRIVACY_AUDIT_EVENT
BEGIN
  RAISE_APPLICATION_ERROR(-20039, 'Privacy audit events are append-only.');
END;
/

-- Module 9 integration contract:
-- * IAM supplies identity, session, role, and scope at decision time. Privacy
--   records historical actor references only; no stored ID confers authority.
--   IAM permissions distinguish consent capture, policy approval, rights-case
--   work, hold approval/release, sensitive audit search, and evidence export.
-- * CIF_KYC.CIF_CONSENT is retained. Privacy decision history links it by ID
--   when applicable. CIF applies only decisions newer than its stored decision
--   number for that purpose version, after inbox deduplication. Denials and
--   expired/superseded decisions need not create a CIF consent row. Optional
--   withdrawal blocks future optional use; required banking records remain.
--   Approved purpose content is immutable; a new notice/legal basis is a new
--   approved version. Each consent decision snapshots the notice digest.
-- * Account opening uses CIF/KYC eligibility and the exact approved product
--   version. Product-version treatment requiring consent checks a current
--   applicable privacy decision and preserves its decision ID in the existing
--   ACCOUNT_PRODUCT_VERSION_HISTORY.CONSENT_REFERENCE. A marketing withdrawal
--   never cancels an account, payment, loan, or required service message.
-- * IAM_CUSTOMER_LINK is an identity link, not a transaction-data entitlement.
--   Customer detail reads also check the active ACCOUNT_PARTY role/instruction
--   and account scope; joint holders, nominees, guardians, and signatories have
--   different rights. A customer hash alone does not authorize amount access.
--   Transaction, payment, and loan APIs return only allowed fields, mask third-
--   party data, and emit sensitive-read audit events with actor and purpose.
-- * Loan-party CONSENT_STATUS and repayment-mandate CUSTOMER_CONSENT_REF are
--   workflow/mandate evidence, not generic optional marketing permission.
--   Privacy purposes are checked only where applicable to those flows.
-- * Data owners classify and mask their own fields according to shared policy.
--   The privacy service holds no copied CIF, account, payment, or loan data.
-- * Rights/correction case tasks route to the owning service. The owner checks
--   requester identity and representative authority before fan-out. Each owner
--   checks entitlement, third-party exposure, and approval before changing its
--   record; before/after evidence remains in its existing audit history.
-- * Purge/disposition checks active legal holds against subject, resource,
--   category, and time range, including linked account/payment/loan records.
--   Held records are skipped and the skip is audited. If current hold status
--   cannot be confirmed, destructive disposition is deferred. A hold release
--   is effective for a domain only after that domain has received it or made
--   a fresh authoritative check; delayed events must not lift a newer hold.
--   Retention rule content is immutable after approval; rule changes create a
--   new version, and the old version remains available for evidence.
-- * Domain audit tables remain in place. The consolidated privacy audit is an
--   append-only evidence projection, deduplicated by source service, stream,
--   and event ID. Privacy decisions, their audit row, and outbox row commit
--   together; domain events arrive through the privacy inbox idempotently.
--   An account closure, reversal, return, or write-off never deletes its
--   financial history; retention actions follow owner, schedule, and hold.
-- * Privacy writes outbox rows with policy/decision/hold/case changes. Its
--   inbox deduplicates producer events. Consumers use their existing inboxes.
-- * Privacy service outage fails closed for high-risk optional processing;
--   essential banking follows approved continuity policy. Retention periods,
--   legal applicability, and policy codes require separate bank approval.

--------------------------------------------------------------------------------
-- MODULE 10 - MB_STATEMENT_REPORTING
--------------------------------------------------------------------------------

CREATE TABLE M10_MASKING_PROFILE (
  MASKING_PROFILE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  PROFILE_CODE VARCHAR2(80 CHAR) NOT NULL,
  VERSION_NO NUMBER(10) NOT NULL,
  CHANNEL_CODE VARCHAR2(30 CHAR) NOT NULL,
  AUDIENCE_CODE VARCHAR2(30 CHAR) NOT NULL,
  RULES_JSON CLOB NOT NULL,
  RULES_SHA256 CHAR(64) NOT NULL,
  STATUS VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL,
  APPROVED_BY VARCHAR2(36 CHAR),
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_SR_MASK_UQ_VERSION UNIQUE (PROFILE_CODE, VERSION_NO),
  CONSTRAINT MB_SR_MASK_CK_JSON CHECK (RULES_JSON IS JSON),
  CONSTRAINT MB_SR_MASK_CK_STATUS CHECK (STATUS IN ('DRAFT','APPROVED','RETIRED')),
  CONSTRAINT MB_SR_MASK_CK_VERSION CHECK (VERSION_NO > 0),
  CONSTRAINT MB_SR_MASK_CK_APPROVAL CHECK
    ((STATUS = 'DRAFT' AND APPROVED_BY IS NULL AND APPROVED_AT IS NULL) OR
     (STATUS IN ('APPROVED','RETIRED') AND APPROVED_BY IS NOT NULL AND APPROVED_AT IS NOT NULL))
);

CREATE TABLE M10_NARRATION_CATALOG (
  NARRATION_CATALOG_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  NARRATION_CODE VARCHAR2(100 CHAR) NOT NULL,
  LOCALE_CODE VARCHAR2(20 CHAR) NOT NULL,
  AUDIENCE_CODE VARCHAR2(30 CHAR) NOT NULL,
  VERSION_NO NUMBER(10) NOT NULL,
  RENDERED_TEXT VARCHAR2(1000 CHAR) NOT NULL,
  EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  EFFECTIVE_TO TIMESTAMP(6) WITH TIME ZONE,
  APPROVAL_STATUS VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL,
  CHECKSUM_SHA256 CHAR(64) NOT NULL,
  APPROVED_BY VARCHAR2(36 CHAR),
  APPROVED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_SR_NARR_UQ_VERSION UNIQUE
    (NARRATION_CODE, LOCALE_CODE, AUDIENCE_CODE, VERSION_NO),
  CONSTRAINT MB_SR_NARR_CK_STATUS CHECK (APPROVAL_STATUS IN ('DRAFT','APPROVED','RETIRED')),
  CONSTRAINT MB_SR_NARR_CK_VERSION CHECK (VERSION_NO > 0),
  CONSTRAINT MB_SR_NARR_CK_DATES CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO > EFFECTIVE_FROM),
  CONSTRAINT MB_SR_NARR_CK_APPROVAL CHECK
    ((APPROVAL_STATUS = 'DRAFT' AND APPROVED_BY IS NULL AND APPROVED_AT IS NULL) OR
     (APPROVAL_STATUS IN ('APPROVED','RETIRED') AND APPROVED_BY IS NOT NULL AND APPROVED_AT IS NOT NULL))
);
CREATE INDEX M10_SR_NARR_IX_RESOLVE
  ON M10_NARRATION_CATALOG
    (NARRATION_CODE, LOCALE_CODE, AUDIENCE_CODE, APPROVAL_STATUS, EFFECTIVE_FROM);

CREATE TABLE M10_STATEMENT_REQUEST (
  REQUEST_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  REQUEST_PAYLOAD_SHA256 CHAR(64) NOT NULL,
  ACCOUNT_ID NUMBER(19) NOT NULL,
  CUSTOMER_CIF_ID VARCHAR2(36 CHAR),
  STATEMENT_TYPE VARCHAR2(30 CHAR) NOT NULL,
  PERIOD_START_DATE DATE,
  PERIOD_END_DATE DATE,
  REQUESTED_LOCALE VARCHAR2(20 CHAR),
  REQUESTED_FORMAT VARCHAR2(12 CHAR) DEFAULT 'PDF' NOT NULL,
  REQUESTER_TYPE VARCHAR2(20 CHAR) NOT NULL,
  REQUESTER_ID VARCHAR2(36 CHAR) NOT NULL,
  REQUEST_CHANNEL VARCHAR2(30 CHAR) NOT NULL,
  PURPOSE_CODE VARCHAR2(80 CHAR),
  CASE_REFERENCE VARCHAR2(160 CHAR),
  AUTHORIZATION_REF VARCHAR2(160 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  STATUS VARCHAR2(30 CHAR) DEFAULT 'RECEIVED' NOT NULL,
  FAILURE_CODE VARCHAR2(80 CHAR),
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  STARTED_AT TIMESTAMP(6) WITH TIME ZONE,
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  VERSION_NO NUMBER(19) DEFAULT 1 NOT NULL,
  CONSTRAINT MB_SR_REQ_UQ_IDEMP UNIQUE (REQUESTER_TYPE, REQUESTER_ID, IDEMPOTENCY_KEY),
  CONSTRAINT MB_SR_REQ_CK_TYPE CHECK (STATEMENT_TYPE IN
    ('CURRENT','PERIODIC','AD_HOC','REISSUE','CORRECTED','STAFF_ASSISTED','LEGALLY_REQUIRED')),
  CONSTRAINT MB_SR_REQ_CK_FORMAT CHECK (REQUESTED_FORMAT IN ('PDF','CSV','HTML')),
  CONSTRAINT MB_SR_REQ_CK_REQUESTER CHECK (REQUESTER_TYPE IN ('CUSTOMER','STAFF','SYSTEM','REGULATOR')),
  CONSTRAINT MB_SR_REQ_CK_STATUS CHECK (STATUS IN
    ('RECEIVED','AUTHORIZED','PROCESSING','COMPLETED','REJECTED','FAILED','QUARANTINED','CANCELLED')),
  CONSTRAINT MB_SR_REQ_CK_PERIOD CHECK
    (PERIOD_END_DATE IS NULL OR PERIOD_START_DATE IS NULL OR PERIOD_END_DATE >= PERIOD_START_DATE),
  CONSTRAINT MB_SR_REQ_CK_STAFF CHECK
    ((REQUESTER_TYPE = 'STAFF' AND PURPOSE_CODE IS NOT NULL) OR REQUESTER_TYPE <> 'STAFF'),
  CONSTRAINT MB_SR_REQ_CK_CASE CHECK
    ((STATEMENT_TYPE IN ('STAFF_ASSISTED','LEGALLY_REQUIRED') AND CASE_REFERENCE IS NOT NULL) OR
     STATEMENT_TYPE NOT IN ('STAFF_ASSISTED','LEGALLY_REQUIRED')),
  CONSTRAINT MB_SR_REQ_CK_TIMES CHECK
    ((STARTED_AT IS NULL OR STARTED_AT >= REQUESTED_AT) AND
     (COMPLETED_AT IS NULL OR (STARTED_AT IS NOT NULL AND COMPLETED_AT >= STARTED_AT)) AND
     VERSION_NO > 0)
);
CREATE INDEX M10_SR_REQ_IX_WORK
  ON M10_STATEMENT_REQUEST(STATUS, REQUESTED_AT);
CREATE INDEX M10_SR_REQ_IX_ACCOUNT
  ON M10_STATEMENT_REQUEST(ACCOUNT_ID, PERIOD_START_DATE, PERIOD_END_DATE);

CREATE TABLE M10_STATEMENT_SOURCE_CUT (
  SOURCE_CUT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  ACCOUNT_ID NUMBER(19) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) DEFAULT 'INR' NOT NULL,
  PERIOD_START_DATE DATE NOT NULL,
  PERIOD_END_DATE DATE NOT NULL,
  AS_OF_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  COMPLETED_THROUGH_MARKER VARCHAR2(200 CHAR) NOT NULL,
  MAX_JOURNAL_ID NUMBER(19) NOT NULL,
  MAX_POSTING_ID NUMBER(19) NOT NULL,
  SOURCE_ORDERING VARCHAR2(100 CHAR) NOT NULL,
  ELIGIBILITY_POLICY_VERSION VARCHAR2(80 CHAR) NOT NULL,
  ELIGIBILITY_RULE_SHA256 CHAR(64) NOT NULL,
  OPENING_POSTED_BALANCE NUMBER(18,2) NOT NULL,
  CLOSING_POSTED_BALANCE NUMBER(18,2) NOT NULL,
  SOURCE_CONTROL_TOTAL NUMBER(18,2) NOT NULL,
  SOURCE_TRANSACTION_COUNT NUMBER(19) NOT NULL,
  SOURCE_CONTROL_SHA256 CHAR(64) NOT NULL,
  CUT_STATUS VARCHAR2(20 CHAR) DEFAULT 'BUILDING' NOT NULL,
  MISMATCH_REASON_CODE VARCHAR2(80 CHAR),
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_SR_CUT_UQ_MARKER UNIQUE (ACCOUNT_ID, CURRENCY_CODE, COMPLETED_THROUGH_MARKER),
  CONSTRAINT MB_SR_CUT_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_SR_CUT_CK_DATES CHECK (PERIOD_END_DATE >= PERIOD_START_DATE),
  CONSTRAINT MB_SR_CUT_CK_NUMBERS CHECK (MAX_JOURNAL_ID > 0 AND MAX_POSTING_ID > 0 AND SOURCE_TRANSACTION_COUNT >= 0),
  CONSTRAINT MB_SR_CUT_CK_STATUS CHECK (CUT_STATUS IN ('BUILDING','COMPLETED','QUARANTINED','FAILED')),
  CONSTRAINT MB_SR_CUT_CK_COMPLETE CHECK
    ((CUT_STATUS = 'COMPLETED' AND COMPLETED_AT IS NOT NULL AND MISMATCH_REASON_CODE IS NULL) OR
     (CUT_STATUS = 'QUARANTINED' AND COMPLETED_AT IS NOT NULL AND MISMATCH_REASON_CODE IS NOT NULL) OR
     (CUT_STATUS IN ('BUILDING','FAILED') AND COMPLETED_AT IS NULL))
);
CREATE INDEX M10_SR_CUT_IX_ACCOUNT
  ON M10_STATEMENT_SOURCE_CUT(ACCOUNT_ID, AS_OF_AT, CUT_STATUS);

CREATE TABLE M10_STATEMENT_SNAPSHOT (
  STATEMENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  STATEMENT_NUMBER VARCHAR2(40 CHAR) NOT NULL,
  REQUEST_ID VARCHAR2(36 CHAR) NOT NULL,
  ACCOUNT_ID NUMBER(19) NOT NULL,
  CUSTOMER_CIF_ID VARCHAR2(36 CHAR),
  STATEMENT_TYPE VARCHAR2(30 CHAR) NOT NULL,
  PERIOD_START_DATE DATE NOT NULL,
  PERIOD_END_DATE DATE NOT NULL,
  REVISION_NO NUMBER(10) DEFAULT 1 NOT NULL,
  PRIOR_STATEMENT_ID VARCHAR2(36 CHAR),
  CORRECTION_REASON_CODE VARCHAR2(80 CHAR),
  SOURCE_CUT_ID VARCHAR2(36 CHAR) NOT NULL,
  BUSINESS_TIMEZONE VARCHAR2(64 CHAR) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) DEFAULT 'INR' NOT NULL,
  OPENING_POSTED_BALANCE NUMBER(18,2) NOT NULL,
  CLOSING_POSTED_BALANCE NUMBER(18,2) NOT NULL,
  SOURCE_CONTROL_TOTAL NUMBER(18,2) NOT NULL,
  SOURCE_TRANSACTION_COUNT NUMBER(19) NOT NULL,
  MASKING_PROFILE_ID VARCHAR2(36 CHAR) NOT NULL,
  MASKING_PROFILE_VERSION NUMBER(10) NOT NULL,
  RESOLVED_LOCALE VARCHAR2(20 CHAR) NOT NULL,
  CALCULATION_POLICY_VERSION VARCHAR2(80 CHAR) NOT NULL,
  SNAPSHOT_HASH_SHA256 CHAR(64) NOT NULL,
  STATE VARCHAR2(30 CHAR) DEFAULT 'DRAFT' NOT NULL,
  ISSUED_AT TIMESTAMP(6) WITH TIME ZONE,
  IMMUTABLE_AT TIMESTAMP(6) WITH TIME ZONE,
  RETENTION_UNTIL TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_SR_STMT_UQ_NUMBER UNIQUE (STATEMENT_NUMBER),
  CONSTRAINT MB_SR_STMT_UQ_REV UNIQUE (ACCOUNT_ID, STATEMENT_TYPE, PERIOD_START_DATE, PERIOD_END_DATE, REVISION_NO),
  CONSTRAINT MB_SR_STMT_FK_REQUEST FOREIGN KEY (REQUEST_ID)
    REFERENCES M10_STATEMENT_REQUEST(REQUEST_ID),
  CONSTRAINT MB_SR_STMT_FK_PRIOR FOREIGN KEY (PRIOR_STATEMENT_ID)
    REFERENCES M10_STATEMENT_SNAPSHOT(STATEMENT_ID),
  CONSTRAINT MB_SR_STMT_FK_CUT FOREIGN KEY (SOURCE_CUT_ID)
    REFERENCES M10_STATEMENT_SOURCE_CUT(SOURCE_CUT_ID),
  CONSTRAINT MB_SR_STMT_FK_MASK FOREIGN KEY (MASKING_PROFILE_ID)
    REFERENCES M10_MASKING_PROFILE(MASKING_PROFILE_ID),
  CONSTRAINT MB_SR_STMT_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_SR_STMT_CK_TYPE CHECK (STATEMENT_TYPE IN
    ('CURRENT','PERIODIC','AD_HOC','REISSUE','CORRECTED','STAFF_ASSISTED','LEGALLY_REQUIRED')),
  CONSTRAINT MB_SR_STMT_CK_DATES CHECK (PERIOD_END_DATE >= PERIOD_START_DATE),
  CONSTRAINT MB_SR_STMT_CK_REVISION CHECK
    ((REVISION_NO = 1 AND PRIOR_STATEMENT_ID IS NULL AND CORRECTION_REASON_CODE IS NULL) OR
     (REVISION_NO > 1 AND PRIOR_STATEMENT_ID IS NOT NULL AND CORRECTION_REASON_CODE IS NOT NULL)),
  CONSTRAINT MB_SR_STMT_CK_STATE CHECK (STATE IN ('DRAFT','QUARANTINED','ISSUED','VOIDED')),
  CONSTRAINT MB_SR_STMT_CK_ISSUED CHECK
    ((STATE = 'ISSUED' AND ISSUED_AT IS NOT NULL AND IMMUTABLE_AT IS NOT NULL) OR
     (STATE <> 'ISSUED' AND ISSUED_AT IS NULL AND IMMUTABLE_AT IS NULL)),
  CONSTRAINT MB_SR_STMT_CK_NUMBERS CHECK (REVISION_NO > 0 AND MASKING_PROFILE_VERSION > 0 AND SOURCE_TRANSACTION_COUNT >= 0)
);
CREATE INDEX M10_SR_STMT_IX_ACCOUNT
  ON M10_STATEMENT_SNAPSHOT(ACCOUNT_ID, PERIOD_START_DATE, PERIOD_END_DATE, STATE);
CREATE INDEX M10_SR_STMT_IX_PRIOR
  ON M10_STATEMENT_SNAPSHOT(PRIOR_STATEMENT_ID);
CREATE INDEX M10_SR_STMT_IX_CUT
  ON M10_STATEMENT_SNAPSHOT(SOURCE_CUT_ID);

CREATE TABLE M10_STATEMENT_LINE_ITEM (
  STATEMENT_LINE_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  STATEMENT_ID VARCHAR2(36 CHAR) NOT NULL,
  LINE_NO NUMBER(10) NOT NULL,
  SOURCE_JOURNAL_ID NUMBER(19) NOT NULL,
  SOURCE_POSTING_ID NUMBER(19) NOT NULL,
  SOURCE_TXN_ID NUMBER(19),
  SOURCE_PAYMENT_ID NUMBER(19),
  SOURCE_LOAN_FACILITY_ID NUMBER(19),
  SOURCE_BOOKED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
  SOURCE_VALUE_DATE DATE NOT NULL,
  SOURCE_ORDERING_MARKER VARCHAR2(200 CHAR) NOT NULL,
  ENTRY_CLASS VARCHAR2(20 CHAR) NOT NULL,
  AMOUNT_SIGNED NUMBER(18,2) NOT NULL,
  POSTED_BALANCE_AFTER NUMBER(18,2) NOT NULL,
  CURRENCY_CODE VARCHAR2(3 CHAR) DEFAULT 'INR' NOT NULL,
  NARRATION_CATALOG_ID VARCHAR2(36 CHAR),
  NARRATION_CODE VARCHAR2(100 CHAR),
  NARRATION_VERSION_NO NUMBER(10),
  RENDERED_NARRATION VARCHAR2(1000 CHAR) NOT NULL,
  RENDERED_LINE_SHA256 CHAR(64) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_SR_LINE_UQ_NO UNIQUE (STATEMENT_ID, LINE_NO),
  CONSTRAINT MB_SR_LINE_UQ_SOURCE UNIQUE (STATEMENT_ID, SOURCE_JOURNAL_ID, SOURCE_POSTING_ID),
  CONSTRAINT MB_SR_LINE_FK_STMT FOREIGN KEY (STATEMENT_ID)
    REFERENCES M10_STATEMENT_SNAPSHOT(STATEMENT_ID),
  CONSTRAINT MB_SR_LINE_FK_NARR FOREIGN KEY (NARRATION_CATALOG_ID)
    REFERENCES M10_NARRATION_CATALOG(NARRATION_CATALOG_ID),
  CONSTRAINT MB_SR_LINE_CK_CCY CHECK (CURRENCY_CODE = 'INR'),
  CONSTRAINT MB_SR_LINE_CK_NO CHECK (LINE_NO > 0),
  CONSTRAINT MB_SR_LINE_CK_ENTRY CHECK (ENTRY_CLASS IN ('NORMAL','REVERSAL','RETURN','ADJUSTMENT','CORRECTION')),
  CONSTRAINT MB_SR_LINE_CK_NARR CHECK
    ((NARRATION_CATALOG_ID IS NULL AND NARRATION_CODE IS NULL AND NARRATION_VERSION_NO IS NULL) OR
     (NARRATION_CATALOG_ID IS NOT NULL AND NARRATION_CODE IS NOT NULL AND NARRATION_VERSION_NO > 0))
);
CREATE INDEX M10_SR_LINE_IX_SOURCE
  ON M10_STATEMENT_LINE_ITEM(SOURCE_JOURNAL_ID, SOURCE_POSTING_ID);

CREATE TABLE M10_STATEMENT_DELIVERY_EVIDENCE (
  DELIVERY_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  STATEMENT_ID VARCHAR2(36 CHAR) NOT NULL,
  DELIVERY_IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  DELIVERY_CHANNEL VARCHAR2(30 CHAR) NOT NULL,
  RECIPIENT_TYPE VARCHAR2(20 CHAR) NOT NULL,
  RECIPIENT_REFERENCE_HASH CHAR(64) NOT NULL,
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  DISPATCHED_AT TIMESTAMP(6) WITH TIME ZONE,
  COMPLETED_AT TIMESTAMP(6) WITH TIME ZONE,
  DELIVERY_STATUS VARCHAR2(20 CHAR) DEFAULT 'REQUESTED' NOT NULL,
  FAILURE_CODE VARCHAR2(80 CHAR),
  RENDER_FORMAT VARCHAR2(12 CHAR) NOT NULL,
  RENDER_URI VARCHAR2(1000 CHAR),
  RENDER_SHA256 CHAR(64),
  AUTHORIZATION_REF VARCHAR2(160 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_SR_DELIV_UQ_KEY UNIQUE (STATEMENT_ID, DELIVERY_IDEMPOTENCY_KEY),
  CONSTRAINT MB_SR_DELIV_FK_STMT FOREIGN KEY (STATEMENT_ID)
    REFERENCES M10_STATEMENT_SNAPSHOT(STATEMENT_ID),
  CONSTRAINT MB_SR_DELIV_CK_CHANNEL CHECK (DELIVERY_CHANNEL IN ('DOWNLOAD','EMAIL','POST','BRANCH','API')),
  CONSTRAINT MB_SR_DELIV_CK_RECIPIENT CHECK (RECIPIENT_TYPE IN ('CUSTOMER','STAFF','REGULATOR','SYSTEM')),
  CONSTRAINT MB_SR_DELIV_CK_FORMAT CHECK (RENDER_FORMAT IN ('PDF','CSV','HTML')),
  CONSTRAINT MB_SR_DELIV_CK_STATUS CHECK (DELIVERY_STATUS IN ('REQUESTED','DISPATCHED','DELIVERED','FAILED','CANCELLED')),
  CONSTRAINT MB_SR_DELIV_CK_TIMES CHECK
    ((DISPATCHED_AT IS NULL OR DISPATCHED_AT >= REQUESTED_AT) AND
     (COMPLETED_AT IS NULL OR (DISPATCHED_AT IS NOT NULL AND COMPLETED_AT >= DISPATCHED_AT))),
  CONSTRAINT MB_SR_DELIV_CK_RENDER CHECK
    ((DELIVERY_STATUS = 'DELIVERED' AND COMPLETED_AT IS NOT NULL AND RENDER_SHA256 IS NOT NULL) OR
     DELIVERY_STATUS <> 'DELIVERED')
);
CREATE INDEX M10_SR_DELIV_IX_WORK
  ON M10_STATEMENT_DELIVERY_EVIDENCE(DELIVERY_STATUS, REQUESTED_AT);

CREATE TABLE M10_STATEMENT_ACCESS_AUDIT (
  ACCESS_AUDIT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  EVENT_TYPE VARCHAR2(40 CHAR) NOT NULL,
  ACTOR_TYPE VARCHAR2(20 CHAR) NOT NULL,
  ACTOR_ID VARCHAR2(36 CHAR),
  SESSION_ID VARCHAR2(36 CHAR),
  ROLE_CODE VARCHAR2(80 CHAR),
  ACTOR_SCOPE_REF VARCHAR2(160 CHAR),
  CUSTOMER_CIF_ID VARCHAR2(36 CHAR),
  ACCOUNT_ID NUMBER(19) NOT NULL,
  STATEMENT_ID VARCHAR2(36 CHAR),
  REQUEST_ID VARCHAR2(36 CHAR),
  PURPOSE_CODE VARCHAR2(80 CHAR),
  CASE_REFERENCE VARCHAR2(160 CHAR),
  AUTHORIZATION_REF VARCHAR2(160 CHAR),
  MASKING_PROFILE_ID VARCHAR2(36 CHAR),
  RESULT VARCHAR2(20 CHAR) NOT NULL,
  DENIAL_REASON_CODE VARCHAR2(80 CHAR),
  CORRELATION_ID VARCHAR2(100 CHAR),
  IP_TOKEN VARCHAR2(256 CHAR),
  USER_AGENT_HASH CHAR(64),
  REQUEST_METADATA CLOB NOT NULL,
  CONSTRAINT MB_SR_AUDIT_FK_STMT FOREIGN KEY (STATEMENT_ID)
    REFERENCES M10_STATEMENT_SNAPSHOT(STATEMENT_ID),
  CONSTRAINT MB_SR_AUDIT_FK_REQ FOREIGN KEY (REQUEST_ID)
    REFERENCES M10_STATEMENT_REQUEST(REQUEST_ID),
  CONSTRAINT MB_SR_AUDIT_FK_MASK FOREIGN KEY (MASKING_PROFILE_ID)
    REFERENCES M10_MASKING_PROFILE(MASKING_PROFILE_ID),
  CONSTRAINT MB_SR_AUDIT_CK_JSON CHECK (REQUEST_METADATA IS JSON),
  CONSTRAINT MB_SR_AUDIT_CK_EVENT CHECK (EVENT_TYPE IN ('REQUEST','ISSUE','VIEW','DOWNLOAD','REISSUE','DELIVERY')),
  CONSTRAINT MB_SR_AUDIT_CK_ACTOR CHECK (ACTOR_TYPE IN ('CUSTOMER','STAFF','SYSTEM','REGULATOR')),
  CONSTRAINT MB_SR_AUDIT_CK_RESULT CHECK (RESULT IN ('ALLOWED','DENIED','FAILED')),
  CONSTRAINT MB_SR_AUDIT_CK_DENIAL CHECK
    ((RESULT = 'DENIED' AND DENIAL_REASON_CODE IS NOT NULL) OR
     (RESULT <> 'DENIED' AND DENIAL_REASON_CODE IS NULL))
);
CREATE INDEX M10_SR_AUDIT_IX_ACTOR
  ON M10_STATEMENT_ACCESS_AUDIT(ACTOR_ID, OCCURRED_AT);
CREATE INDEX M10_SR_AUDIT_IX_ACCOUNT
  ON M10_STATEMENT_ACCESS_AUDIT(ACCOUNT_ID, OCCURRED_AT);

CREATE TABLE M10_STATEMENT_OUTBOX_EVENT (
  EVENT_ID VARCHAR2(36 CHAR) PRIMARY KEY,
  AGGREGATE_TYPE VARCHAR2(50 CHAR) NOT NULL,
  AGGREGATE_ID VARCHAR2(36 CHAR) NOT NULL,
  EVENT_TYPE VARCHAR2(100 CHAR) NOT NULL,
  SCHEMA_VERSION NUMBER(10) NOT NULL,
  IDEMPOTENCY_KEY VARCHAR2(160 CHAR) NOT NULL,
  CORRELATION_ID VARCHAR2(100 CHAR),
  PAYLOAD_JSON CLOB NOT NULL,
  PAYLOAD_HASH_SHA256 CHAR(64) NOT NULL,
  OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PUBLISH_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
  PUBLISHED_AT TIMESTAMP(6) WITH TIME ZONE,
  PUBLISH_ATTEMPTS NUMBER(10) DEFAULT 0 NOT NULL,
  LAST_ERROR_CODE VARCHAR2(80 CHAR),
  CONSTRAINT MB_SR_OUTBOX_UQ_IDEMP UNIQUE (IDEMPOTENCY_KEY),
  CONSTRAINT MB_SR_OUTBOX_CK_JSON CHECK (PAYLOAD_JSON IS JSON),
  CONSTRAINT MB_SR_OUTBOX_CK_STATUS CHECK (PUBLISH_STATUS IN ('PENDING','CLAIMED','PUBLISHED','DEAD_LETTER')),
  CONSTRAINT MB_SR_OUTBOX_CK_STATE CHECK
    ((PUBLISH_STATUS = 'PUBLISHED' AND PUBLISHED_AT IS NOT NULL) OR
     (PUBLISH_STATUS <> 'PUBLISHED' AND PUBLISHED_AT IS NULL)),
  CONSTRAINT MB_SR_OUTBOX_CK_NUMBERS CHECK (SCHEMA_VERSION > 0 AND PUBLISH_ATTEMPTS >= 0)
);
CREATE INDEX M10_SR_OUTBOX_IX_PENDING
  ON M10_STATEMENT_OUTBOX_EVENT(PUBLISH_STATUS, OCCURRED_AT);

CREATE TABLE M10_STATEMENT_CONSUMER_INBOX (
  SOURCE_SERVICE VARCHAR2(120 CHAR) NOT NULL,
  EVENT_ID VARCHAR2(100 CHAR) NOT NULL,
  EVENT_TYPE VARCHAR2(120 CHAR) NOT NULL,
  EVENT_PAYLOAD_SHA256 CHAR(64) NOT NULL,
  RECEIVED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  PROCESSED_AT TIMESTAMP(6) WITH TIME ZONE,
  RESULT_CODE VARCHAR2(30 CHAR),
  FAILURE_CODE VARCHAR2(80 CHAR),
  CONSTRAINT MB_SR_INBOX_PK PRIMARY KEY (SOURCE_SERVICE, EVENT_ID),
  CONSTRAINT MB_SR_INBOX_CK_RESULT CHECK (RESULT_CODE IS NULL OR RESULT_CODE IN ('PROCESSED','IGNORED','FAILED','QUARANTINED'))
);
CREATE INDEX M10_SR_INBOX_IX_PENDING
  ON M10_STATEMENT_CONSUMER_INBOX(PROCESSED_AT, RECEIVED_AT);

CREATE OR REPLACE TRIGGER M10_TRG_SR_MASK_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_MASKING_PROFILE
FOR EACH ROW
BEGIN
  IF :OLD.STATUS IN ('APPROVED','RETIRED') THEN
    RAISE_APPLICATION_ERROR(-20050, 'Approved masking profile versions are immutable.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_NARR_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_NARRATION_CATALOG
FOR EACH ROW
BEGIN
  IF :OLD.APPROVAL_STATUS IN ('APPROVED','RETIRED') THEN
    RAISE_APPLICATION_ERROR(-20051, 'Approved narration versions are immutable.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_CUT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_STATEMENT_SOURCE_CUT
FOR EACH ROW
BEGIN
  IF :OLD.CUT_STATUS IN ('COMPLETED','QUARANTINED') THEN
    RAISE_APPLICATION_ERROR(-20052, 'Completed statement source cuts are immutable.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_STMT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_STATEMENT_SNAPSHOT
FOR EACH ROW
BEGIN
  IF :OLD.IMMUTABLE_AT IS NOT NULL THEN
    RAISE_APPLICATION_ERROR(-20053, 'Issued statements are immutable; create a corrected revision.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_LINE_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_STATEMENT_LINE_ITEM
BEGIN
  RAISE_APPLICATION_ERROR(-20054, 'Statement line items are append-only.');
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_AUDIT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_STATEMENT_ACCESS_AUDIT
BEGIN
  RAISE_APPLICATION_ERROR(-20055, 'Statement access audit evidence is append-only.');
END;
/

-- Module 10 integration contract:
-- * Statement Reporting reads only the posted MB_TXN.GL_JOURNAL and GL_POSTING
--   financial book of record. It orders a customer-account cut by BOOKED_AT,
--   JOURNAL_ID, POSTING_ID; normal eligibility requires the linked transaction,
--   when present, to be POSTED. HELD, FAILED, CANCELLED, pending, and rejected
--   transactions are excluded. Reversals, returns, adjustments, and corrections
--   are later independently posted entries and are rendered with their ENTRY_CLASS.
-- * The service calculates opening and closing posted balances from the cut, not
--   from ACCOUNT_MGMT projections. A control mismatch quarantines the cut and
--   request and writes a SOURCE_MISMATCH outbox event in the same transaction.
-- * Before each request, issue, view/download, reissue, and delivery, the service
--   performs fresh IAM, IAM_CUSTOMER_LINK, ACCOUNT_PARTY, operating-instruction,
--   account lifecycle/restriction, privacy/hold, and staff purpose/case checks.
--   Those checks account for dormant, frozen, debit/credit-blocked, closing and
--   closed accounts; joint, guardian, nominee, and deceased-party authority;
--   privacy/legal holds; disputed postings; and failed or reprint deliveries.
--   Actor IDs, roles, scopes, and authorization references are historical evidence
--   only. Both allowed and denied decisions create access audit evidence.
-- * Service consumers deduplicate producer events in STATEMENT_CONSUMER_INBOX and
--   still refresh owner facts before disclosing data. Request, issue, correction,
--   delivery, failure, and access-relevant changes commit with idempotent outbox rows.
-- * A request replay must match REQUEST_PAYLOAD_SHA256 for its requester-scoped
--   idempotency key; a different payload is rejected and audited. Issuance must
--   use an approved resolved masking profile and narration version, then persist
--   exactly the rendered values and hashes. No later policy, account, or source
--   change rewrites an issued revision. Customer and staff representations require
--   separate authorization and audience-specific masking. Closure and retention
--   never delete evidence.

--------------------------------------------------------------------------------
-- MONEYBAGS / FINERACT COMPARISON ENHANCEMENTS (GREENFIELD APPENDIX)
-- Apply after the original Modules 1-10 statements, before application access.
-- Fineract-inspired features are adapted to Moneybags' Oracle/service ownership.
--------------------------------------------------------------------------------

-- The original payment state machine describes outbound debits. Keep its
-- transition rows for outbound payments and add an independent inbound path.
CREATE TABLE M06_PAYMENT_DIRECTION_TRANSITION (
  PAYMENT_DIRECTION VARCHAR2(10 CHAR) NOT NULL,
  FROM_STATUS VARCHAR2(30 CHAR) NOT NULL,
  TO_STATUS VARCHAR2(30 CHAR) NOT NULL,
  REQUIRES_RAIL_EVIDENCE CHAR(1 CHAR) DEFAULT 'N' NOT NULL,
  REQUIRES_LEDGER_EVIDENCE CHAR(1 CHAR) DEFAULT 'N' NOT NULL,
  CONSTRAINT MB_PK_PAY_DIRECTION_TRANSITION PRIMARY KEY
    (PAYMENT_DIRECTION, FROM_STATUS, TO_STATUS),
  CONSTRAINT MB_FK_PAY_DIRECTION_TRANSITION FOREIGN KEY (FROM_STATUS, TO_STATUS)
    REFERENCES M06_PAYMENT_STATE_TRANSITION(FROM_STATUS, TO_STATUS),
  CONSTRAINT MB_CK_PAY_DIRECTION_TRANSITION CHECK
    (PAYMENT_DIRECTION IN ('OUTBOUND','INBOUND') AND
     REQUIRES_RAIL_EVIDENCE IN ('Y','N') AND
     REQUIRES_LEDGER_EVIDENCE IN ('Y','N'))
);
INSERT INTO M06_PAYMENT_DIRECTION_TRANSITION
  (PAYMENT_DIRECTION, FROM_STATUS, TO_STATUS,
   REQUIRES_RAIL_EVIDENCE, REQUIRES_LEDGER_EVIDENCE)
SELECT 'OUTBOUND', FROM_STATUS, TO_STATUS,
       REQUIRES_RAIL_EVIDENCE, REQUIRES_LEDGER_EVIDENCE
FROM M06_PAYMENT_STATE_TRANSITION;

ALTER TABLE M06_PAYMENT_INSTRUCTION DROP CONSTRAINT MB_CK_PAYMENT_STATUS;
ALTER TABLE M06_PAYMENT_INSTRUCTION ADD CONSTRAINT MB_CK_PAYMENT_STATUS
  CHECK (STATUS IN
    ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED',
     'CREDIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN','SETTLEMENT_PENDING',
     'SETTLED','REJECTED','REFUNDED','CANCELLED'));
ALTER TABLE M06_PAYMENT_STATUS_HISTORY DROP CONSTRAINT MB_CK_PAY_HISTORY_TO_STATUS;
ALTER TABLE M06_PAYMENT_STATUS_HISTORY DROP CONSTRAINT MB_CK_PAY_HISTORY_FROM_STATUS;
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_CK_PAY_HISTORY_TO_STATUS
  CHECK (TO_STATUS IN
    ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED',
     'CREDIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN','SETTLEMENT_PENDING',
     'SETTLED','REJECTED','REFUNDED','CANCELLED'));
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_CK_PAY_HISTORY_FROM_STATUS
  CHECK (FROM_STATUS IS NULL OR FROM_STATUS IN
    ('RECEIVED','AUTHORIZED','LIQUIDITY_PENDING','HELD','DEBIT_POSTED',
     'CREDIT_POSTED','DISPATCHED','ACCEPTED','UNKNOWN','SETTLEMENT_PENDING',
     'SETTLED','REJECTED','REFUNDED','CANCELLED'));

INSERT ALL
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('AUTHORIZED','SETTLEMENT_PENDING','Y','N')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('SETTLEMENT_PENDING','CREDIT_POSTED','Y','Y')
  INTO M06_PAYMENT_STATE_TRANSITION VALUES ('CREDIT_POSTED','SETTLED','Y','Y')
SELECT 1 FROM DUAL;
INSERT ALL
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','RECEIVED','AUTHORIZED','N','N')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','RECEIVED','REJECTED','N','N')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','AUTHORIZED','SETTLEMENT_PENDING','Y','N')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','AUTHORIZED','REJECTED','Y','N')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','SETTLEMENT_PENDING','CREDIT_POSTED','Y','Y')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','SETTLEMENT_PENDING','REJECTED','Y','N')
  INTO M06_PAYMENT_DIRECTION_TRANSITION VALUES ('INBOUND','CREDIT_POSTED','SETTLED','Y','Y')
SELECT 1 FROM DUAL;
ALTER TABLE M06_PAYMENT_INSTRUCTION ADD CONSTRAINT MB_UK_PAY_ID_DIRECTION
  UNIQUE (PAYMENT_ID, PAYMENT_DIRECTION);
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD (
  PAYMENT_DIRECTION VARCHAR2(10 CHAR) DEFAULT 'OUTBOUND' NOT NULL,
  LEDGER_JOURNAL_ID NUMBER(19),
  TREASURY_ENTRY_ID NUMBER(19)
);
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_FK_PAY_HISTORY_DIRECTION
  FOREIGN KEY (PAYMENT_ID, PAYMENT_DIRECTION)
  REFERENCES M06_PAYMENT_INSTRUCTION(PAYMENT_ID, PAYMENT_DIRECTION);
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_FK_PAY_HISTORY_DIR_TRANS
  FOREIGN KEY (PAYMENT_DIRECTION, FROM_STATUS, TO_STATUS)
  REFERENCES M06_PAYMENT_DIRECTION_TRANSITION
    (PAYMENT_DIRECTION, FROM_STATUS, TO_STATUS);
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_CK_PAY_HISTORY_POSTED_SIDE
  CHECK ((TO_STATUS <> 'DEBIT_POSTED' OR
          (PAYMENT_DIRECTION = 'OUTBOUND' AND LEDGER_JOURNAL_ID IS NOT NULL)) AND
         (TO_STATUS <> 'CREDIT_POSTED' OR
          (PAYMENT_DIRECTION = 'INBOUND' AND LEDGER_JOURNAL_ID IS NOT NULL)));
-- Services must check transition flags and bind the journal/treasury references
-- to the same payment before status and history commit. Inbound credit is posted
-- only after confirmed external settlement, never from a pending notification.

-- Evidence must belong to the payment whose status/reconciliation it supports.
ALTER TABLE M06_RAIL_STATUS_EVIDENCE ADD CONSTRAINT MB_UK_PAY_EVIDENCE_SCOPE
  UNIQUE (EVIDENCE_ID, PAYMENT_ID);
ALTER TABLE M06_PAYMENT_STATUS_HISTORY ADD CONSTRAINT MB_FK_PAY_HIST_EVID_SCOPE
  FOREIGN KEY (EVIDENCE_ID, PAYMENT_ID)
  REFERENCES M06_RAIL_STATUS_EVIDENCE(EVIDENCE_ID, PAYMENT_ID);
ALTER TABLE M06_PAYMENT_RECONCILIATION ADD CONSTRAINT MB_FK_PAY_RECON_EVID_SCOPE
  FOREIGN KEY (RAIL_EVIDENCE_ID, PAYMENT_ID)
  REFERENCES M06_RAIL_STATUS_EVIDENCE(EVIDENCE_ID, PAYMENT_ID);

-- Different sources may observe the same reserve movement and use its external
-- reference. Each source/type has one logical observation; the hash deduplicates
-- exact repeated messages.
ALTER TABLE M07_SETTLEMENT_EVIDENCE
  DROP CONSTRAINT MB_UK_SETTLEMENT_EVIDENCE_REF;
ALTER TABLE M07_SETTLEMENT_EVIDENCE
  ADD CONSTRAINT MB_UK_SETTLEMENT_EVIDENCE_SOURCE_REF
  UNIQUE (RESERVE_ACCOUNT_ID, EVIDENCE_TYPE, EXTERNAL_SETTLEMENT_REF);
ALTER TABLE M07_SETTLEMENT_EVIDENCE
  ADD CONSTRAINT MB_UK_SETTLEMENT_EVIDENCE_ACCOUNT
  UNIQUE (EVIDENCE_ID, RESERVE_ACCOUNT_ID);
ALTER TABLE M07_CENTRAL_TREASURY_LEDGER
  ADD CONSTRAINT MB_FK_TREASURY_ENTRY_EVID_ACCOUNT
  FOREIGN KEY (EVIDENCE_ID, RESERVE_ACCOUNT_ID)
  REFERENCES M07_SETTLEMENT_EVIDENCE(EVIDENCE_ID, RESERVE_ACCOUNT_ID);
ALTER TABLE M07_CENTRAL_TREASURY_LEDGER
  ADD CONSTRAINT MB_UK_TREASURY_ENTRY_ACCOUNT
  UNIQUE (TREASURY_ENTRY_ID, RESERVE_ACCOUNT_ID);
ALTER TABLE M07_RESERVE_POSITION
  ADD CONSTRAINT MB_FK_RESERVE_POSITION_ENTRY_ACCOUNT
  FOREIGN KEY (LAST_TREASURY_ENTRY_ID, RESERVE_ACCOUNT_ID)
  REFERENCES M07_CENTRAL_TREASURY_LEDGER(TREASURY_ENTRY_ID, RESERVE_ACCOUNT_ID);
ALTER TABLE M07_TREASURY_LIQUIDITY_HOLD
  ADD CONSTRAINT MB_FK_LIQUIDITY_HOLD_ENTRY_ACCOUNT
  FOREIGN KEY (CONSUMED_BY_ENTRY_ID, RESERVE_ACCOUNT_ID)
  REFERENCES M07_CENTRAL_TREASURY_LEDGER(TREASURY_ENTRY_ID, RESERVE_ACCOUNT_ID);

-- Use facility-scoped references so a repayment cannot be allocated to a
-- different loan's schedule installment.
ALTER TABLE M08_LOAN_SCHEDULE ADD CONSTRAINT MB_UK_LN_SCHEDULE_FACILITY
  UNIQUE (SCHEDULE_ID, FACILITY_ID);
ALTER TABLE M08_LOAN_SCHEDULE_ITEM ADD (FACILITY_ID NUMBER(19) NOT NULL);
ALTER TABLE M08_LOAN_SCHEDULE_ITEM ADD CONSTRAINT MB_FK_LN_ITEM_FACILITY
  FOREIGN KEY (SCHEDULE_ID, FACILITY_ID)
  REFERENCES M08_LOAN_SCHEDULE(SCHEDULE_ID, FACILITY_ID);
ALTER TABLE M08_LOAN_SCHEDULE_ITEM ADD CONSTRAINT MB_UK_LN_ITEM_FACILITY
  UNIQUE (SCHEDULE_ITEM_ID, FACILITY_ID);
ALTER TABLE M08_LOAN_PAYMENT ADD CONSTRAINT MB_UK_LN_PAYMENT_FACILITY
  UNIQUE (LOAN_PAYMENT_ID, FACILITY_ID);
ALTER TABLE M08_LOAN_PAYMENT_ALLOCATION ADD (FACILITY_ID NUMBER(19) NOT NULL);
ALTER TABLE M08_LOAN_PAYMENT_ALLOCATION ADD CONSTRAINT MB_FK_LN_ALLOC_PAYMENT_FAC
  FOREIGN KEY (LOAN_PAYMENT_ID, FACILITY_ID)
  REFERENCES M08_LOAN_PAYMENT(LOAN_PAYMENT_ID, FACILITY_ID);
ALTER TABLE M08_LOAN_PAYMENT_ALLOCATION ADD CONSTRAINT MB_FK_LN_ALLOC_ITEM_FAC
  FOREIGN KEY (SCHEDULE_ITEM_ID, FACILITY_ID)
  REFERENCES M08_LOAN_SCHEDULE_ITEM(SCHEDULE_ITEM_ID, FACILITY_ID);

-- A statement's source cut must cover the same account, period, and currency.
ALTER TABLE M10_STATEMENT_SOURCE_CUT
  ADD CONSTRAINT MB_UK_SR_CUT_SCOPE UNIQUE
    (SOURCE_CUT_ID, ACCOUNT_ID, PERIOD_START_DATE, PERIOD_END_DATE, CURRENCY_CODE);
ALTER TABLE M10_STATEMENT_SNAPSHOT
  ADD CONSTRAINT MB_FK_SR_STMT_CUT_SCOPE FOREIGN KEY
    (SOURCE_CUT_ID, ACCOUNT_ID, PERIOD_START_DATE, PERIOD_END_DATE, CURRENCY_CODE)
  REFERENCES M10_STATEMENT_SOURCE_CUT
    (SOURCE_CUT_ID, ACCOUNT_ID, PERIOD_START_DATE, PERIOD_END_DATE, CURRENCY_CODE);
ALTER TABLE M10_STATEMENT_REQUEST
  ADD CONSTRAINT MB_UK_SR_REQUEST_ACCOUNT UNIQUE (REQUEST_ID, ACCOUNT_ID);
ALTER TABLE M10_STATEMENT_SNAPSHOT
  ADD CONSTRAINT MB_FK_SR_STMT_REQUEST_ACCOUNT FOREIGN KEY (REQUEST_ID, ACCOUNT_ID)
  REFERENCES M10_STATEMENT_REQUEST(REQUEST_ID, ACCOUNT_ID);
ALTER TABLE M10_STATEMENT_SOURCE_CUT
  DROP CONSTRAINT MB_SR_CUT_CK_NUMBERS;
ALTER TABLE M10_STATEMENT_SOURCE_CUT
  ADD CONSTRAINT MB_SR_CUT_CK_NUMBERS CHECK
    (MAX_JOURNAL_ID >= 0 AND MAX_POSTING_ID >= 0 AND SOURCE_TRANSACTION_COUNT >= 0);
ALTER TABLE M10_STATEMENT_SNAPSHOT
  DROP CONSTRAINT MB_SR_STMT_CK_ISSUED;
ALTER TABLE M10_STATEMENT_SNAPSHOT
  ADD CONSTRAINT MB_SR_STMT_CK_ISSUED CHECK
    ((STATE IN ('ISSUED','VOIDED') AND ISSUED_AT IS NOT NULL AND IMMUTABLE_AT IS NOT NULL) OR
     (STATE IN ('DRAFT','QUARANTINED') AND ISSUED_AT IS NULL AND IMMUTABLE_AT IS NULL));

-- Permit only a status-only retirement or voiding update to approved artifacts.
CREATE OR REPLACE TRIGGER M10_TRG_SR_MASK_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_MASKING_PROFILE
FOR EACH ROW
BEGIN
  IF DELETING THEN
    IF :OLD.STATUS IN ('APPROVED','RETIRED') THEN
      RAISE_APPLICATION_ERROR(-20050, 'Approved masking profile versions are immutable.');
    END IF;
  ELSIF :OLD.STATUS IN ('APPROVED','RETIRED') THEN
    IF :OLD.STATUS <> 'APPROVED' OR :NEW.STATUS <> 'RETIRED' OR
       UPDATING('MASKING_PROFILE_ID') OR UPDATING('PROFILE_CODE') OR
       UPDATING('VERSION_NO') OR UPDATING('CHANNEL_CODE') OR
       UPDATING('AUDIENCE_CODE') OR UPDATING('RULES_JSON') OR
       UPDATING('RULES_SHA256') OR UPDATING('APPROVED_BY') OR
       UPDATING('APPROVED_AT') OR UPDATING('CREATED_AT') OR
       UPDATING('CREATED_BY') THEN
      RAISE_APPLICATION_ERROR(-20050, 'Only APPROVED to RETIRED is allowed.');
    END IF;
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_NARR_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_NARRATION_CATALOG
FOR EACH ROW
BEGIN
  IF DELETING THEN
    IF :OLD.APPROVAL_STATUS IN ('APPROVED','RETIRED') THEN
      RAISE_APPLICATION_ERROR(-20051, 'Approved narration versions are immutable.');
    END IF;
  ELSIF :OLD.APPROVAL_STATUS IN ('APPROVED','RETIRED') THEN
    IF :OLD.APPROVAL_STATUS <> 'APPROVED' OR :NEW.APPROVAL_STATUS <> 'RETIRED' OR
       UPDATING('NARRATION_CATALOG_ID') OR UPDATING('NARRATION_CODE') OR
       UPDATING('LOCALE_CODE') OR UPDATING('AUDIENCE_CODE') OR
       UPDATING('VERSION_NO') OR UPDATING('RENDERED_TEXT') OR
       UPDATING('EFFECTIVE_FROM') OR UPDATING('EFFECTIVE_TO') OR
       UPDATING('CHECKSUM_SHA256') OR UPDATING('APPROVED_BY') OR
       UPDATING('APPROVED_AT') OR UPDATING('CREATED_AT') OR
       UPDATING('CREATED_BY') THEN
      RAISE_APPLICATION_ERROR(-20051, 'Only APPROVED to RETIRED is allowed.');
    END IF;
  END IF;
END;
/

CREATE OR REPLACE TRIGGER M10_TRG_SR_STMT_IMMUTABLE
BEFORE UPDATE OR DELETE ON M10_STATEMENT_SNAPSHOT
FOR EACH ROW
BEGIN
  IF DELETING THEN
    IF :OLD.IMMUTABLE_AT IS NOT NULL THEN
      RAISE_APPLICATION_ERROR(-20053, 'Issued statements are immutable.');
    END IF;
  ELSIF :OLD.IMMUTABLE_AT IS NOT NULL THEN
    IF :OLD.STATE <> 'ISSUED' OR :NEW.STATE <> 'VOIDED' OR
       UPDATING('STATEMENT_ID') OR UPDATING('STATEMENT_NUMBER') OR
       UPDATING('REQUEST_ID') OR UPDATING('ACCOUNT_ID') OR
       UPDATING('CUSTOMER_CIF_ID') OR UPDATING('STATEMENT_TYPE') OR
       UPDATING('PERIOD_START_DATE') OR UPDATING('PERIOD_END_DATE') OR
       UPDATING('REVISION_NO') OR UPDATING('PRIOR_STATEMENT_ID') OR
       UPDATING('CORRECTION_REASON_CODE') OR UPDATING('SOURCE_CUT_ID') OR
       UPDATING('BUSINESS_TIMEZONE') OR UPDATING('CURRENCY_CODE') OR
       UPDATING('OPENING_POSTED_BALANCE') OR UPDATING('CLOSING_POSTED_BALANCE') OR
       UPDATING('SOURCE_CONTROL_TOTAL') OR UPDATING('SOURCE_TRANSACTION_COUNT') OR
       UPDATING('MASKING_PROFILE_ID') OR UPDATING('MASKING_PROFILE_VERSION') OR
       UPDATING('RESOLVED_LOCALE') OR UPDATING('CALCULATION_POLICY_VERSION') OR
       UPDATING('SNAPSHOT_HASH_SHA256') OR UPDATING('ISSUED_AT') OR
       UPDATING('IMMUTABLE_AT') OR UPDATING('RETENTION_UNTIL') OR
       UPDATING('CREATED_AT') OR UPDATING('CREATED_BY') THEN
      RAISE_APPLICATION_ERROR(-20053, 'Only ISSUED to VOIDED is allowed.');
    END IF;
  END IF;
END;
/

-- Fineract acc_gl_closure-inspired bank-wide accounting close. The approved
-- Module 5 posting API must reject value dates on/before the latest close.
CREATE TABLE M05_GL_PERIOD_CLOSE (
  CLOSE_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  REQUEST_KEY VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  CLOSED_THROUGH_DATE DATE NOT NULL,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'PENDING' NOT NULL,
  MAKER_USER_ID VARCHAR2(36 CHAR) NOT NULL,
  CHECKER_USER_ID VARCHAR2(36 CHAR),
  REASON_TEXT VARCHAR2(500 CHAR) NOT NULL,
  REQUESTED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  DECIDED_AT TIMESTAMP(6) WITH TIME ZONE,
  CONSTRAINT MB_CK_GL_PERIOD_CLOSE_STATUS CHECK
    (STATUS IN ('PENDING','APPROVED','REJECTED')),
  CONSTRAINT MB_CK_GL_PERIOD_CLOSE_SOD CHECK
    (CHECKER_USER_ID IS NULL OR CHECKER_USER_ID <> MAKER_USER_ID),
  CONSTRAINT MB_CK_GL_PERIOD_CLOSE_DECISION CHECK
    ((STATUS = 'PENDING' AND CHECKER_USER_ID IS NULL AND DECIDED_AT IS NULL) OR
     (STATUS IN ('APPROVED','REJECTED') AND CHECKER_USER_ID IS NOT NULL AND DECIDED_AT IS NOT NULL))
);
CREATE UNIQUE INDEX M05_UX_GL_PERIOD_CLOSE_ACTIVE
  ON M05_GL_PERIOD_CLOSE
    (CASE WHEN STATUS IN ('PENDING','APPROVED') THEN CLOSED_THROUGH_DATE END);

-- Fineract acc_product_mapping-inspired role-to-GL mapping. Product version is
-- an opaque Product Master reference; Module 5 validates it through the service.
CREATE TABLE M05_GL_PRODUCT_MAPPING (
  MAPPING_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER(19) NOT NULL,
  POSTING_TYPE VARCHAR2(40 CHAR) NOT NULL,
  GL_ROLE_CODE VARCHAR2(40 CHAR) NOT NULL,
  GL_ACCOUNT_ID NUMBER(19) NOT NULL REFERENCES M05_GL_ACCOUNT(GL_ACCOUNT_ID),
  EFFECTIVE_FROM DATE NOT NULL,
  EFFECTIVE_TO DATE,
  STATUS VARCHAR2(12 CHAR) DEFAULT 'ACTIVE' NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CONSTRAINT MB_UK_GL_MAPPING_VERSION UNIQUE
    (PRODUCT_VERSION_ID, POSTING_TYPE, GL_ROLE_CODE, EFFECTIVE_FROM),
  CONSTRAINT MB_CK_GL_MAPPING_DATES CHECK
    (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO >= EFFECTIVE_FROM),
  CONSTRAINT MB_CK_GL_MAPPING_STATUS CHECK (STATUS IN ('ACTIVE','RETIRED'))
);

-- Fineract m_charge and m_loan_charge-inspired assessed fee instances. MB_TXN
-- owns their posted financial effect; policy IDs remain Product Master references.
CREATE TABLE M05_FEE_ASSESSMENT (
  FEE_ASSESSMENT_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FEE_KEY VARCHAR2(120 CHAR) NOT NULL UNIQUE,
  BANK_ACCOUNT_ID NUMBER(19),
  LOAN_FACILITY_ID NUMBER(19),
  PRODUCT_FEE_RULE_ID NUMBER(19) NOT NULL,
  ASSESSED_AMOUNT NUMBER(18,2) NOT NULL,
  PAID_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,
  WAIVED_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,
  DUE_DATE DATE NOT NULL,
  STATUS VARCHAR2(16 CHAR) DEFAULT 'ASSESSED' NOT NULL,
  ASSESSMENT_JOURNAL_ID NUMBER(19) REFERENCES M05_GL_JOURNAL(JOURNAL_ID),
  LAST_JOURNAL_ID NUMBER(19) REFERENCES M05_GL_JOURNAL(JOURNAL_ID),
  ASSESSED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_CK_FEE_ASSESSMENT_SCOPE CHECK
    ((BANK_ACCOUNT_ID IS NOT NULL AND LOAN_FACILITY_ID IS NULL) OR
     (BANK_ACCOUNT_ID IS NULL AND LOAN_FACILITY_ID IS NOT NULL)),
  CONSTRAINT MB_CK_FEE_ASSESSMENT_AMOUNTS CHECK
    (ASSESSED_AMOUNT > 0 AND PAID_AMOUNT >= 0 AND WAIVED_AMOUNT >= 0 AND
     PAID_AMOUNT + WAIVED_AMOUNT <= ASSESSED_AMOUNT),
  CONSTRAINT MB_CK_FEE_ASSESSMENT_STATUS CHECK
    (STATUS IN ('ASSESSED','PART_PAID','PAID','WAIVED','CANCELLED'))
);
CREATE INDEX M05_IX_FEE_ASSESSMENT_ACCOUNT
  ON M05_FEE_ASSESSMENT(BANK_ACCOUNT_ID, STATUS, DUE_DATE);
CREATE INDEX M05_IX_FEE_ASSESSMENT_LOAN
  ON M05_FEE_ASSESSMENT(LOAN_FACILITY_ID, STATUS, DUE_DATE);

-- Fineract product/loan allocation rules adapted to immutable Moneybags product
-- versions. A row's component order must be included in RULE_SET_HASH.
CREATE TABLE M03_PM_LOAN_ALLOCATION_RULE (
  ALLOCATION_RULE_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  PRODUCT_VERSION_ID NUMBER(19) NOT NULL
    REFERENCES M03_PM_PRODUCT_VERSION(PRODUCT_VERSION_ID),
  ALLOCATION_FLOW VARCHAR2(8 CHAR) NOT NULL,
  PAYMENT_KIND VARCHAR2(20 CHAR) NOT NULL,
  PRIORITY_NO NUMBER(5) NOT NULL,
  COMPONENT_CODE VARCHAR2(20 CHAR) NOT NULL,
  FUTURE_INSTALLMENT_RULE VARCHAR2(20 CHAR) DEFAULT 'NEXT_DUE' NOT NULL,
  CONSTRAINT MB_UK_PM_LOAN_ALLOC_PRIORITY UNIQUE
    (PRODUCT_VERSION_ID, ALLOCATION_FLOW, PAYMENT_KIND, PRIORITY_NO),
  CONSTRAINT MB_UK_PM_LOAN_ALLOC_COMPONENT UNIQUE
    (PRODUCT_VERSION_ID, ALLOCATION_FLOW, PAYMENT_KIND, COMPONENT_CODE),
  CONSTRAINT MB_CK_PM_LOAN_ALLOC_FLOW CHECK
    (ALLOCATION_FLOW IN ('DEBIT','CREDIT')),
  CONSTRAINT MB_CK_PM_LOAN_ALLOC_KIND CHECK
    (PAYMENT_KIND IN ('REGULAR','PREPAYMENT','RECOVERY')),
  CONSTRAINT MB_CK_PM_LOAN_ALLOC_PRIORITY CHECK (PRIORITY_NO > 0),
  CONSTRAINT MB_CK_PM_LOAN_ALLOC_COMPONENT CHECK
    (COMPONENT_CODE IN ('PENALTY','FEE','INTEREST','PRINCIPAL','UNAPPLIED')),
  CONSTRAINT MB_CK_PM_LOAN_ALLOC_FUTURE CHECK
    (FUTURE_INSTALLMENT_RULE IN ('NEXT_DUE','EARLIEST','LATEST'))
);

-- Fineract installment delinquency/action history, scoped to Moneybags loans.
ALTER TABLE M08_LOAN_DELINQUENCY_SNAPSHOT
  ADD CONSTRAINT MB_UK_LN_DELINQ_SNAP_FACILITY
  UNIQUE (DELINQUENCY_SNAPSHOT_ID, FACILITY_ID);
CREATE TABLE M08_LOAN_DELINQUENCY_ACTION (
  DELINQUENCY_ACTION_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  FACILITY_ID NUMBER(19) NOT NULL REFERENCES M08_LOAN_FACILITY(FACILITY_ID),
  ACTION_CODE VARCHAR2(40 CHAR) NOT NULL,
  REASON_CODE VARCHAR2(50 CHAR) NOT NULL,
  START_DATE DATE NOT NULL,
  END_DATE DATE,
  INSTALLMENT_ID NUMBER(19),
  SOURCE_SNAPSHOT_ID NUMBER(19),
  CREATED_BY VARCHAR2(36 CHAR) NOT NULL,
  CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT MB_FK_LN_DELINQ_ACTION_ITEM FOREIGN KEY (INSTALLMENT_ID, FACILITY_ID)
    REFERENCES M08_LOAN_SCHEDULE_ITEM(SCHEDULE_ITEM_ID, FACILITY_ID),
  CONSTRAINT MB_FK_LN_DELINQ_ACTION_SNAP FOREIGN KEY (SOURCE_SNAPSHOT_ID, FACILITY_ID)
    REFERENCES M08_LOAN_DELINQUENCY_SNAPSHOT(DELINQUENCY_SNAPSHOT_ID, FACILITY_ID),
  CONSTRAINT MB_CK_LN_DELINQ_ACTION_DATES CHECK
    (END_DATE IS NULL OR END_DATE >= START_DATE),
  CONSTRAINT MB_CK_LN_DELINQ_ACTION_CODE CHECK
    (ACTION_CODE IN ('PAUSE','RESUME','REAGE','RESTRUCTURE','MANUAL_REVIEW'))
);
CREATE INDEX M08_IX_LN_DELINQ_ACTION_FACILITY
  ON M08_LOAN_DELINQUENCY_ACTION(FACILITY_ID, START_DATE);

-- These additions are schema contracts. Module 5's posting API still must
-- enforce balanced journals, current funds, holds, idempotency, period close,
-- GL mapping, and same-transaction outbox writes before committing money.
-- Later DDL changes dependencies of these views/triggers. Compile them after
-- the full schema is installed so the greenfield file finishes with valid objects.
ALTER TRIGGER M08_TRG_LN_ALLOCATION_IMMUTABLE COMPILE;
ALTER VIEW M08_V_PAYMENT_ALLOCATION_CONTROL COMPILE;
ALTER VIEW M08_V_SCHEDULE_TOTAL_CONTROL COMPILE;
ALTER TRIGGER M06_TRG_PAYMENT_HISTORY_IMMUTABLE COMPILE;
COMMIT;

-- Confirm table count, foreign keys, and compilation in the current schema.
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE (table_name IN ('M01_IAM_ACCESS_REQUEST',
      'M01_IAM_ACCESS_REQUEST_SCOPE',
      'M01_IAM_AUDIT_EVENT',
      'M01_IAM_AUTH_FACTOR',
      'M01_IAM_CREDENTIAL',
      'M01_IAM_CUSTOMER_LINK',
      'M01_IAM_INBOX_EVENT',
      'M01_IAM_MENU_ITEM',
      'M01_IAM_OUTBOX_EVENT',
      'M01_IAM_PERMISSION',
      'M01_IAM_REFRESH_TOKEN',
      'M01_IAM_ROLE',
      'M01_IAM_ROLE_AUTHORITY',
      'M01_IAM_ROLE_PERMISSION',
      'M01_IAM_SESSION',
      'M01_IAM_USER',
      'M01_IAM_USER_ROLE',
      'M01_IAM_USER_ROLE_SCOPE',
